window.KIRTAN={"collections":[{"id":"cp","title":"Chosath Padi","gu":"ચોસઠ પદી","poet":"Nishkulanand Swami","source":"https://www.anirdesh.com/kavya/chosath-padi/","songs":[{"n":1,"id":"cp-1","name":"Pad 1","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=1","stanzas":[{"id":"cp-1.1","gu":["એક વાત અનુપ અમોલ, કરું છું કહેવાતણું;","પણ મનભાઈ કહે છે મ બોલ, ઘોળ્યું ન કહેવું ઘણું"],"ro":["Ek vaat anup amol, karu chhu kahevaa-tanu;","Pan manbhaai kahe chhe ma bol, gholyu na kahevu ghanu"],"en":"There is one matchless, priceless thing I mean to say. But my mind, like a companion, says, \"Don't speak. Never mind; better not to say too much.\"","gl":[["anup","matchless"],["amol","priceless"],["manbhaai","'brother mind', the mind spoken to as a companion"]],"check":"'gholyu' (ઘોળ્યું) read as a word of dismissal, 'never mind'","no":1,"tek":1},{"id":"cp-1.2","gu":["પણ વણકહ્યે જો વિગત, પડે કેમ પરને;","સંત અસંતમાં એક મત, નિશ્ચે રહે નરને"],"ro":["Pan vankahye jo vigat, pade kem parne;","Sant asantmaa ek mat, nishche rahe narne"],"en":"Yet if it is left unsaid, how will others come to know the particulars? People stay firmly convinced that a Sant and an asant are one and the same.","gl":[["vigat","the particulars"],["asant","one who looks like a Sant but is not"]],"no":2},{"id":"cp-1.3","gu":["માટે કહ્યા વિના ન કળાય, સહુ તે સુણી લહીએ;","મોટા સંતનો કહ્યો મહિમાય, તે સંત કોને કહીએ"],"ro":["Maate kahyaa vinaa na kalaay, sahu te suni lahiye;","Motaa santno kahyo mahimaay, te sant kone kahiye"],"en":"So without being told, it cannot be grasped; let everyone listen and take it in. The mahima of the great Sant has been told, but whom should we call a Sant?","gl":[["kalaay","be grasped"],["lahiye","take in"],["mahimaay","mahima, glory"]],"no":3},{"id":"cp-1.4","gu":["કે’ છે સંત સેવ્યે સરે કાજ, એમ છે આગમમાં;","સુણી નિષ્કુળાનંદ તે આજ, સહુ છે ઉદ્યમમાં"],"ro":["Ke' chhe sant sevye sare kaaj, em chhe aagammaa;","Suni Nishkulanand te aaj, sahu chhe udyammaa"],"chhap":1,"en":"It is said that by serving a Sant one's purpose is fulfilled; so the scriptures say. Hearing this, says Nishkulanand, everyone today is striving.","gl":[["sare kaaj","the purpose is fulfilled"],["aagam","scripture"],["udyam","striving, effort"]],"no":4}]},{"n":2,"id":"cp-2","name":"Pad 2","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=1","stanzas":[{"id":"cp-2.1","gu":["એવા સંત તણી ઓળખાણ, કહું સહુ સાંભળો;","પછી સોંપી તેને મન પ્રાણ, એ વાળે તેમ વળો"],"ro":["Evaa sant tani olkhaan, kahu sahu saambhalo;","Pachhi sompi tene man praan, e vaale tem valo"],"en":"Now all of you, hear how such a Sant is recognised. Then entrust your mind and very life to him, and bend whichever way he bends you.","gl":[["olkhaan","recognition"],["praan","life-breath"],["vaale tem valo","turn as he turns you"]],"no":1,"tek":1},{"id":"cp-2.2","gu":["જેના અંતરમાં અવિનાશ, વાસ કરી વસિયા;","તેણે કામ ક્રોધ પામ્યા નાશ, લોભ ને મોહ ગયા"],"ro":["Jenaa antarmaa avinaash, vaas kari vasiyaa;","Tene kaam krodh paamyaa naash, lobh ne moh gayaa"],"en":"In whose heart the Imperishable has come to live, in him lust and anger have been destroyed, and greed and moha are gone.","gl":[["avinaash","the Imperishable, God"],["kaam krodh","lust, anger"],["lobh","greed"]],"no":2},{"id":"cp-2.3","gu":["એવા શત્રુતણું ટળ્યું સાલ, લાલ જ્યાં આવી રહ્યા;","તેણે સંત થયા છે નિહાલ, પૂરણકામ થયા"],"ro":["Evaa shatru-tanu talyu saal, laal jyaa aavi rahyaa;","Tene sant thayaa chhe nihaal, purankaam thayaa"],"en":"The thorn of such enemies is pulled out where the Beloved has come to stay. Such Sants are fulfilled, with nothing left to want.","gl":[["saal","a thorn, a lodged pain"],["Laal","the Beloved, God"],["nihaal","blessed, fulfilled"],["purankaam","with every wish fulfilled"]],"no":3},{"id":"cp-2.4","gu":["એવા સંત જે હોય સંસાર, શોધીને સેવી લીજીએ;","કહે નિષ્કુળાનંદ નિરધાર, તે લાભ તો લીજીએ"],"ro":["Evaa sant je hoy sansaar, shodhine sevi lijiye;","Kahe Nishkulanand nirdhaar, te laabh to lijiye"],"chhap":1,"en":"If there is such a Sant in the world, seek him out and serve him. Says Nishkulanand with certainty: take that gain.","gl":[["sansaar","the world"],["nirdhaar","with certainty"],["laabh","gain, benefit"]],"no":4}]},{"n":3,"id":"cp-3","name":"Pad 3","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=1","stanzas":[{"id":"cp-3.1","gu":["સાચા સંત સેવ્યે સેવ્યા નાથ, સેવ્યા સુર સહુને;","સેવ્યો મુક્ત મુનિ ઋષિ સાથ, બીજા સેવ્યા બહુને"],"ro":["Saachaa sant sevye sevyaa naath, sevyaa sur sahune;","Sevyo mukt muni rushi saath, bijaa sevyaa bahune"],"en":"By serving a true Sant one has served the Lord and served all the gods; served the muktas, munis and rishis together, and served many others besides.","gl":[["naath","the Lord"],["sur","the gods"],["mukt","the liberated (muktas)"]],"no":1,"tek":1},{"id":"cp-3.2","gu":["એવા સંત જમ્યે જમ્યા શ્યામ, જમ્યા સહુ દેવતા;","જમ્યા સર્વે લોક સરવે ધામ, સહુ થયા ત્રપતા"],"ro":["Evaa sant jamye jamyaa shyaam, jamyaa sahu devtaa;","Jamyaa sarve lok sarve dhaam, sahu thayaa traptaa"],"en":"When such a Sant is fed, Shyam is fed and all the deities are fed; all the worlds and every dham are fed, and all are satisfied.","gl":[["Shyaam","God, the dark-complexioned Lord"],["dhaam","abode"],["traptaa","satisfied"]],"no":2},{"id":"cp-3.3","gu":["એવા સંતને પૂજીને પટ, પ્રીત્યેશું પહેરાવિયાં;","તેણે ઢાંક્યાં છે સહુના ઘટ, ભલાં મન ભાવિયાં"],"ro":["Evaa santne pujine pat, prityeshu paheraaviyaa;","Tene dhaankyaa chhe sahunaa ghat, bhalaa man bhaaviyaa"],"en":"One who worships such a Sant and lovingly clothes him in cloth has covered the bodies of all; this is pleasing indeed.","gl":[["pat","cloth"],["ghat","body (literally, a vessel)"],["bhaaviyaa","were pleasing"]],"check":"'bhalaa man bhaaviyaa': whose mind is pleased (God's, or everyone's) is not explicit","no":3},{"id":"cp-3.4","gu":["એવા સંત મળ્યે મળ્યા સ્વામી, ખામી કોયે ન રહી;","કહે નિષ્કુળાનંદ શીશ નામી, સાચી સહુને કહી"],"ro":["Evaa sant malye malyaa svaami, khaami koye na rahi;","Kahe Nishkulanand shish naami, saachi sahune kahi"],"chhap":1,"en":"Meeting such a Sant, one has met the Swami; nothing at all is left lacking. Bowing his head, says Nishkulanand, I have told everyone the truth.","gl":[["Svaami","the Lord"],["khaami","lack, shortfall"],["shish naami","bowing the head"]],"no":4}]},{"n":4,"id":"cp-4","name":"Pad 4","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=1","stanzas":[{"id":"cp-4.1","gu":["નક્કી વાત છે એ નિરધાર, જૂઠી જરાયે નથી;","સહુ અંતરે કરો વિચાર, ઘણું શું કહું કથી"],"ro":["Nakki vaat chhe e nirdhaar, juthi jaraaye nathi;","Sahu antre karo vichaar, ghanu shu kahu kathi"],"en":"This is settled and certain, not false in the least. Think it over in your hearts, all of you; how much more need I say?","gl":[["nirdhaar","certain"],["kathi","by telling"]],"no":1,"tek":1},{"id":"cp-4.2","gu":["એક જમતાં બોલિયો શંખ, અસંખ્યથી શું સર્યું;","એક જમીને બોલ્યો નિઃશંક, યમુના જાવા કર્યું"],"ro":["Ek jamtaa boliyo shankh, asankhyathi shu saryu;","Ek jamine bolyo nishank, yamunaa jaavaa karyu"],"en":"When one ate, the conch sounded; what came of the countless others? One ate and then declared without doubt, and made the way across the Yamuna.","gl":[["shankh","conch"],["asankhya","countless"],["nishank","without doubt"]],"note":"Two Puranic stories. At the Pandavas' yagna a conch was to sound when a true devotee had eaten; it sounded only for one. Durvasa, after eating the gopis' food, declared he had not eaten, and on that truth the Yamuna gave way for them.","check":"story identifications are from memory; confirm against a commentary","no":2},{"id":"cp-4.3","gu":["એમ એક પૂજ્યે પૂજ્યા સહુ, સેવ્યે સહુ સેવિયા;","માટે ઘણું ઘણું શું કહું, ભેદ ભક્તના કહ્યા"],"ro":["Em ek pujye pujyaa sahu, sevye sahu seviyaa;","Maate ghanu ghanu shu kahu, bhed bhaktanaa kahyaa"],"en":"So by worshipping one, all are worshipped; by serving one, all are served. Why say more and more? I have told what sets a bhakta apart.","gl":[["bhed","the difference, the distinction"]],"no":3},{"id":"cp-4.4","gu":["હવે એવા વિના જે અનેક, જગતમાં જે કહીએ;","કહે નિષ્કુળાનંદ વિવેક, સેવ્યે સુખ શું લહીએ"],"ro":["Have evaa vinaa je anek, jagatmaa je kahiye;","Kahe Nishkulanand vivek, sevye sukh shu lahiye"],"chhap":1,"en":"Now, the many others in the world who are called by that name: says Nishkulanand with vivek, what happiness would one find in serving them?","gl":[["vivek","discernment"],["lahiye","find, gain"]],"no":4}]},{"n":5,"id":"cp-5","name":"Pad 5","section":{"gu":"અસંતનાં લક્ષણ","en":"Marks of an asant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=1","stanzas":[{"id":"cp-5.1","gu":["જેના અંતરમાં કામ ક્રોધ, લોભની લાહ્ય બળે;","એવા બહુ કરતા હોય બોધ, તે સાંભળ્યે શું વળે"],"ro":["Jenaa antarmaa kaam krodh, lobhni laahya bale;","Evaa bahu kartaa hoy bodh, te saambhalye shu vale"],"en":"In whose heart lust and anger and the flame of greed are burning, even if such people preach a great deal, what good comes of listening to them?","gl":[["laahya","flame, burning"],["bodh","teaching, preaching"],["vale","comes of it"]],"no":1,"tek":1},{"id":"cp-5.2","gu":["માન મમતા મત્સર મોહ, ઈરષા અતિ ઘણી;","એવો અધર્મ સર્ગ સમોહ, ધારી રહ્યા જે ધણી"],"ro":["Maan mamtaa matsar moh, irshaa ati ghani;","Evo adharm sarg samoh, dhaari rahyaa je dhani"],"en":"Maan, possessiveness, envy, moha, and jealousy beyond measure: those who carry this whole host of adharma as its owners…","gl":[["mamtaa","possessiveness"],["matsar","envy"],["irshaa","jealousy"],["sarg samoh","the whole array"]],"check":"'dhaari rahyaa je dhani': read as 'who hold it as its masters'; the line runs on into the next stanza","no":2},{"id":"cp-5.3","gu":["તેને સેવતાં શું ફળ થાય, પૂજીને શું પામીએ;","જે જમાડીએ તે પણ જાય, ખાધું જે હરામીએ"],"ro":["Tene sevtaa shu fal thaay, pujine shu paamiye;","Je jamaadiye te pan jaay, khaadhu je haraamiye"],"en":"What fruit comes of serving them, what is gained by worshipping them? Even what you feed them is lost, eaten by the dishonest.","gl":[["fal","fruit, result"],["haraami","dishonest, ungrateful"]],"no":3},{"id":"cp-5.4","gu":["એનાં દર્શન તે દુઃખદેણ, ન થાય તો ન કીજીએ;","સુણી નિષ્કુળાનંદનાં વેણ, સહુ માની લીજીએ"],"ro":["Enaa darshan te dukhden, na thaay to na kijiye;","Suni Nishkulanandnaa ven, sahu maani lijiye"],"chhap":1,"en":"Their darshan brings misery; if you can avoid it, do not have it. Hear these words of Nishkulanand, and let everyone take them to heart.","gl":[["dukhden","giver of misery"],["ven","words"]],"no":4}]},{"n":6,"id":"cp-6","name":"Pad 6","section":{"gu":"અસંતનાં લક્ષણ","en":"Marks of an asant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=1","stanzas":[{"id":"cp-6.1","gu":["એવા વિકારી જનની વાત, દેનારી છે દુઃખની;","જેના અંતરમાં દી’ ને રાત, ઇચ્છા વિષય સુખની"],"ro":["Evaa vikaari janni vaat, denaari chhe dukhni;","Jenaa antarmaa di' ne raat, ichchhaa vishay sukhni"],"en":"The talk of such corrupted people brings misery; day and night their hearts want the pleasures of the senses.","gl":[["vikaari","corrupted, ruled by passions"],["vishay","objects of the senses"]],"no":1,"tek":1},{"id":"cp-6.2","gu":["એને અરથે કરે ઉપાય, શોધી સારા ગામને;","પોતે પોતાનું મા’તમ ગાય, ચા’યે દામ વામને"],"ro":["Ene arthe kare upaay, shodhi saaraa gaamne;","Pote potaanu maa'tam gaay, chaa'ye daam vaamne"],"en":"For that end they make their plans, seeking out good villages; they sing their own mahima, wanting money and women.","gl":[["maa'tam","mahatmya, one's own glory"],["daam","money"],["vaam","woman"]],"no":2},{"id":"cp-6.3","gu":["કરે કથા કીરતન કાવ્ય, અરથ એ સારવા;","ભલો દેખાડે ભક્તિભાવ, પર ઘર મારવા"],"ro":["Kare kathaa kirtan kaavya, arath e saarvaa;","Bhalo dekhaade bhaktibhaav, par ghar maarvaa"],"en":"They do katha, kirtan and poetry to serve that aim; they put on a fine show of bhakti, to rob other people's homes.","gl":[["saarvaa","to accomplish"],["par ghar maarvaa","to plunder others' homes"]],"no":3},{"id":"cp-6.4","gu":["એથી કેદી ન થાય કલ્યાણ, જિજ્ઞાસુને જાણવું;","કહે નિષ્કુળાનંદ નિરવાણ, પેખી પરમાણવું"],"ro":["Ethi kedi na thaay kalyaan, jignaasune jaanvu;","Kahe Nishkulanand nirvaan, pekhi parmaanvu"],"chhap":1,"en":"Through them kalyan never comes; a seeker should know this. Says Nishkulanand, finally: look for yourself and weigh it up.","gl":[["kalyaan","liberation, ultimate good"],["jignaasu","a sincere seeker"],["pekhi parmaanvu","see and judge"]],"check":"'nirvaan' read as 'in conclusion, for certain', not as liberation","no":4}]},{"n":7,"id":"cp-7","name":"Pad 7","section":{"gu":"અસંતનાં લક્ષણ","en":"Marks of an asant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=1","stanzas":[{"id":"cp-7.1","gu":["દેહ પોષવા સારુ જે દંભ, કરે છે જે કુબુદ્ધિ;","ખોટા સુખ અરથે આરંભ, મૂકે નહિ મૂઆ સુધી"],"ro":["Deh poshvaa saaru je dambh, kare chhe je kubuddhi;","Khotaa sukh arthe aarambh, muke nahi muvaa sudhi"],"en":"Those of crooked mind who put on a show of piety to feed the body, who set out after false pleasure and do not let go of it until they die…","gl":[["dambh","hypocrisy, a show of piety"],["kubuddhi","a crooked mind"],["aarambh","undertaking"]],"no":1,"tek":1},{"id":"cp-7.2","gu":["તેણે જનમ પશુને પાડ, ખોયો ખોટા કારણે;","મોક્ષ મારગે દીધાં કમાડ, કડી જડી બારણે"],"ro":["Tene janam pashune paad, khoyo khotaa kaarne;","Moksh maarge didhaa kamaad, kadi jadi baarne"],"en":"They have wasted their birth like a beast's, for a false cause. On the path of moksha they have shut the doors and fastened the latch.","gl":[["kamaad","door panels"],["kadi","latch"]],"check":"'pashune paad' read as 'on a beast's level'","no":2},{"id":"cp-7.3","gu":["ફેરો ન ફાવ્યો થયો ફજીત, જીત ગઈ જળમાં;","મેલી મુક્ત મોટપ્યની રીત, ખ્યાતિ કરી ખળમાં"],"ro":["Fero na faavyo thayo fajit, jit gai jalmaa;","Meli mukt motapyani rit, khyaati kari khalmaa"],"en":"The round of this life did not pay; they were disgraced, and their victory sank in the water. Leaving the dignified ways of the muktas, they won fame among the wicked.","gl":[["fero","the round, this turn of life"],["fajit","disgraced"],["khal","the wicked"]],"check":"'meli mukt motpyani rit': 'leaving the ways of the muktas' greatness'; could also be 'free of the ways of true greatness'","no":3},{"id":"cp-7.4","gu":["આપ ડહાપણે આખો દિવસ, દુઃખે ભર્યો દો’યલો;","કહે નિષ્કુળાનંદ અવસ, ખાટ્યો માલ ખોયલો"],"ro":["Aap dahaapne aakho divas, dukhe bharyo do'yalo;","Kahe Nishkulanand avas, khaatyo maal khoylo"],"chhap":1,"en":"By their own cleverness the whole day is hard and full of misery. Says Nishkulanand: surely, whatever wealth they earned is lost.","gl":[["dahaapan","cleverness"],["do'yalo","hard, difficult"],["avas","surely"]],"check":"'avas' read as 'avashya' (surely); it could be 'avasar' (the opportunity)","no":4}]},{"n":8,"id":"cp-8","name":"Pad 8","section":{"gu":"અસંતનાં લક્ષણ","en":"Marks of an asant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=1","stanzas":[{"id":"cp-8.1","gu":["સંત અસંતની ઓળખાણ, પાડી છે પુરાણમાં;","સુણી સરવે જન સુજાણ, તણાશો મા તાણમાં"],"ro":["Sant asantni olkhaan, paadi chhe puraanmaa;","Suni sarve jan sujaan, tanaasho maa taanmaa"],"en":"How to tell a Sant from an asant is set out in the Puranas. All you wise people, hear it, and don't be swept along in the current.","gl":[["sujaan","the wise"],["taan","the pull, the current"]],"no":1,"tek":1},{"id":"cp-8.2","gu":["જડભરત જનક જયદેવ, એવું થાવું આપણે;","ત્યારે કરતાં અસંતની સેવ, વાત કહો કેમ બણે"],"ro":["Jadbharat Janak Jaydev, evu thaavu aapne;","Tyaare kartaa asantni sev, vaat kaho kem bane"],"en":"Jadbharat, Janak, Jaydev: that is what we are to become. Then tell me, how could it work to serve an asant?","gl":[["Jadbharat","a sage unmoved by the world"],["Janak","a king who lived detached"],["Jaydev","a poet-devotee"]],"no":2},{"id":"cp-8.3","gu":["અતિ આદર્યું કામ અતોલ, પરલોક પામવા;","ત્યારે ખરી કરી જોઈએ ખોળ, વિઘનને વામવા"],"ro":["Ati aadaryu kaam atol, parlok paamvaa;","Tyaare khari kari joiye khol, vighanne vaamvaa"],"en":"We have undertaken a great, immeasurable task: to attain the world beyond. So we must search truly, to clear the obstacles away.","gl":[["atol","immeasurable"],["parlok","the world beyond this one"],["vighan","obstacle"]],"no":3},{"id":"cp-8.4","gu":["વણ સમજે સાર અસાર, પાર કહો કોણ થયા;","કરી નિષ્કુળાનંદ વિચાર, સંત અસંત કહ્યા"],"ro":["Van samje saar asaar, paar kaho kon thayaa;","Kari Nishkulanand vichaar, sant asant kahyaa"],"chhap":1,"en":"Without knowing the essential from the worthless, tell me, who has ever crossed over? Having thought it through, Nishkulanand has described the Sant and the asant.","gl":[["saar asaar","essential and worthless"],["paar","across (the ocean of births)"]],"no":4}]},{"n":9,"id":"cp-9","name":"Pad 9","section":{"gu":"અસંતનાં લક્ષણ","en":"Marks of an asant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=9","stanzas":[{"id":"cp-9.1","gu":["સાચા સંતનાં અંગ એંધાણ રે, જોઈ લેવાં જીવડીએ;","જેને મળવે માન્યું કલ્યાણ રે, તેને જોવા ઘડીઘડીએ"],"ro":["Saachaa santnaa ang endhaan re, joi levaa jivdiye;","Jene malve maanyu kalyaan re, tene jovaa ghadighdiye"],"no":1,"tek":1},{"id":"cp-9.2","gu":["ખાતાં પીતાં જોતાં જણાશે રે, આશય એના અંતરનો;","ઊઠે બેસે બોલે કળાશે રે, પાસે વસતા એ નરનો"],"ro":["Khaataa pitaa jotaa janaashe re, aashay enaa antarno;","Uthe bese bole kalaashe re, paase vastaa e narno"],"no":2},{"id":"cp-9.3","gu":["હશે હારદ હૈયા કેરું રે, વણ કહ્યે પણ વરતાશે;","જેમ જેમ છપાડશે ઘણેરું રે, તેમ તેમ છતું થાશે"],"ro":["Hashe haarad haiyaa keru re, van kahye pan vartaashe;","Jem jem chhapaadshe ghaneru re, tem tem chhatu thaashe"],"no":3},{"id":"cp-9.4","gu":["ખાય ખૂણે લસણ લકીરે, તે ગંધ કરે છુપાવાનું;","કહે નિષ્કુળાનંદ વાત નકી રે, જેમ છે તેમ જણાવાનું"],"ro":["Khaay khune lasan lakire, te gandh kare chhupaavaanu;","Kahe Nishkulanand vaat naki re, jem chhe tem janaavaanu"],"chhap":1,"no":4}]},{"n":10,"id":"cp-10","name":"Pad 10","section":{"gu":"અસંતનાં લક્ષણ","en":"Marks of an asant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=9","stanzas":[{"id":"cp-10.1","gu":["જેવો રસ ભર્યો જે ઠામે રે, તેવો તેમાંથી ઝરશે;","કોઈ કાઢશે પડ્યે કામે રે, નિશ્ચે તેવો નીસરશે"],"ro":["Jevo ras bharyo je thaame re, tevo temaanthi jharshe;","Koi kaadhshe padye kaame re, nishche tevo nisarshe"],"no":1,"tek":1},{"id":"cp-10.2","gu":["જોને આહાર કરે જન જેવો રે, તેવો આવે ઓડકારે;","અણપૂછે નીસરે એવો રે, આશય અંતરનો બા’રે"],"ro":["Jone aahaar kare jan jevo re, tevo aave odkaare;","Anpuchhe nisre evo re, aashay antarno baa're"],"no":2},{"id":"cp-10.3","gu":["જોને ચીલ ચડે આસમાને રે, નજર તેની નીચી છે;","દેખી મારણને મન માને રે, અન્ય જોવા આંખ મીંચી છે"],"ro":["Jone chil chade aasmaane re, najar teni nichi chhe;","Dekhi maaranne man maane re, anya jovaa aankh minchi chhe"],"no":3},{"id":"cp-10.4","gu":["એવા લક્ષણવાળા લાખું રે, દીઠા મેં દગે ભરિયા;","કહે નિષ્કુળાનંદ શું ભાખું રે, ઓળખો એની જોઈ ક્રિયા"],"ro":["Evaa lakshanvaalaa laakhu re, dithaa me dage bhariyaa;","Kahe Nishkulanand shu bhaakhu re, olkho eni joi kriyaa"],"chhap":1,"no":4}]},{"n":11,"id":"cp-11","name":"Pad 11","section":{"gu":"અસંતનાં લક્ષણ","en":"Marks of an asant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=9","stanzas":[{"id":"cp-11.1","gu":["કામી બોલે કામે ભરિયું રે, લોભી બોલે લોભ લઈ;","ક્રોધી બોલે ક્રોધે અનુસરિયું રે, માની બોલે માન સઈ"],"ro":["Kaami bole kaame bhariyu re, lobhi bole lobh lai;","Krodhi bole krodhe anusriyu re, maani bole maan sai"],"no":1,"tek":1},{"id":"cp-11.2","gu":["સ્વાદી બોલે સ્વાદ વખાણી રે, દંભી બોલે દંભ ભરી;","અહંકારી અહંકાર આણી રે, કપટી બોલે કપટ કરી"],"ro":["Svaadi bole svaad vakhaani re, dambhi bole dambh bhari;","Ahankaari ahankaar aani re, kapti bole kapat kari"],"no":2},{"id":"cp-11.3","gu":["માટે જે જનને મળે જેવા રે, તેવો તેને રંગ ચડશે;","નહિ જાય શ્રોતા સારુ લેવા રે, જેમ છે તેમ તેનું જડશે"],"ro":["Maate je janne male jevaa re, tevo tene rang chadshe;","Nahi jaay shrotaa saaru levaa re, jem chhe tem tenu jadshe"],"no":3},{"id":"cp-11.4","gu":["ખૂબ ખરા હોય ખપવાળા રે, તેને જોવું તપાસી;","થાય નિષ્કુળાનંદ સુખાળા રે, ખરી વાત કહું ખાસી"],"ro":["Khub kharaa hoy khapvaalaa re, tene jovu tapaasi;","Thaay Nishkulanand sukhaalaa re, khari vaat kahu khaasi"],"chhap":1,"no":4}]},{"n":12,"id":"cp-12","name":"Pad 12","section":{"gu":"અસંતનાં લક્ષણ","en":"Marks of an asant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=9","stanzas":[{"id":"cp-12.1","gu":["વણ સાધુનો વરતારો રે, આ પદ સુણતાં ઓળખાશે;","પછી શોધી સમાગમ સારો રે, તે સાથે પ્રીતિ થાશે"],"ro":["Van saadhuno vartaaro re, aa pad suntaa olkhaashe;","Pachhi shodhi samaagam saaro re, te saathe priti thaashe"],"no":1,"tek":1},{"id":"cp-12.2","gu":["તેહ વિના મન નહિ માને રે, બીજે દલડું નહિ બેસે;","કાયરની વાતો કાને રે, સાંભળી પંડ્યમાં નહિ પેસે"],"ro":["Teh vinaa man nahi maane re, bije daldu nahi bese;","Kaayarni vaato kaane re, saambhli pandyamaa nahi pese"],"no":2},{"id":"cp-12.3","gu":["આંખ અંતરની ઊઘડશે રે, પડશે પારખું પોતાને;","ખરા ખોટાની ગમ પડશે રે, જડશે વાતો એ જોતાને"],"ro":["Aankh antarni ughadshe re, padshe paarkhu potaane;","Kharaa khotaani gam padshe re, jadshe vaato e jotaane"],"no":3},{"id":"cp-12.4","gu":["પછી સંત અસંત એક પાડે રે, નહિ દેખે તે કોઈ દને;","કહિ નિષ્કુળાનંદ શું દેખાડે રે, જાણશે જેમ છે તેમ મને"],"ro":["Pachhi sant asant ek paade re, nahi dekhe te koi dane;","Kahi Nishkulanand shu dekhaade re, jaanshe jem chhe tem mane"],"chhap":1,"no":4}]},{"n":13,"id":"cp-13","name":"Pad 13","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=9","stanzas":[{"id":"cp-13.1","gu":["જેનું તન મન માન્યું ત્યાગે રે, ભક્તિ ધર્મ ભાવે છે;","તેનાં વચન વીંટ્યાં વૈરાગ્યે રે, અંતરમાંથી આવે છે"],"ro":["Jenu tan man maanyu tyaage re, bhakti dharm bhaave chhe;","Tenaa vachan vintyaa vairaagye re, antarmaanthi aave chhe"],"no":1,"tek":1},{"id":"cp-13.2","gu":["શીલ સંતોષ ને વળી શાંતિ રે, એમાં રહીને બોલે છે;","ધીરજતા કહી નથી જાતી રે, જ્ઞાન ધ્યાનમાં ડોલે છે"],"ro":["Shil santosh ne vali shaanti re, emaa rahine bole chhe;","Dhirajtaa kahi nathi jaati re, gnaan dhyaanmaa dole chhe"],"no":2},{"id":"cp-13.3","gu":["એવા સંત સહુના સગા રે, પર ઉપકારી પૂરા છે;","જેના દલમાં નહિ કોઈ દગા રે, સત્ય વાતમાં શૂરા છે"],"ro":["Evaa sant sahunaa sagaa re, par upkaari puraa chhe;","Jenaa dalmaa nahi koi dagaa re, satya vaatmaa shuraa chhe"],"no":3},{"id":"cp-13.4","gu":["વળી હેત ઘણું છે હૈયે રે, આંખે અમૃત વરસે છે;","કહે નિષ્કુળાનંદ શું કહિયે રે, એ જન જોઈ હરિ હરખે છે"],"ro":["Vali het ghanu chhe haiye re, aankhe amrut varse chhe;","Kahe Nishkulanand shu kahiye re, e jan joi hari harkhe chhe"],"chhap":1,"no":4}]},{"n":14,"id":"cp-14","name":"Pad 14","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=9","stanzas":[{"id":"cp-14.1","gu":["કેને દુઃખ દેવાનો દલમાં રે, ભૂલ્યે ભૂંડો ભાવ નથી;","પર ઉપકારે પળપળમાં રે, ઊપજે ઇચ્છા અંતરથી"],"ro":["Kene dukh devaano dalmaa re, bhulye bhundo bhaav nathi;","Par upkaare palpalmaa re, upje ichchhaa antarthi"],"no":1,"tek":1},{"id":"cp-14.2","gu":["પંચવિષયને પરહરીને રે, વરતે છે વણ વિકારે;","તેહ જણાય જોવે કરીને રે, જન એ બોલે છે જ્યારે"],"ro":["Panchvishayne parahrine re, varte chhe van vikaare;","Teh janaay jove karine re, jan e bole chhe jyaare"],"no":2},{"id":"cp-14.3","gu":["વણ વિચારે પણ વાતું રે, આવે એના અંતરથી;","બોલે અહં મમતાનું ઘસાતું રે, ઊતર્યું મન તનસુખ પરથી"],"ro":["Van vichaare pan vaatu re, aave enaa antarthi;","Bole aham mamtaanu ghasaatu re, utaryu man tansukh parthi"],"no":3},{"id":"cp-14.4","gu":["એવા ક્યાંથી મળે જન એકે રે, નિર્મળ અંતર નિષ્કામી;","કહે નિષ્કુળાનંદ વિવેકે રે, બીજા બહુ હોય હરામી"],"ro":["Evaa kyaanthi male jan eke re, nirmal antar nishkaami;","Kahe Nishkulanand viveke re, bijaa bahu hoy haraami"],"chhap":1,"no":4}]},{"n":15,"id":"cp-15","name":"Pad 15","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=9","stanzas":[{"id":"cp-15.1","gu":["વિષયી જનનાં વાયક રે, ભર્યાં ભરપૂર ભૂંડાઈયે;","હોય સહુને દુઃખદાયક રે, એથી સુખિયાં શું થાયે"],"ro":["Vishyi jannaa vaayak re, bharyaa bharpur bhundaaiye;","Hoy sahune dukhdaayak re, ethi sukhiyaa shu thaaye"],"no":1,"tek":1},{"id":"cp-15.2","gu":["જોને આગ્નીધ્ર દીર્ઘતમા રે, વિષય સારુ વલખ્યા છે;","એનાં વચન શોધી શાસ્ત્રમાં રે, સર્વે લઈને લખ્યાં છે"],"ro":["Jone aagnidhra dirghatmaa re, vishay saaru valakhyaa chhe;","Enaa vachan shodhi shaastramaa re, sarve laine lakhyaa chhe"],"no":2},{"id":"cp-15.3","gu":["વળી વશિષ્ઠ ને દુર્વાસા રે, લોભી ક્રોધી કા’વે છે;","એના અંતરની જે આસા રે, સર્વે શાસ્ત્ર જણાવે છે"],"ro":["Vali vashishth ne durvaasaa re, lobhi krodhi kaa've chhe;","Enaa antarni je aasaa re, sarve shaastra janaave chhe"],"no":3},{"id":"cp-15.4","gu":["માટે જે જનમાં ગુણ જેવો રે, એવો આપે સેવકને;","કહે નિષ્કુળાનંદ ન સેવો રે, જાણી એવા વિવેકને"],"ro":["Maate je janmaa gun jevo re, evo aape sevakne;","Kahe Nishkulanand na sevo re, jaani evaa vivekne"],"chhap":1,"no":4}]},{"n":16,"id":"cp-16","name":"Pad 16","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=9","stanzas":[{"id":"cp-16.1","gu":["કહ્યાં ખટ દશ પદ આ ખોળી રે, સહુ જનને સમજાવાને;","કહ્યું તન મનમાં મેં તોળી રે, જેમ છે તેમ જણાવાને"],"ro":["Kahyaa khat dash pad aa kholi re, sahu janne samjaavaane;","Kahyu tan manmaa me toli re, jem chhe tem janaavaane"],"no":1,"tek":1},{"id":"cp-16.2","gu":["કોઈ પીયૂષ રસને પાઈ રે, ઉછેરે નર ઉરગને;","તોય નિરવિખ તે ન થાય રે, વાધે વિખ એના અંગને"],"ro":["Koi piyush rasne paai re, uchhere nar uragne;","Toy nirvikh te na thaay re, vaadhe vikh enaa angne"],"no":2},{"id":"cp-16.3","gu":["જોને જેવો ગુણ જે બીજે રે, તેવો તેહ જણાવે છે;","તેની કોટિ જતન જો કીજે રે, તોય તે શું બદલાવે છે"],"ro":["Jone jevo gun je bije re, tevo teh janaave chhe;","Teni koti jatan jo kije re, toy te shu badlaave chhe"],"no":3},{"id":"cp-16.4","gu":["એવા ઝેરીલા જન જાણી રે, તરત તેને તજી દેવા;","સુણી નિષ્કુળાનંદની વાણી રે, શુદ્ધ સંતની કરીયે સેવા"],"ro":["Evaa jherilaa jan jaani re, tarat tene taji devaa;","Suni Nishkulanandni vaani re, shuddh santni kariye sevaa"],"chhap":1,"no":4}]},{"n":17,"id":"cp-17","name":"Pad 17","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=17","stanzas":[{"id":"cp-17.1","gu":["કઠણ વચન કહું છું રે, કડવાં કાંકચ્ય રૂપ;","દરદીને ગોળી દઉં છું રે, સુખ થાવા અનૂપ"],"ro":["Kathan vachan kahu chhu re, kadvaa kaankachya rup;","Dardine goli dau chhu re, sukh thaavaa anup"],"no":1,"tek":1},{"id":"cp-17.2","gu":["ખરે મને જે જન ખાવશે રે, આવું જે ઔષદ;","જીરણ રોગ તેનો જાવશે રે, સુખી થાશે સદ"],"ro":["Khare mane je jan khaavshe re, aavu je aushad;","Jiran rog teno jaavshe re, sukhi thaashe sad"],"no":2},{"id":"cp-17.3","gu":["પણ બીક રહે છે બોલતાં રે, સાચી દેતાં શિખ;","ખરાં છિદ્ર કેનાં ખોલતાં રે, વવાઈ જાશે વિખ"],"ro":["Pan bik rahe chhe boltaa re, saachi detaa shikh;","Kharaa chhidra kenaa kholtaa re, vavaai jaashe vikh"],"no":3},{"id":"cp-17.4","gu":["દેહ માનીને દલમાં રે, સુણતાં જાશે સુખ;","પ્રજળશે તેહ પળમાં રે, દાઝ્યે થાશે દુઃખ"],"ro":["Deh maanine dalmaa re, suntaa jaashe sukh;","Prajalshe teh palmaa re, daajhye thaashe dukh"],"no":4},{"id":"cp-17.5","gu":["માટે કહું ન કહું કોઈને રે, એમ આવે વિચાર;","નિષ્કુળાનંદ વિચારી જોઈને રે, પછી કરું ઉચ્ચાર"],"ro":["Maate kahu na kahu koine re, em aave vichaar;","Nishkulanand vichaari joine re, pachhi karu uchchaar"],"chhap":1,"no":5}]},{"n":18,"id":"cp-18","name":"Pad 18","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=17","stanzas":[{"id":"cp-18.1","gu":["સુણો સાધુ શુકજી સરખા રે, નારદ જેવા નેક;","નથી ઉપમાં માનો મૂરખા રે, ઉર કરો વિવેક"],"ro":["Suno saadhu Shukji sarkhaa re, naarad jevaa nek;","Nathi upmaa maano murkhaa re, ur karo vivek"],"no":1,"tek":1},{"id":"cp-18.2","gu":["જડભરત જેવા જાણીએ રે, સનકાદિક સમાન;","કદરજ જેવા વખાણીએ રે, ખરા ક્ષમાવાન"],"ro":["Jadbharat jevaa jaaniye re, sankaadik samaan;","Kadraj jevaa vakhaaniye re, kharaa kshamaavaan"],"no":2},{"id":"cp-18.3","gu":["એવી સાધુતાને આશરી રે, જ્યારે લીધો જોગ;","ત્યારે પ્રીત સહુશું પરહરી રે, ભૂલવા ભવ ભોગ"],"ro":["Evi saadhutaane aashri re, jyaare lidho jog;","Tyaare prit sahushu parahri re, bhulvaa bhav bhog"],"no":3},{"id":"cp-18.4","gu":["એની રીત્યે રીત્ય આપણી રે, બીજી રીત્યે બાધ;","પરહરો પરી પાપણી રે, વળગી એ વરાધ"],"ro":["Eni ritye ritya aapni re, biji ritye baadh;","Parahro pari paapni re, valgi e varaadh"],"no":4},{"id":"cp-18.5","gu":["ફોગટ પડતાં બીજા ફંદમા રે, આવે દુઃખ અત્યંત;","નિષ્કુળાનંદ આનંદમાં રે, સદા રહોને સંત"],"ro":["Fogat padtaa bijaa fandmaa re, aave dukh atyant;","Nishkulanand aanandmaa re, sadaa rahone sant"],"chhap":1,"no":5}]},{"n":19,"id":"cp-19","name":"Pad 19","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=17","stanzas":[{"id":"cp-19.1","gu":["શુકજીએ નથી સંઘર્યું રે, ધાતુ વળી ધન;","નાણું નારદે ભેળું ન કર્યું રે, કહે છે કોયે દન"],"ro":["Shukjiye nathi sangharyu re, dhaatu vali dhan;","Naanu naarde bhelu na karyu re, kahe chhe koye dan"],"no":1,"tek":1},{"id":"cp-19.2","gu":["જડભરતે ન જોડાવિયું રે, ગાડું ગાડી વેલ;","કદરજનું વ્યાસે કા’વિયું રે, ખરી ક્ષમાનો ખેલ"],"ro":["Jadbharte na jodaaviyu re, gaadu gaadi vel;","Kadrajnu vyaase kaa'viyu re, khari kshamaano khel"],"no":2},{"id":"cp-19.3","gu":["સનકાદિકે સુખ કારણે રે, ઘોડું ન રાખ્યું ઘેર;","આ તો બાંધ્યાં બીજાને બારણે રે, કરવા કાળો કે’ર"],"ro":["Sankaadike sukh kaarne re, ghodu na raakhyu gher;","Aa to baandhyaa bijaane baarne re, karvaa kaalo ke'ra"],"no":3},{"id":"cp-19.4","gu":["મેલી ઊભી અસલ રીતને રે, નકલ લીધી નેક;","તે તો ચોંટી ગઈ ચિત્તને રે, છોડી ન છૂટે છેક"],"ro":["Meli ubhi asal ritne re, nakal lidhi nek;","Te to chonti gai chittane re, chhodi na chhute chhek"],"no":4},{"id":"cp-19.5","gu":["કોઈ કહે એની કોરનું રે, તે શું બંધાયે વેર;","કહે નિષ્કુળાનંદ નોરનું રે, મું પર રાખજો મે’ર"],"ro":["Koi kahe eni kornu re, te shu bandhaaye ver;","Kahe Nishkulanand nornu re, mu par raakhjo me'ra"],"chhap":1,"no":5}]},{"n":20,"id":"cp-20","name":"Pad 20","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=17","stanzas":[{"id":"cp-20.1","gu":["જરૂર જાવું છે જાણજો રે, પ્રભુજીની પાસ;","એવી દેશીયે મ આણજો રે, વણ કર્યે તપાસ"],"ro":["Jarur jaavu chhe jaanjo re, prabhujini paas;","Evi deshiye ma aanjo re, van karye tapaas"],"no":1,"tek":1},{"id":"cp-20.2","gu":["જાણો જગ મોટાઈ જૂઠ છે રે, તેની તજો તાણ;","એને ઇચ્છે તે હૈયાફૂટ છે રે, ન ઇચ્છે સુજાણ"],"ro":["Jaano jag motaai juth chhe re, teni tajo taan;","Ene ichchhe te haiyaafut chhe re, na ichchhe sujaan"],"no":2},{"id":"cp-20.3","gu":["મેલો લાભ આ લોક સુખનો રે, પ્રીત કરો પરલોક;","એ તો મતો છે મૂરખનો રે, ખોટો હરખ શોક"],"ro":["Melo laabh aa lok sukhno re, prit karo parlok;","E to mato chhe murakhno re, khoto harakh shok"],"no":3},{"id":"cp-20.4","gu":["રૂડા સંતની રીતડી રે, જાણો જુદી જન;","જેને પ્રભુ સાથે પ્રીતડી રે, તે વિચારો મન"],"ro":["Rudaa santni ritdi re, jaano judi jan;","Jene prabhu saathe pritdi re, te vichaaro man"],"no":4},{"id":"cp-20.5","gu":["માથે કલંક ને મરશું રે, એ તો છે અકાજ;","તે તો નિષ્કુળાનંદ નરસું રે, જોઈ રીઝે નહિ રાજ"],"ro":["Maathe kalank ne marshu re, e to chhe akaaj;","Te to Nishkulanand narsu re, joi rijhe nahi raaj"],"chhap":1,"no":5}]},{"n":21,"id":"cp-21","name":"Pad 21","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=17","stanzas":[{"id":"cp-21.1","gu":["શોધી આવ્યો તું સતસંગમાં રે, ભજવાને ભગવાન;","આવ્યો તૈંયેં તારા અંગમાં રે, નો’તા મોટપ માન"],"ro":["Shodhi aavyo tu satsangmaa re, bhajvaane bhagvaan;","Aavyo tainye taaraa angmaa re, no'taa motap maan"],"no":1,"tek":1},{"id":"cp-21.2","gu":["સહુ સંતને શીશ નામતો રે, થઈને દાસાનુદાસ;","ગુણ ગોવિંદજીના ગાવતો રે, જગથી થઈ ઉદાસ"],"ro":["Sahu santne shish naamto re, thaine daasaanudaas;","Gun govindjinaa gaavto re, jagthi thai udaas"],"no":2},{"id":"cp-21.3","gu":["એહ ગયું તારી ગાંઠનું રે, બીજું પેઠું પાપ;","લઈ લીધું લક્ષણ લાંઠનું રે, અવળું કર્યું આપ"],"ro":["Eh gayu taari gaanthnu re, biju pethu paap;","Lai lidhu lakshan laanthnu re, avlu karyu aap"],"no":3},{"id":"cp-21.4","gu":["બની વાત ગઈ બગડી રે, કવથાણું છે કામ;","દિલે સળગે છે સગડી રે, સહુનો થાવા શ્યામ"],"ro":["Bani vaat gai bagdi re, kavthaanu chhe kaam;","Dile salge chhe sagdi re, sahuno thaavaa shyaam"],"no":4},{"id":"cp-21.5","gu":["નાને ગુણે મોટપ ન મળે રે, વિચારી જોને વાત;","કહે નિષ્કુળાનંદ કાં બળે રે, ઠાલો દી’ ને રાત"],"ro":["Naane gune motap na male re, vichaari jone vaat;","Kahe Nishkulanand kaa bale re, thaalo di' ne raat"],"chhap":1,"no":5}]},{"n":22,"id":"cp-22","name":"Pad 22","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=17","stanzas":[{"id":"cp-22.1","gu":["મોટા થાવાનું મનમાં રે, દલમાં ઘણો ડોડ;","તેવા ગુણ નથી તનમાં રે, કાં કરે તું કોડ"],"ro":["Motaa thaavaanu manmaa re, dalmaa ghano dod;","Tevaa gun nathi tanmaa re, kaa kare tu kod"],"no":1,"tek":1},{"id":"cp-22.2","gu":["તું તપાસી જોને તુજને રે, ઊતરી અંતર માંય;","પછી ઇચ્છજે થાવા પૂજ્યને રે, તેનું નથી કાંય"],"ro":["Tu tapaasi jone tujne re, utri antar maany;","Pachhi ichchhaje thaavaa pujyane re, tenu nathi kaany"],"no":2},{"id":"cp-22.3","gu":["કામ ક્રોધ વળી લોભ છે રે, લિયે છે તારી લાજ;","તેણે કરી અંતરે ક્ષોભ છે રે, જો વિચારી આજ"],"ro":["Kaam krodh vali lobh chhe re, liye chhe taari laaj;","Tene kari antre kshobh chhe re, jo vichaari aaj"],"no":3},{"id":"cp-22.4","gu":["ભૂંડા ઘાટ ઊઠે છે ભીતરે રે, જે ન કહેવાય બા’ર;","એહ વાતનો તારે અંતરે રે, નથી નર વિચાર"],"ro":["Bhundaa ghaat uthe chhe bhitre re, je na kahevaay baa'ra;","Eh vaatno taare antre re, nathi nar vichaar"],"no":4},{"id":"cp-22.5","gu":["નથી ખોળતો ખોટ્ય માંયની રે, દે છે બીજાને દોષ;","કહે નિષ્કુળાનંદ ન્યાયની રે, અમથો શો અપસોષ"],"ro":["Nathi kholto khotya maanyni re, de chhe bijaane dosh;","Kahe Nishkulanand nyaayni re, amtho sho apsosh"],"chhap":1,"no":5}]},{"n":23,"id":"cp-23","name":"Pad 23","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=17","stanzas":[{"id":"cp-23.1","gu":["એક ભૂંસાડીને એકડો રે, વાળ્યાં મીંડા વીશ;","જોતાં સરવાળો ન જડ્યો રે, ત્યારે કરે છે રીશ"],"ro":["Ek bhunsaadine ekdo re, vaalyaa mindaa vish;","Jotaa sarvaalo na jadyo re, tyaare kare chhe rish"],"no":1,"tek":1},{"id":"cp-23.2","gu":["ધન વિના કરે છે ધાંખના રે, કાંઈક મળવા કાજ;","પામીશ નહિ પડીકાં રાખનાં રે, ઠાલી ખોઈશ લાજ"],"ro":["Dhan vinaa kare chhe dhaankhnaa re, kaanik malvaa kaaj;","Paamish nahi padikaa raakhnaa re, thaali khoish laaj"],"no":2},{"id":"cp-23.3","gu":["દીવો દિનકર આગળે રે, કરવા જાયે કોય;","શોભા શું લખાય કાગળે રે, ઊલટી હાંસી હોય"],"ro":["Divo dinkar aagle re, karvaa jaaye koy;","Shobhaa shu lakhaay kaagle re, ulti haansi hoy"],"no":3},{"id":"cp-23.4","gu":["મોટા પંડિત આગે મૂરખો રે, કરે કોય ઉચ્ચાર;","સહુ જાણે પશુ સરખો રે, ભૂલ્યે ન પડે ભાર"],"ro":["Motaa pandit aage murkho re, kare koy uchchaar;","Sahu jaane pashu sarkho re, bhulye na pade bhaar"],"no":4},{"id":"cp-23.5","gu":["માંડી મોર કળા સોહામણી રે, પછી દેખાડે પૂંઠ;","નિષ્કુળાનંદ લાગે લજામણી રે, જરાય નથી જૂઠ"],"ro":["Maandi mor kalaa sohaamni re, pachhi dekhaade punth;","Nishkulanand laage lajaamni re, jaraay nathi juth"],"chhap":1,"no":5}]},{"n":24,"id":"cp-24","name":"Pad 24","section":{"gu":"સંતનાં લક્ષણ","en":"Marks of a Sant"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=17","stanzas":[{"id":"cp-24.1","gu":["વાત હેતની હૈયે ધારજો રે, સમજીને સુજાણ;","કામ પડે એ વિચારજો રે, તો થાશે કલ્યાણ"],"ro":["Vaat hetni haiye dhaarjo re, samjine sujaan;","Kaam pade e vichaarjo re, to thaashe kalyaan"],"no":1,"tek":1},{"id":"cp-24.2","gu":["પ્રભુજીનાં પદ પામવા રે, આ છે સુંદર સાર;","વડાં વિઘનને વામવા રે, પામવા બેડો પાર"],"ro":["Prabhujinaa pad paamvaa re, aa chhe sundar saar;","Vadaa vighanne vaamvaa re, paamvaa bedo paar"],"no":2},{"id":"cp-24.3","gu":["કહ્યું લગાડીને કડવું રે, લીમથી ઘણું લાખ;","એમ કહીને નો’તું લડવું રે, સહુ પૂરશે સાખ"],"ro":["Kahyu lagaadine kadvu re, limthi ghanu laakh;","Em kahine no'tu ladvu re, sahu purshe saakh"],"no":3},{"id":"cp-24.4","gu":["કોઈ વીંધે આવી કાનને રે, કરીને કળ છળ;","પણ સમજો તેના તાનને રે, પે’રાવશે કુંડળ"],"ro":["Koi vindhe aavi kaanne re, karine kal chhal;","Pan samjo tenaa taanne re, pe'raavshe kundal"],"no":4},{"id":"cp-24.5","gu":["રૂડું આપણી જે રીતનું રે, શોધી કહ્યું સાર;","કહ્યું નિષ્કુળાનંદે હિતનું રે, સારું સુખ દેનાર"],"ro":["Rudu aapni je ritnu re, shodhi kahyu saar;","Kahyu Nishkulanandે hitnu re, saaru sukh denaar"],"chhap":1,"no":5}]},{"n":25,"id":"cp-25","name":"Pad 25","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=25","stanzas":[{"id":"cp-25.1","gu":["માનો મળી છે મોટી વાત, હાથ આવી તે મા હારજો રે;","કરી જતન દિવસ રાત, સૂતાં બેઠાં સંભારજો રે"],"ro":["Maano mali chhe moti vaat, haath aavi te maa haarjo re;","Kari jatan divas raat, sutaa bethaa sambhaarjo re"],"no":1,"tek":1},{"id":"cp-25.2","gu":["સાચો મળ્યો છે સતસંગ, અંગે અચળ કરી રાખજો રે;","રખે ચડે બીજાનો રંગ, એવું ડહાપણ દૂર નાખજો રે"],"ro":["Saacho malyo chhe satsang, ange achal kari raakhjo re;","Rakhe chade bijaano rang, evu dahaapan dur naakhjo re"],"no":2},{"id":"cp-25.3","gu":["લઈ બેઠા છો મોટો લાભ, ભેટી પૂરણ બ્રહ્મને રે;","નહિ તો દુઃખનો ઊગત ડાભ, માની લેજો એ મર્મને રે"],"ro":["Lai bethaa chho moto laabh, bheti puran brahmane re;","Nahi to dukhno ugat daabh, maani lejo e marmane re"],"no":3},{"id":"cp-25.4","gu":["આજ પામ્યા છો આનંદ, વામ્યા દારુણ દુઃખને રે;","એમ કહે નિષ્કુળાનંદ, રખે મૂકતા એવા સુખને રે"],"ro":["Aaj paamyaa chho aanand, vaamyaa daarun dukhne re;","Em kahe Nishkulanand, rakhe muktaa evaa sukhne re"],"chhap":1,"no":4}]},{"n":26,"id":"cp-26","name":"Pad 26","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=25","stanzas":[{"id":"cp-26.1","gu":["ઘણા મોંઘા જે ઘનશ્યામ, નાવે નજરે ન મળે કોઈને રે;","અક્ષરવાસી આઠું જામ, જેને રહ્યા છે અખંડ જોઈને રે"],"ro":["Ghanaa monghaa je Ghanshyaam, naave najre na male koine re;","Aksharvaasi aathu jaam, jene rahyaa chhe akhand joine re"],"no":1,"tek":1},{"id":"cp-26.2","gu":["અતિ થઈને દીન આધીન, નિત્ય નમાવે છે શીશને રે;","લગ્નિ લગાડી લેલીન, જોઈ રહ્યા છે જગદીશને રે"],"ro":["Ati thaine din aadhin, nitya namaave chhe shishne re;","Lagni lagaadi lelin, joi rahyaa chhe jagdishne re"],"no":2},{"id":"cp-26.3","gu":["એવા મુક્તને મળવા કાજ, મોટા ઇચ્છે છે મનમાં રે;","શિવ બ્રહ્મા ને સુરરાજ, તે તો તલસે છે તનમાં રે"],"ro":["Evaa muktane malvaa kaaj, motaa ichchhe chhe manmaa re;","Shiv brahmaa ne surraaj, te to talse chhe tanmaa re"],"no":3},{"id":"cp-26.4","gu":["એવા દેવતાના દર્શન, થાતાં નથી થોડી વાતમાં રે;","નિષ્કુળાનંદ વિચારો મન, આવો રહસ્ય બેસી એકાંતમાં રે"],"ro":["Evaa devtaanaa darshan, thaataa nathi thodi vaatmaa re;","Nishkulanand vichaaro man, aavo rahasya besi ekaantmaa re"],"chhap":1,"no":4}]},{"n":27,"id":"cp-27","name":"Pad 27","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=25","stanzas":[{"id":"cp-27.1","gu":["કિયાં જીવ કિયાં જગદીશ, જાણો જૂજવી એ જાત છે રે;","મર આપિયે સો સો શીશ, તોયે વણ મળ્યાની વાત છે રે"],"ro":["Kiyaa jiv kiyaa jagdish, jaano jujvi e jaat chhe re;","Mar aapiye so so shish, toye van malyaani vaat chhe re"],"no":1,"tek":1},{"id":"cp-27.2","gu":["કિયાં કીડી કરી મેળાપ, ભેળું થાવા ભારે ભેદ છે રે;","કિયાં પૂર્ણ પુરુષોત્તમ આપ, કિયાં જીવ જેને બહુ કેદ છે રે"],"ro":["Kiyaa kidi kari melaap, bhelu thaavaa bhaare bhed chhe re;","Kiyaa purn Purushottam aap, kiyaa jiv jene bahu ked chhe re"],"no":2},{"id":"cp-27.3","gu":["અતિ અણમળ્યાનું એહ, મળવું માયિક અમાયિકને રે;","તે તો દયા કરી ધરી દેહ, આવે ઉદ્ધારવા અનેકને રે"],"ro":["Ati anmalyaanu eh, malvu maayik amaayikne re;","Te to dayaa kari dhari deh, aave uddhaarvaa anekne re"],"no":3},{"id":"cp-27.4","gu":["તૈંયેં થાય એનો મેળાપ, જ્યારે નરતન ધરે નાથજી રે;","કહે નિષ્કુળાનંદ આપ, ત્યારે મળાય એને સાથજી રે"],"ro":["Tainye thaay eno melaap, jyaare nartan dhare naathji re;","Kahe Nishkulanand aap, tyaare malaay ene saathji re"],"chhap":1,"no":4}]},{"n":28,"id":"cp-28","name":"Pad 28","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=25","stanzas":[{"id":"cp-28.1","gu":["એવા મળ્યા છે મહારાજ, જે કોઈ સર્વેના શ્યામ છે રે;","વળી રાજા એ અધિરાજ, એને આધારે સૌ ધામ છે રે"],"ro":["Evaa malyaa chhe mahaaraaj, je koi sarvenaa shyaam chhe re;","Vali raajaa e adhiraaj, ene aadhaare sau dhaam chhe re"],"no":1,"tek":1},{"id":"cp-28.2","gu":["ધામ ધામના જે રહેનાર, હજૂર રહે છે જોડી હાથને રે;","કરી આરત્ય શું ઉચ્ચાર, શીશ નમાવે છે નાથને રે"],"ro":["Dhaam dhaamnaa je rahenaar, hajur rahe chhe jodi haathne re;","Kari aaratya shu uchchaar, shish namaave chhe naathne re"],"no":2},{"id":"cp-28.3","gu":["શિવ બ્રહ્મા ને સુરેશ, દેવ અદેવ રહે છે ડરતા રે;","જેની આજ્ઞામાં અહોનિશ, શશી સૂરજ રહે છે ફરતા રે"],"ro":["Shiv brahmaa ne suresh, dev adev rahe chhe dartaa re;","Jeni aagnaamaa ahonish, shashi suraj rahe chhe fartaa re"],"no":3},{"id":"cp-28.4","gu":["કંપે કાળ માયા મનમાંય, અતિ ઘણું અંતરમાં રે;","કહે નિષ્કુળાનંદ કાંય, તું પણ ડરને તેના ડરમાં રે"],"ro":["Kampe kaal maayaa manmaany, ati ghanu antarmaa re;","Kahe Nishkulanand kaany, tu pan darne tenaa darmaa re"],"chhap":1,"no":4}]},{"n":29,"id":"cp-29","name":"Pad 29","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=25","stanzas":[{"id":"cp-29.1","gu":["એની આગળ જો આપણ, કોણ ગણતીમાં આવીએ રે;","શીદ ડો’ળીને ડહાપણ, સમજુ શિયાણા હસાવીયે રે"],"ro":["Eni aagal jo aapan, kon gantimaa aaviye re;","Shid do'line dahaapan, samju shiyaanaa hasaaviye re"],"no":1,"tek":1},{"id":"cp-29.2","gu":["જેણે રચ્યું આ જગત, જોને જૂજવી જાત્યનું રે;","જોતા મૂંઝાય જાય મત, એવુ કર્યું ભાત ભાતનું રે"],"ro":["Jene rachyu aa jagat, jone jujvi jaatyanu re;","Jotaa munjhaay jaay mat, evu karyu bhaat bhaatnu re"],"no":2},{"id":"cp-29.3","gu":["એણે કર્યું એવું એક, થાય નહિ જરૂર જાણીએ રે;","વણકર્યે એ વિવેક, શીદ અભિમાન આણીએ રે"],"ro":["Ene karyu evu ek, thaay nahi jarur jaaniye re;","Vankarye e vivek, shid abhimaan aaniye re"],"no":3},{"id":"cp-29.4","gu":["મેલી ડા’પણ ભોળાપણ, રહીએ દાસના દાસ થઈને રે;","કહે નિષ્કુળાનંદ આપણ, તો બેસિયે લાભ લઈને રે"],"ro":["Meli daa'pan bholaapan, rahiye daasnaa daas thaine re;","Kahe Nishkulanand aapan, to besiye laabh laine re"],"chhap":1,"no":4}]},{"n":30,"id":"cp-30","name":"Pad 30","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=25","stanzas":[{"id":"cp-30.1","gu":["જે જે હરિએ કર્યું હેત, એવું કરે કોણ આપણે રે;","માત તાત સગાં સમેત, માન્યા સનેહી ભોળાપણે રે"],"ro":["Je je hariye karyu het, evu kare kon aapne re;","Maat taat sagaa samet, maanyaa sanehi bholaapne re"],"no":1,"tek":1},{"id":"cp-30.2","gu":["જોને ગર્ભવાસની ત્રાસ, ટળી ટળે કેમ કોયની રે;","તે પણ ટાળીને અવિનાશ, રાખે ખબર અન્ન તોયની રે"],"ro":["Jone garbhavaasni traas, tali tale kem koyni re;","Te pan taaline avinaash, raakhe khabar ann toyni re"],"no":2},{"id":"cp-30.3","gu":["વળી સમે સમે સંભાળ, જાણો કરે હરિજનને રે;","બીજુ એવું કોણ દયાળ, કાં રે મનાય નહિ મનને રે"],"ro":["Vali same same sambhaal, jaano kare harijanne re;","Biju evu kon dayaal, kaa re manaay nahi manne re"],"no":3},{"id":"cp-30.4","gu":["એમ સમજ્યા વિના જન, આવે ઉન્મત્તાઈ અંગમાં રે;","કહે નિષ્કુળાનંદ વચન, પછી મન માને કુસંગમાં રે"],"ro":["Em samajyaa vinaa jan, aave unmattaai angmaa re;","Kahe Nishkulanand vachan, pachhi man maane kusangmaa re"],"chhap":1,"no":4}]},{"n":31,"id":"cp-31","name":"Pad 31","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=25","stanzas":[{"id":"cp-31.1","gu":["જ્યારે ગણ્યો પોતામાં ગુણ, જાણ્યું હું પણ છૌં કોઈ કામનો રે;","ત્યારે કો’ને વધ્યો કુણ, લેતાં આશરો સુંદર શ્યામનો રે"],"ro":["Jyaare ganyo potaamaa gun, jaanyu hu pan chhau koi kaamno re;","Tyaare ko'ne vadhyo kun, letaa aashro sundar shyaamno re"],"no":1,"tek":1},{"id":"cp-31.2","gu":["જ્યારે કરી દીનતા ત્યાગ, અંગે લીધો અહંકારને રે;","ત્યારે મળ્યો માયાને લાગ, ખરો કરવા ખુવારને રે"],"ro":["Jyaare kari dintaa tyaag, ange lidho ahankaarne re;","Tyaare malyo maayaane laag, kharo karvaa khuvaarne re"],"no":2},{"id":"cp-31.3","gu":["પછી પ્રભુ પામવા કાજ, જે જે કર્યું’તું આ જગમાં રે;","તે તો સર્વે ખોયો સાજ, પડ્યો ઠાઉકો જઈ ઠગમાં રે"],"ro":["Pachhi prabhu paamvaa kaaj, je je karyu'tu aa jagmaa re;","Te to sarve khoyo saaj, padyo thaauko jai thagmaa re"],"no":3},{"id":"cp-31.4","gu":["એવા મૂરખની મિરાત, એને અર્થે નથી આવતી રે;","કહે નિષ્કુળાનંદ વાત, હરિભક્તને મન ભાવતી રે"],"ro":["Evaa murakhni miraat, ene arthe nathi aavti re;","Kahe Nishkulanand vaat, haribhaktane man bhaavti re"],"chhap":1,"no":4}]},{"n":32,"id":"cp-32","name":"Pad 32","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=25","stanzas":[{"id":"cp-32.1","gu":["આવી અરથની જે વાત, કોય નર ઉતારે અંગમાં રે;","ત્યારે સુખી થાય સાક્ષાત, પછી સમજી રે’ સત્સંગમાં રે"],"ro":["Aavi arathni je vaat, koy nar utaare angmaa re;","Tyaare sukhi thaay saakshaat, pachhi samji re' satsangmaa re"],"no":1,"tek":1},{"id":"cp-32.2","gu":["થઈ ગરીબ ને ગર્જવાન, શિષ્ય થઈ રહે સર્વનો રે;","મેલી મમતા ને માન, ત્યાગ કરે તન ગર્વનો રે"],"ro":["Thai garib ne garjavaan, shishya thai rahe sarvano re;","Meli mamtaa ne maan, tyaag kare tan garvano re"],"no":2},{"id":"cp-32.3","gu":["ખોળી ખોટ્ય ન રાખે કાંઈ, ભલી ભક્તિ ભજાવવા રે;","એક રહે અંતરમાંઈ તાન, પ્રભુને રીઝાવવા રે"],"ro":["Kholi khotya na raakhe kaani, bhali bhakti bhajaavvaa re;","Ek rahe antarmaani taan, prabhune rijhaavvaa re"],"no":3},{"id":"cp-32.4","gu":["એવા ઉપર શ્રી ઘનશ્યામ, સદા સર્વદા રાજી રહે છે રે;","સરે નિષ્કુળાનંદ કામ, એમ સર્વે સંત કહે છે રે"],"ro":["Evaa upar shri Ghanshyaam, sadaa sarvadaa raaji rahe chhe re;","Sare Nishkulanand kaam, em sarve sant kahe chhe re"],"chhap":1,"no":4}]},{"n":33,"id":"cp-33","name":"Pad 33","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=33","stanzas":[{"id":"cp-33.1","gu":["કો’ તો વળી કહું એક વાત, સુણજ્યો સહુ મળી;","છે જો સાંભળ્યા જેવી સાક્ષાત, વા’લપે કહું વળી"],"ro":["Ko' to vali kahu ek vaat, sunajyo sahu mali;","Chhe jo saambhalyaa jevi saakshaat, vaa'lape kahu vali"],"no":1,"tek":1},{"id":"cp-33.2","gu":["જેમ નરદેવ દઈને દંડ, વેરીને વશ્ય કરે;","લિયે ખાટી તે સર્વે ખંડ, દુષ્ટ તે સરવે ડરે"],"ro":["Jem nardev daine dand, verine vashya kare;","Liye khaati te sarve khand, dusht te sarve dare"],"no":2},{"id":"cp-33.3","gu":["તેમ પ્રગટી પૂરણબ્રહ્મ, સંતના શત્રુ હણ્યા;","કામ ક્રોધ લોભ જે વિષમ, તે તૃણ તુલ્ય ગણ્યા"],"ro":["Tem pragti purnabrahm, santnaa shatru hanyaa;","Kaam krodh lobh je visham, te trun tulya ganyaa"],"no":3},{"id":"cp-33.4","gu":["સ્વાદ સ્નેહ મમતા માન, પાપી પારોઠા કીધા;","કહે નિષ્કુળાનંદ નિદાન, નિજ જન તારી લીધા"],"ro":["Svaad sneh mamtaa maan, paapi paarothaa kidhaa;","Kahe Nishkulanand nidaan, nij jan taari lidhaa"],"chhap":1,"no":4}]},{"n":34,"id":"cp-34","name":"Pad 34","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=33","stanzas":[{"id":"cp-34.1","gu":["જેમ જીત્યા એ શત્રુ સમૂહ, કામ ક્રોધ લોભ લઈ;","સ્વાદ સ્નેહ મમતા મોહ, તે તો દેખાડું કઈ"],"ro":["Jem jityaa e shatru samuh, kaam krodh lobh lai;","Svaad sneh mamtaa moh, te to dekhaadu kai"],"no":1,"tek":1},{"id":"cp-34.2","gu":["કામ કારણે કઢાવી લાજ, ક્રોધે બોલી બંધ કરી;","લોભ ઉપર મહા મુનિરાજ, આવિયા ઝાડે ફરી"],"ro":["Kaam kaarne kadhaavi laaj, krodhe boli bandh kari;","Lobh upar mahaa muniraaj, aaviyaa jhaade fari"],"no":2},{"id":"cp-34.3","gu":["સ્વાદે સૌ એકઠું કરી અન્ન, જળ નાખી જન જમે;","સ્નેહે સંભારે નહિ સ્વજન, માનથી દૂર રમે"],"ro":["Svaade sau ekthu kari ann, jal naakhi jan jame;","Snehe sambhaare nahi svajan, maanthi dur rame"],"no":3},{"id":"cp-34.4","gu":["કાઢી રીસ કરી હડકાર, બીજા દુષ્ટ બહુ ડર્યા;","કહે નિષ્કુળાનંદ નિરધાર, વેરી એમ વશ્ય કર્યા"],"ro":["Kaadhi ris kari hadkaar, bijaa dusht bahu daryaa;","Kahe Nishkulanand nirdhaar, veri em vashya karyaa"],"chhap":1,"no":4}]},{"n":35,"id":"cp-35","name":"Pad 35","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=33","stanzas":[{"id":"cp-35.1","gu":["સારો શક્કો બેસાર્યો સુંદર, પ્રભુજી પ્રગટ થઈ;","નિષ્કલંક કર્યાં નારી નર, ઉત્તમ ઉપદેશ દઈ"],"ro":["Saaro shakko besaaryo sundar, prabhuji pragat thai;","Nishkalank karyaa naari nar, uttam updesh dai"],"no":1,"tek":1},{"id":"cp-35.2","gu":["કોઈ કાળે સુણી નહિ કાન, એવી રીતિ આપે આણી;","લોકમાંહી અલૌકી નિદાન, આશ્ચર્ય પામ્યાં પ્રાણી"],"ro":["Koi kaale suni nahi kaan, evi riti aape aani;","Lokmaanhi alauki nidaan, aashcharya paamyaa praani"],"no":2},{"id":"cp-35.3","gu":["બહુ સામર્થી વાવરી શ્યામ, કામ તે કંઈક કરી;","પછી પધારિયા નિજ ધામ, શ્રી ઘનશ્યામ હરિ"],"ro":["Bahu saamarthi vaavri shyaam, kaam te kanik kari;","Pachhi padhaariyaa nij dhaam, shri Ghanshyaam hari"],"no":3},{"id":"cp-35.4","gu":["વાંસે રહ્યા વેરી વિપરીત, ખરે ખરા ખીજે ભર્યા;","કહે નિષ્કુળાનંદ તેની રીત, દેખી સાચું દાઝી મર્યા"],"ro":["Vaanse rahyaa veri viprit, khare kharaa khije bharyaa;","Kahe Nishkulanand teni rit, dekhi saachu daajhi maryaa"],"chhap":1,"no":4}]},{"n":36,"id":"cp-36","name":"Pad 36","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=33","stanzas":[{"id":"cp-36.1","gu":["વડું વેર વાળવાને કાજ, સાબદા એ સહુ થયા;","મોટા મોટાની લેવાને લાજ, તાકે છે તેહ રહ્યા"],"ro":["Vadu ver vaalvaane kaaj, saabdaa e sahu thayaa;","Motaa motaani levaane laaj, taake chhe teh rahyaa"],"no":1,"tek":1},{"id":"cp-36.2","gu":["ઝીણા ઝાલવામાં નહિ જશ, માટે મોટાને જોશે;","કરશે દગો દેખજ્યો અવશ્ય, વેર વાળી વગોવશે"],"ro":["Jhinaa jhaalvaamaa nahi jash, maate motaane joshe;","Karshe dago dekhajyo avashya, ver vaali vagovshe"],"no":2},{"id":"cp-36.3","gu":["માટે સહુ રે’જો સાવધાન, ખબડદાર થઈ ખરા;","જેનું આગે કર્યું અપમાન, તે જાળવે નહિ જરા"],"ro":["Maate sahu re'jo saavdhaan, khabaddaar thai kharaa;","Jenu aage karyu apmaan, te jaalve nahi jaraa"],"no":3},{"id":"cp-36.4","gu":["એમ છે એ અનાદિની રીત, નવી એ નથી થઈ;","કહે નિષ્કુળાનંદ ધારો ચિત, સનાતન સાચી કહી"],"ro":["Em chhe e anaadini rit, navi e nathi thai;","Kahe Nishkulanand dhaaro chit, sanaatan saachi kahi"],"chhap":1,"no":4}]},{"n":37,"id":"cp-37","name":"Pad 37","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=33","stanzas":[{"id":"cp-37.1","gu":["કૃષ્ણ પધાર્યા કેડ્યની વાત, શ્રી ભાગવતે ભાખી;","કર્યો અસુરે બહુ ઉતપાત, હરિનારી ઘેર રાખી"],"ro":["Krushn padhaaryaa kedyani vaat, shri bhaagavte bhaakhi;","Karyo asure bahu utpaat, harinaari gher raakhi"],"no":1,"tek":1},{"id":"cp-37.2","gu":["અર્જુનનું ન ઊપજ્યું કાંય, ગાંડીવ ઘણુંયે હતું;","તોય ન થઈ તેહની સા’ય, બુઢાપણ આવ્યું નો’તું"],"ro":["Arjunnu na upajyu kaany, gaandiv ghanunye hatu;","Toy na thai tehni saa'ya, budhaapan aavyu no'tu"],"no":2},{"id":"cp-37.3","gu":["માટે પ્રભુ ગયા પછી એમ, થાય તેના સંશય શિયા;","સમા સમું રહે કહો કેમ, જેના રખવાળ ગયા"],"ro":["Maate prabhu gayaa pachhi em, thaay tenaa sanshay shiyaa;","Samaa samu rahe kaho kem, jenaa rakhvaal gayaa"],"no":3},{"id":"cp-37.4","gu":["માટે સમજી સર્વે સુજાણ, વચનમાં વળગી રહેજો;","કહે નિષ્કુળાનંદ નિરવાણ, કઠણ પળ આવી છે જો"],"ro":["Maate samji sarve sujaan, vachanmaa valgi rahejo;","Kahe Nishkulanand nirvaan, kathan pal aavi chhe jo"],"chhap":1,"no":4}]},{"n":38,"id":"cp-38","name":"Pad 38","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=33","stanzas":[{"id":"cp-38.1","gu":["નારી નજરે ન જુવો કોય, વિત્તની તો વાત ભૂંડી;","સ્વાદ સ્નેહ દુઃખદાયી દોય, ઇચ્છા એની ટાળો ઊંડી"],"ro":["Naari najre na juvo koy, vittani to vaat bhundi;","Svaad sneh dukhdaayi doy, ichchhaa eni taalo undi"],"no":1,"tek":1},{"id":"cp-38.2","gu":["માન મોટો છે અરિ અજિત, સમજીને સંગ તજો;","ન કરો એ પંચની પ્રતીત, હેતે શું હરિને ભજો"],"ro":["Maan moto chhe ari ajit, samjine sang tajo;","Na karo e panchni pratit, hete shu harine bhajo"],"no":2},{"id":"cp-38.3","gu":["આવો અવસર જાય અમોલ, પાછો તે પમાતો નથી;","તેનો તપાસી કરવો તોલ, ઊંડો અતિ અંતરથી"],"ro":["Aavo avsar jaay amol, paachho te pamaato nathi;","Teno tapaasi karvo tol, undo ati antarthi"],"no":3},{"id":"cp-38.4","gu":["માંડી મૂઠી જુગટાની જેમ, જીત્યા તો જીત થઈ;","કહે નિષ્કુળાનંદ (તો) એમ, હાર્યા તો હાર્ય સઈ"],"ro":["Maandi muthi jugtaani jem, jityaa to jit thai;","Kahe Nishkulanand (to) em, haaryaa to haarya sai"],"chhap":1,"no":4}]},{"n":39,"id":"cp-39","name":"Pad 39","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=33","stanzas":[{"id":"cp-39.1","gu":["અન્ન ધન ગયે મળે અન્ન ધન, વસ્ત્ર ગયે વસ્ત્ર મળે;","ગયે ભુવન મળે ભુવન, દિન ગયે દિન મળે"],"ro":["Ann dhan gaye male ann dhan, vastra gaye vastra male;","Gaye bhuvan male bhuvan, din gaye din male"],"no":1,"tek":1},{"id":"cp-39.2","gu":["રાજ ગયે આવી મળે રાજ, સાજ સમાજ સહી;","પણ ગઈ મળે નહિ લાજ, કહેવાની હતી તે કહી"],"ro":["Raaj gaye aavi male raaj, saaj samaaj sahi;","Pan gai male nahi laaj, kahevaani hati te kahi"],"no":2},{"id":"cp-39.3","gu":["લાજ ખોઈને કરવું કાજ, એ તો અકાજ ખરું;","મર મળે ત્રિલોકીનું રાજ, ઘોળ્યું પરહરો પરું"],"ro":["Laaj khoine karvu kaaj, e to akaaj kharu;","Mar male trilokinu raaj, gholyu parahro paru"],"no":3},{"id":"cp-39.4","gu":["બેઠી બદલામી જેને શીશ, ટળે નહિ કોઈ પળે;","કહે નિષ્કુળાનંદ વસાવીશ, લખાય છે તે કાગળે"],"ro":["Bethi badlaami jene shish, tale nahi koi pale;","Kahe Nishkulanand vasaavish, lakhaay chhe te kaagle"],"chhap":1,"no":4}]},{"n":40,"id":"cp-40","name":"Pad 40","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=33","stanzas":[{"id":"cp-40.1","gu":["જોને ભવ બ્રહ્માજીની ભૂલ્ય, જન સહુ જાણે છે;","એકલશૃંગી સૌભરીનાં શૂલ, પોથીમાં પ્રમાણે છે"],"ro":["Jone bhav brahmaajini bhulya, jan sahu jaane chhe;","Ekalshrungi saubhrinaa shul, pothimaa pramaane chhe"],"no":1,"tek":1},{"id":"cp-40.2","gu":["નારદ પર્વતની નિદાન, કીર્તિ કથામાં કહી;","માટે સહુ રહેજ્યો સાવધાન, ખબડદાર ખરા થઈ"],"ro":["Naarad parvatni nidaan, kirti kathaamaa kahi;","Maate sahu rahejyo saavdhaan, khabaddaar kharaa thai"],"no":2},{"id":"cp-40.3","gu":["જેની પાસે હોય જોખમ, જાળવો તે જતન કરી;","માથે મોટા છે વેરી વિષમ, ખોટી નહિ વાત ખરી"],"ro":["Jeni paase hoy jokham, jaalvo te jatan kari;","Maathe motaa chhe veri visham, khoti nahi vaat khari"],"no":3},{"id":"cp-40.4","gu":["રહેવું નહિ ગાફલ ગમાર, માલ અતોલ મળે;","કહે નિષ્કુળાનંદ વિચાર, કરવો પળે પળે"],"ro":["Rahevu nahi gaafal gamaar, maal atol male;","Kahe Nishkulanand vichaar, karvo pale pale"],"chhap":1,"no":4}]},{"n":41,"id":"cp-41","name":"Pad 41","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=41","stanzas":[{"id":"cp-41.1","gu":["જેનું કામે કાપી લીધું નાક, લોભે લઈ લાજ લીધી રે;","જેને જીભે રોળી કર્યો રાંક, માને તો ફજેતી કીધી રે"],"ro":["Jenu kaame kaapi lidhu naak, lobhe lai laaj lidhi re;","Jene jibhe roli karyo raank, maane to fajeti kidhi re"],"no":1,"tek":1},{"id":"cp-41.2","gu":["એવા જનનું જાણો જરૂર, નથી મુખ જોયા જેવું રે;","દોષે ભર્યું જાણી તજો દૂર, અઘે અવરાણું એવું રે"],"ro":["Evaa jannu jaano jarur, nathi mukh joyaa jevu re;","Doshe bharyu jaani tajo dur, aghe avraanu evu re"],"no":2},{"id":"cp-41.3","gu":["તેને પાસે વસતાં વાસ, લાંછન તો લાગે જ લાગે રે;","તજો તેને આણી તનત્રાસ, જેથી કુબુદ્ધિ જાગે રે"],"ro":["Tene paase vastaa vaas, laanchhan to laage ja laage re;","Tajo tene aani tanatraas, jethi kubuddhi jaage re"],"no":3},{"id":"cp-41.4","gu":["એવા પાપીનું સ્પર્શતાં અંગ, પુણ્ય જાય પોતાતણું રે;","કહે નિષ્કુળાનંદ એ કુસંગ, તે સંગે જ્યાન ઘણું રે"],"ro":["Evaa paapinu sparshataa ang, punya jaay potaatnu re;","Kahe Nishkulanand e kusang, te sange jyaan ghanu re"],"chhap":1,"no":4}]},{"n":42,"id":"cp-42","name":"Pad 42","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=41","stanzas":[{"id":"cp-42.1","gu":["એવા જન જીવતા જરૂર, મૂઆ છે માની લેજો રે;","દેખી દુર્ગંધને રહેજો દૂર, આભડછેટ એ તો છે જો રે"],"ro":["Evaa jan jivtaa jarur, muvaa chhe maani lejo re;","Dekhi durgandhne rahejo dur, aabhadchhet e to chhe jo re"],"no":1,"tek":1},{"id":"cp-42.2","gu":["કાઢ્યા વિના નહિ સૂઝે કામ, સૂતક એ શીદ રાખો રે;","બાળી જાળી ટાળો એનું ઠામ, વાની વહેતે જળે નાખો રે"],"ro":["Kaadhyaa vinaa nahi sujhe kaam, sutak e shid raakho re;","Baali jaali taalo enu thaam, vaani vahete jale naakho re"],"no":2},{"id":"cp-42.3","gu":["ઘણું રાખતાં એ ઘરમાંય, સૂણી કે સડી જાશે રે;","કાઢો વેલ્ય મ કરજો કાંય, ઘણું રાખ્યે ગંધ થાશે રે"],"ro":["Ghanu raakhtaa e gharmaany, suni ke sadi jaashe re;","Kaadho velya ma karjo kaany, ghanu raakhye gandh thaashe re"],"no":3},{"id":"cp-42.4","gu":["કેડે કરવી નહિ તેની કાણ, ખરખરો ખોટો ખોળી રે;","કહે નિષ્કુળાનંદ સુજાણ, કહ્યું મેં તપાસી તોળી રે"],"ro":["Kede karvi nahi teni kaan, kharakhro khoto kholi re;","Kahe Nishkulanand sujaan, kahyu me tapaasi toli re"],"chhap":1,"no":4}]},{"n":43,"id":"cp-43","name":"Pad 43","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=41","stanzas":[{"id":"cp-43.1","gu":["કહેશો હરે ફરે નર આપ, મૂઓ તેને કેમ કહીએ રે;","તે તો પૂંછ હલાવે છે સાપ, ઘડીવાર જીવ ગયે રે"],"ro":["Kahesho hare fare nar aap, muvo tene kem kahiye re;","Te to punchh halaave chhe saap, ghadivaar jiv gaye re"],"no":1,"tek":1},{"id":"cp-43.2","gu":["પણ પંડમાંયે નથી પ્રાણ, જરૂર જાણી લેજો રે;","જોઈ એના અંગનાં એંધાણ, પછી ડરી દૂર રહેજો રે"],"ro":["Pan pandmaanye nathi praan, jarur jaani lejo re;","Joi enaa angnaa endhaan, pachhi dari dur rahejo re"],"no":2},{"id":"cp-43.3","gu":["કાપ્યું તરુ કાઢે છે કૂંપળ, સરે પણ સૂકી જાશે રે;","તેમ નર કરે કોટિ કળ, અંતે તે ઉઘાડું થાશે રે"],"ro":["Kaapyu taru kaadhe chhe kumpal, sare pan suki jaashe re;","Tem nar kare koti kal, ante te ughaadu thaashe re"],"no":3},{"id":"cp-43.4","gu":["કહો કપટ કેટલા દન, નર એહ રાખી રહેશે રે;","કહે નિષ્કુળાનંદ સહુ જન, જેમ હશે તેમ કહેશે રે"],"ro":["Kaho kapat ketlaa dan, nar eh raakhi raheshe re;","Kahe Nishkulanand sahu jan, jem hashe tem kaheshe re"],"chhap":1,"no":4}]},{"n":44,"id":"cp-44","name":"Pad 44","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=41","stanzas":[{"id":"cp-44.1","gu":["જેમ મહાજળમાં મગર, સાગર સહુને રાખે રે;","નાનાં મોટાં કરી રહે ઘર, કોઈને ન કાઢી નાખે રે"],"ro":["Jem mahaajalmaa magar, saagar sahune raakhe re;","Naanaa motaa kari rahe ghar, koine na kaadhi naakhe re"],"no":1,"tek":1},{"id":"cp-44.2","gu":["પણ જિયાં લગી જીવ હોય, ત્યાં લગી તેમાં રહે રે;","વણ જીવે રહે નહિ કોય, લે’રે દૂર નાખી દહે રે"],"ro":["Pan jiyaa lagi jiv hoy, tyaa lagi temaa rahe re;","Van jive rahe nahi koy, le're dur naakhi dahe re"],"no":2},{"id":"cp-44.3","gu":["હરિજનનું જીવન છે ધર્મ, પોતે પોતાનો પાળે રે;","તજે નહિ ભજે પરબ્રહ્મ, તો રહે તેમાં સદાકાળે રે"],"ro":["Harijannu jivan chhe dharm, pote potaano paale re;","Taje nahi bhaje parabrahm, to rahe temaa sadaakaale re"],"no":3},{"id":"cp-44.4","gu":["વણ જીવે હોય નહિ વાસ, સતસંગ સિંધુમાંઈ રે;","કરવો નિષ્કુળાનંદ તપાસ, કહ્યું નથી કૂડું કાંઈ રે"],"ro":["Van jive hoy nahi vaas, satsang sindhumaani re;","Karvo Nishkulanand tapaas, kahyu nathi kudu kaani re"],"chhap":1,"no":4}]},{"n":45,"id":"cp-45","name":"Pad 45","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=41","stanzas":[{"id":"cp-45.1","gu":["જે કોઈ ડચકાં દિવસ રાત, ખાતો નર હોય ખરાં રે;","તેને જીવવાની જૂઠી વાત, પાંપળાં મેલો પરાં રે"],"ro":["Je koi dachkaa divas raat, khaato nar hoy kharaa re;","Tene jivvaani juthi vaat, paamplaa melo paraa re"],"no":1,"tek":1},{"id":"cp-45.2","gu":["જેની નાડી છાંડી ગઈ ઘર, જિહ્વા તો ટૂંકી પડી રે;","દૃગ દોય દઈ ગયાં દર, શ્વાસ આવ્યો સુધો ચડી રે"],"ro":["Jeni naadi chhaandi gai ghar, jihvaa to tunki padi re;","Drug doy dai gayaa dar, shvaas aavyo sudho chadi re"],"no":2},{"id":"cp-45.3","gu":["તેહ સમામાંહી સગપણ, કરે કોય કન્યાતણું રે;","તેને રોકડું છે રંડાપણ, એવાતણ ઉધારે ઘણું રે"],"ro":["Teh samaamaanhi sagpan, kare koy kanyaatnu re;","Tene rokdu chhe randaapan, evaatan udhaare ghanu re"],"no":3},{"id":"cp-45.4","gu":["તેમ સત્સંગમાં કોઈ જન, ગડબડ ગોટા વાળે રે;","કહે નિષ્કુળાનંદ કોઈ દન, રખે તે જીવત બાળે રે"],"ro":["Tem satsangmaa koi jan, gadbad gotaa vaale re;","Kahe Nishkulanand koi dan, rakhe te jivat baale re"],"chhap":1,"no":4}]},{"n":46,"id":"cp-46","name":"Pad 46","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=41","stanzas":[{"id":"cp-46.1","gu":["ડોરી દેખી મ ડગાવો દલ, સમજીને સંગ કરો રે;","સારા સંત ઓળખી અવલ, મન કર્મ વચને વરો રે"],"ro":["Dori dekhi ma dagaavo dal, samjine sang karo re;","Saaraa sant olkhi aval, man karm vachne varo re"],"no":1,"tek":1},{"id":"cp-46.2","gu":["દેખી ઉપરનો આટાટોપ, મને રખે મોટા માનો રે;","એ તો ફોગટ ફૂલ્યો છે ફોપ, સમજો એ સંત શાનો રે"],"ro":["Dekhi uparno aataatop, mane rakhe motaa maano re;","E to fogat fulyo chhe fop, samjo e sant shaano re"],"no":2},{"id":"cp-46.3","gu":["જેને જાણજો જગ મોટાઈ, જડાણી જીવ સંગે રે;","તેને મોટા માનો જગમાંઈ, ખોટા છે મોક્ષ મગે રે"],"ro":["Jene jaanjo jag motaai, jadaani jiv sange re;","Tene motaa maano jagmaani, khotaa chhe moksh mage re"],"no":3},{"id":"cp-46.4","gu":["જોને શુકજી ને જડભરત, કો’ કેણે મોટા જાણ્યા રે;","હતા નિષ્કુળાનંદ એ સમ્રથ, પછી સહુએ પરમાણ્યા રે"],"ro":["Jone Shukji ne Jadbharat, ko' kene motaa jaanyaa re;","Hataa Nishkulanand e samrath, pachhi sahuve parmaanyaa re"],"chhap":1,"no":4}]},{"n":47,"id":"cp-47","name":"Pad 47","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=41","stanzas":[{"id":"cp-47.1","gu":["એહ વિના મોટાઈ જે અન્ય, ખરી તે પણ ખોટી નથી રે;","તે તો સુણી લિયો સહુજન, તે પણ કહું કથી રે"],"ro":["Eh vinaa motaai je anya, khari te pan khoti nathi re;","Te to suni liyo sahujan, te pan kahu kathi re"],"no":1,"tek":1},{"id":"cp-47.2","gu":["જેમ પંખીમાં મોટેરો ઘૂડ, ઝાડમાં તાડ લઈએ રે;","તળાવ જળમાં મોટો ઝૂડ, પશુમાં પાડો કહીએ રે"],"ro":["Jem pankhimaa motero ghud, jhaadmaa taad laiye re;","Talaav jalmaa moto jhud, pashumaa paado kahiye re"],"no":2},{"id":"cp-47.3","gu":["સર્પમાં મોટેરો તક્ષક, વીંછીમાં ઠાકરિયો વળી રે;","એ તો મોટપ દુઃખદાયક, સમજો સહુ મળી રે"],"ro":["Sarpamaa motero takshak, vinchhimaa thaakriyo vali re;","E to motap dukhdaayak, samjo sahu mali re"],"no":3},{"id":"cp-47.4","gu":["એમ જાણ્યા વિના જગમાંય, ઉપાય નથી ઊગર્યાનો રે;","કહે નિષ્કુળાનંદ તે ન્યાય, માનો કે નવ માનો રે"],"ro":["Em jaanyaa vinaa jagmaany, upaay nathi ugaryaano re;","Kahe Nishkulanand te nyaay, maano ke nav maano re"],"chhap":1,"no":4}]},{"n":48,"id":"cp-48","name":"Pad 48","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=41","stanzas":[{"id":"cp-48.1","gu":["ખોટીલા સાંભળી આવી ખોટ, દોષ જે બીજાને દેશે રે;","પોતે પેટે કપટ રાખી કોટ, બા’ર તો સાધુતા ગ્રે’શે રે"],"ro":["Khotilaa saambhli aavi khot, dosh je bijaane deshe re;","Pote pete kapat raakhi kot, baa'ra to saadhutaa gre'she re"],"no":1,"tek":1},{"id":"cp-48.2","gu":["છળે કળે છપાડી છિદર, વાંકમાં નહિ આવે આપે રે;","એમ કરતાં જાણશે કોઈ નર, તેને ડરાવશે શાપે રે"],"ro":["Chhale kale chhapaadi chhidar, vaankmaa nahi aave aape re;","Em kartaa jaanshe koi nar, tene daraavshe shaape re"],"no":2},{"id":"cp-48.3","gu":["આણી આખ્યાન તેની ઉપર, બોલવા નહિ દિયે રે;","જેને નથી મહારાજનો ડર, તે કહો કેથી બીયે રે"],"ro":["Aani aakhyaan teni upar, bolvaa nahi diye re;","Jene nathi mahaaraajno dar, te kaho kethi biye re"],"no":3},{"id":"cp-48.4","gu":["એવા પાપી જે પાપના પુંજ, દેખીને દૂર રહીએ રે;","કહે નિષ્કુળાનંદ તે શું જ, કહી કહી કેટલું કહીએ રે"],"ro":["Evaa paapi je paapnaa punj, dekhine dur rahiye re;","Kahe Nishkulanand te shu ja, kahi kahi ketlu kahiye re"],"chhap":1,"no":4}]},{"n":49,"id":"cp-49","name":"Pad 49","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=49","stanzas":[{"id":"cp-49.1","gu":["સુંદર સારી શિખામણ મારી, માની લે મનવા મારા રે;","ધારી વિચારી મેં વાત ઉચ્ચારી, તે જોઈ સ્વભાવ તારા રે"],"ro":["Sundar saari shikhaaman maari, maani le manvaa maaraa re;","Dhaari vichaari me vaat uchchaari, te joi svabhaav taaraa re"],"no":1,"tek":1},{"id":"cp-49.2","gu":["પરને કહેવા પ્રવીણ છો પૂરો, પોતાનું તો તું ન પેખે રે;","સામાને શીખ દેવામાં છો શૂરો, નિજ દોષને નવ દેખે રે"],"ro":["Parne kahevaa pravin chho puro, potaanu to tu na pekhe re;","Saamaane shikh devaamaa chho shuro, nij doshne nav dekhe re"],"no":2},{"id":"cp-49.3","gu":["કાંયે ન સમજે કારજ તારું, કહું છું કાંયે નહિ થાય રે;","શીદને ઉતારે છે પરબારું, કાંરે ન મનાય કાંય રે"],"ro":["Kaanye na samje kaaraj taaru, kahu chhu kaanye nahi thaay re;","Shidne utaare chhe parbaaru, kaanre na manaay kaany re"],"no":3},{"id":"cp-49.4","gu":["અવળી સમજણ અળગીએ કરી, સવળું સમજાય તો સારું રે;","નિષ્કુળાનંદ કહે વિચારી, એટલું માની લે મારું રે"],"ro":["Avli samjan algiye kari, savlu samjaay to saaru re;","Nishkulanand kahe vichaari, etlu maani le maaru re"],"chhap":1,"no":4}]},{"n":50,"id":"cp-50","name":"Pad 50","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=49","stanzas":[{"id":"cp-50.1","gu":["મન તુંને સમજાવવા સારુ, કહ્યું મેં વારમવાર રે;","તેં તો ગમતું ન તજિયું તારું, ગઈ શિખામણ ગમાર રે"],"ro":["Man tunne samjaavvaa saaru, kahyu me vaaramvaar re;","Te to gamtu na tajiyu taaru, gai shikhaaman gamaar re"],"no":1,"tek":1},{"id":"cp-50.2","gu":["જે જે વાત કરી તુજ સાથે, તે તો તેં રતિ ન રાખી રે;","ખોટ્ય આવવા દીધી નહીં માથે, લઈ બીજા પર નાખી રે"],"ro":["Je je vaat kari tuj saathe, te to te rati na raakhi re;","Khotya aavvaa didhi nahi maathe, lai bijaa par naakhi re"],"no":2},{"id":"cp-50.3","gu":["કહો ખોટ્ય ટળે કેમ તારી, નિજ દોષને ન દેખે રે;","એથી ભૂલ બીજી કઈ ભારી, સહુથી સરસ આપ લેખે રે"],"ro":["Kaho khotya tale kem taari, nij doshne na dekhe re;","Ethi bhul biji kai bhaari, sahuthi saras aap lekhe re"],"no":3},{"id":"cp-50.4","gu":["કહેનારાને કહેવા ન રહ્યું, તેં ન ધર્યું જ્યારે કાન રે;","નિષ્કુળાનંદ કહે તુંને શિયું, તારે તો બીજું છે તાન રે"],"ro":["Kahenaaraane kahevaa na rahyu, te na dharyu jyaare kaan re;","Nishkulanand kahe tunne shiyu, taare to biju chhe taan re"],"chhap":1,"no":4}]},{"n":51,"id":"cp-51","name":"Pad 51","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=49","stanzas":[{"id":"cp-51.1","gu":["સમું સમજે શોધતાં એવા, જોતાં ઝાઝા નવ જડે રે;","જેને ન આવડે અવળું લેવા, વણતોળી વિપત્ય જો પડે રે"],"ro":["Samu samje shodhtaa evaa, jotaa jhaajhaa nav jade re;","Jene na aavde avlu levaa, vantoli vipatya jo pade re"],"no":1,"tek":1},{"id":"cp-51.2","gu":["માન મોટપ ને મમતા મૂકે, ગમતું ગોવિંદનું જાણી રે;","ચોટ નિશાન ઉપરથી ન ચૂકે, પરલોકે પ્રતીતિ આણી રે"],"ro":["Maan motap ne mamtaa muke, gamtu govindnu jaani re;","Chot nishaan uparthi na chuke, parloke pratiti aani re"],"no":2},{"id":"cp-51.3","gu":["કોઈ કાળે જો કામ પોતાનું, વણસાડે નહિ વળી રે;","કપટ કેદીયે ન રાખે છાનું, મોટા સંતને મળી રે"],"ro":["Koi kaale jo kaam potaanu, vansaade nahi vali re;","Kapat kediye na raakhe chhaanu, motaa santne mali re"],"no":3},{"id":"cp-51.4","gu":["એવા જન જગતમાં જાણો, ઘર ઘર ઘણા ન હોય રે;","નિષ્કુળાનંદ કહે પરમાણો, સાચા સંત કા’વે સોય રે"],"ro":["Evaa jan jagatmaa jaano, ghar ghar ghanaa na hoy re;","Nishkulanand kahe parmaano, saachaa sant kaa've soy re"],"chhap":1,"no":4}]},{"n":52,"id":"cp-52","name":"Pad 52","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=49","stanzas":[{"id":"cp-52.1","gu":["આ લોકની જેણે આશા તજી છે, પરલોકના સુખ સારુ રે;","તેણે કરી હરિભક્તિ રજી છે, સંસાર સુખ થયું ખારું રે"],"ro":["Aa lokni jene aashaa taji chhe, parloknaa sukh saaru re;","Tene kari haribhakti raji chhe, sansaar sukh thayu khaaru re"],"no":1,"tek":1},{"id":"cp-52.2","gu":["ચૌદ લોક ને ચતુરધા લગી, જગમાં જે જે કહેવાય રે;","સર્વે એ ઠેકાણે અગનિ સળગી, દેખે તપતાં ત્યાંય રે"],"ro":["Chaud lok ne chaturdhaa lagi, jagmaa je je kahevaay re;","Sarve e thekaane agni salgi, dekhe taptaa tyaany re"],"no":2},{"id":"cp-52.3","gu":["ઠરવા ઠાઉકું ઠામ ન સૂઝે, કો’ સુખ કિયાં મનાય રે;","કાળ માયાથી સહુ રહ્યાં ધ્રૂજે, હરિનાં ચરણ વિનાય રે"],"ro":["Tharvaa thaauku thaam na sujhe, ko' sukh kiyaa manaay re;","Kaal maayaathi sahu rahyaa dhruje, harinaa charan vinaay re"],"no":3},{"id":"cp-52.4","gu":["એમ અહોનિશ અંતરમાંઈ, વરતે છે વૈરાગ્ય રે;","નિષ્કુળાનંદ કહે તેને કાંઈ, કઠણ નો’યે કરવું ત્યાગ રે"],"ro":["Em ahonish antarmaani, varte chhe vairaagya re;","Nishkulanand kahe tene kaani, kathan no'ye karvu tyaag re"],"chhap":1,"no":4}]},{"n":53,"id":"cp-53","name":"Pad 53","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=49","stanzas":[{"id":"cp-53.1","gu":["એવા જનની ઉપર હરિ, રાજી છે અક્ષર પતિ રે;","જેણે ભક્તિ ભાવે શું કરી, ફરે નહિ કેદી મતિ રે"],"ro":["Evaa janni upar hari, raaji chhe akshar pati re;","Jene bhakti bhaave shu kari, fare nahi kedi mati re"],"no":1,"tek":1},{"id":"cp-53.2","gu":["શરીરનાં સુખ સર્વે ત્યાગી, બાંધી પ્રભુ સાથે પ્રીતિ રે;","જેની લગની લાલશું લાગી, તે તો ગયા જગ જીતી રે"],"ro":["Sharirnaa sukh sarve tyaagi, baandhi prabhu saathe priti re;","Jeni lagni laalshu laagi, te to gayaa jag jiti re"],"no":2},{"id":"cp-53.3","gu":["કપટ રહિત શ્રીજીની સેવા, જાણજો જે જને કરી રે;","પ્રભુના પદને પામિયા એવા, આ ભવજળ ગયા તરી રે"],"ro":["Kapat rahit shrijini sevaa, jaanjo je jane kari re;","Prabhunaa padne paamiyaa evaa, aa bhavjal gayaa tari re"],"no":3},{"id":"cp-53.4","gu":["તેમા સંશય લેશ મ લાવો, પૂરણ પ્રતીતિ આણો રે;","નિષ્કુળાનંદ કહે નિરદાવો, જેના જીવમાં જાણો રે"],"ro":["Temaa sanshay lesh ma laavo, puran pratiti aano re;","Nishkulanand kahe nirdaavo, jenaa jivmaa jaano re"],"chhap":1,"no":4}]},{"n":54,"id":"cp-54","name":"Pad 54","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=49","stanzas":[{"id":"cp-54.1","gu":["એવાને સંગેથી અક્ષરધામે, જવાય છે જો જરૂર રે;","બીજાને સંગે તો સુખ ન પામે, દુઃખ રહે ભરપૂર રે"],"ro":["Evaane sangethi Akshardhaamે, javaay chhe jo jarur re;","Bijaane sange to sukh na paame, dukh rahe bharpur re"],"no":1,"tek":1},{"id":"cp-54.2","gu":["જેને જાવું હોય જમને હાથે, દક્ષિણ દેશની માંય રે;","તે તો સુખે રહો કપટી સાથે, તેનું કહેતા નથી કાંય રે"],"ro":["Jene jaavu hoy jamne haathe, dakshin deshni maany re;","Te to sukhe raho kapti saathe, tenu kahetaa nathi kaany re"],"no":2},{"id":"cp-54.3","gu":["પણ જાવું જેને પ્રભુજી પાસે, તેને કરવો તપાસ રે;","અંતરે બીજો તજવો આશે, થઈ રહેવું હરિદાસ રે"],"ro":["Pan jaavu jene prabhuji paase, tene karvo tapaas re;","Antre bijo tajvo aashe, thai rahevu haridaas re"],"no":3},{"id":"cp-54.4","gu":["આવી વાત અંતરે ઉતારી, કરી લેવું નિજ કામ રે;","નિષ્કુળાનંદ કહે વિચારી, તો પામિયે અક્ષરધામ રે"],"ro":["Aavi vaat antre utaari, kari levu nij kaam re;","Nishkulanand kahe vichaari, to paamiye Akshardhaam re"],"chhap":1,"no":4}]},{"n":55,"id":"cp-55","name":"Pad 55","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=49","stanzas":[{"id":"cp-55.1","gu":["જેહ ધામને પામીને પ્રાણી, પાછું પડવાનું નથી રે;","સર્વે પર છે સુખની ખાણી, કેવું કહીએ તેને કથી રે"],"ro":["Jeh dhaamne paamine praani, paachhu padvaanu nathi re;","Sarve par chhe sukhni khaani, kevu kahiye tene kathi re"],"no":1,"tek":1},{"id":"cp-55.2","gu":["અનંત મુક્ત જ્યાં આનંદે ભરિયા, રહે છે પ્રભુજીની પાસ રે;","સુખ સુખ જ્યાં સુખના દરિયા, તિયાં વસી રહ્યા વાસ રે"],"ro":["Anant mukt jyaa aanande bhariyaa, rahe chhe prabhujini paas re;","Sukh sukh jyaa sukhnaa dariyaa, tiyaa vasi rahyaa vaas re"],"no":2},{"id":"cp-55.3","gu":["તેજ તેજ જિયાં તેજ અંબાર, તેજોમય તન તેનાં રે;","તેજોમય જ્યાં સર્વે આકાર, શું કહીએ સુખ એનાં રે"],"ro":["Tej tej jiyaa tej ambaar, tejomay tan tenaa re;","Tejomay jyaa sarve aakaar, shu kahiye sukh enaa re"],"no":3},{"id":"cp-55.4","gu":["તે તેજ મધ્યે સિંહાસન શોભે, તિયાં બેઠા બહુનામી રે;","નિષ્કુળાનંદ કહે મન લોભે, પૂર્ણ પુરુષોત્તમ પામી રે"],"ro":["Te tej madhye sinhaasan shobhe, tiyaa bethaa bahunaami re;","Nishkulanand kahe man lobhe, purn Purushottam paami re"],"chhap":1,"no":4}]},{"n":56,"id":"cp-56","name":"Pad 56","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=49","stanzas":[{"id":"cp-56.1","gu":["એવા ધામની આગળ બીજાં, શી ગણતીમાં ગણાય રે;","મા’પ્રલય કાળના અગ્નિમાં સીજાં, હંમેશ જેહ હણાય રે"],"ro":["Evaa dhaamni aagal bijaa, shi gantimaa ganaay re;","Maa'pralay kaalnaa agnimaa sijaa, hammesh jeh hanaay re"],"no":1,"tek":1},{"id":"cp-56.2","gu":["પ્રકૃતિ પુરુષ પ્રલયમાં આવે, ભવ બ્રહ્મા ન રહે કોય રે;","ચૌદ લોક ધામ રે’વા ન પાવે, સર્વે સંહાર હોય રે"],"ro":["Prakruti purush pralaymaa aave, bhav brahmaa na rahe koy re;","Chaud lok dhaam re'vaa na paave, sarve sanhaar hoy re"],"no":2},{"id":"cp-56.3","gu":["જેમ કડાયામાં કણ ઊછળે છે, ઊંચા નીચા અગ્નિ જ્વાળે રે;","તેમ જ તનધારી બળે છે, સ્વર્ગ મૃત્યુ ને પાતાળે રે"],"ro":["Jem kadaayaamaa kan uchhle chhe, unchaa nichaa agni jvaale re;","Tem ja tandhaari bale chhe, svarg mrutyu ne paataale re"],"no":3},{"id":"cp-56.4","gu":["માટે સુખ નથી કિયાં માને, પ્રભુજીના પદ પખી રે;","નિષ્કુળાનંદ કે’ ભૂલે છે શાને, લે વાત આવી તું લખી રે"],"ro":["Maate sukh nathi kiyaa maane, prabhujinaa pad pakhi re;","Nishkulanand ke' bhule chhe shaane, le vaat aavi tu lakhi re"],"chhap":1,"no":4}]},{"n":57,"id":"cp-57","name":"Pad 57","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=57","stanzas":[{"id":"cp-57.1","gu":["એવા ધામને પામવા કાજ, અવસર અમૂલ્ય આવ્યો;","આવ્યો સુખનો મળી સમાજ, ભલો અતિ મન ભાવ્યો"],"ro":["Evaa dhaamne paamvaa kaaj, avsar amulya aavyo;","Aavyo sukhno mali samaaj, bhalo ati man bhaavyo"],"no":1,"tek":1},{"id":"cp-57.2","gu":["ભાવ્યો એ રસ જેહને ઉર, તેણે પીવા પ્યાસ કરી;","કરી દેહબુદ્ધિ વળી દૂર, એક ઉર રાખ્યા હરિ"],"ro":["Bhaavyo e ras jehne ur, tene pivaa pyaas kari;","Kari dehbuddhi vali dur, ek ur raakhyaa hari"],"no":2},{"id":"cp-57.3","gu":["હરિ વિના રાખ્યું નહિ કાંય, અસત્ય જાણી આપે;","આપે વિચાર્યું અંતરમાંય, તેહ તપે નહિ તાપે"],"ro":["Hari vinaa raakhyu nahi kaany, asatya jaani aape;","Aape vichaaryu antarmaany, teh tape nahi taape"],"no":3},{"id":"cp-57.4","gu":["તાપે તપતાં જાણી ત્રિલોક, ઇચ્છા ઉરથી તજી;","તજી નિષ્કુળાનંદ સંશે શોક, ભાવે લીધા પ્રભુને ભજી"],"ro":["Taape taptaa jaani trilok, ichchhaa urthi taji;","Taji Nishkulanand sanshe shok, bhaave lidhaa prabhune bhaji"],"chhap":1,"no":4}]},{"n":58,"id":"cp-58","name":"Pad 58","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=57","stanzas":[{"id":"cp-58.1","gu":["ભજી ભલી ગઈ છે જો વાત, પુરુષોત્તમને પામી;","પામી પ્રગટ પ્રભુ સાક્ષાત, કહો કાંઈ રહી ખામી"],"ro":["Bhaji bhali gai chhe jo vaat, Purushottamne paami;","Paami pragat prabhu saakshaat, kaho kaani rahi khaami"],"no":1,"tek":1},{"id":"cp-58.2","gu":["ખામી ભાંગી ખરી થઈ ખાટ, ખોયા દી’ની ખોટ્ય ટળી;","ટળી ગયા સર્વે ઉચ્ચાટ, શ્રી ઘનશ્યામ મળી"],"ro":["Khaami bhaangi khari thai khaat, khoyaa di'ni khotya tali;","Tali gayaa sarve uchchaat, shri Ghanshyaam mali"],"no":2},{"id":"cp-58.3","gu":["મળી મોજ અલૌકિક આજ, આવ્યું સુખ અતિ અંગે;","અંગે કરવું ન રહ્યું કાજ, મળી મહારાજ સંગે"],"ro":["Mali moj alaukik aaj, aavyu sukh ati ange;","Ange karvu na rahyu kaaj, mali mahaaraaj sange"],"no":3},{"id":"cp-58.4","gu":["સંગે રહીશ હું તો સદાય, સુખકારી શ્યામ જાણી;","જાણી નિષ્કુળાનંદ મનમાંય, રહું ઉર આનંદ આણી"],"ro":["Sange rahish hu to sadaay, sukhkaari shyaam jaani;","Jaani Nishkulanand manmaany, rahu ur aanand aani"],"chhap":1,"no":4}]},{"n":59,"id":"cp-59","name":"Pad 59","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=57","stanzas":[{"id":"cp-59.1","gu":["આણી આંખ્યે મેં જોયા જીવન, સહજાનંદ સ્વામી;","સ્વામી દોયલી વેળાનું ધન, પામી દુઃખ ગયાં વામી"],"ro":["Aani aankhye me joyaa jivan, Sahajanand svaami;","Svaami doyli velaanu dhan, paami dukh gayaa vaami"],"no":1,"tek":1},{"id":"cp-59.2","gu":["વામી વેદના મારી આ વાર, શરણ શ્રીજીનું લઈ;","લઈ મું અર્થે અવતાર, આવિયા આપે સઈ"],"ro":["Vaami vednaa maari aa vaar, sharan shrijinu lai;","Lai mu arthe avtaar, aaviyaa aape sai"],"no":2},{"id":"cp-59.3","gu":["સઈ કહું આ સમાની રીત, આજ આડો આંક વળ્યો;","વળ્યો દિવસ થઈ મારી જીત, સંશય શોક ટળ્યો"],"ro":["Sai kahu aa samaani rit, aaj aado aank valyo;","Valyo divas thai maari jit, sanshay shok talyo"],"no":3},{"id":"cp-59.4","gu":["ટળ્યો કાળની ઝાળનો ત્રાસ, પૂરણ સુખ પામ્યો;","પામ્યો નિષ્કુળાનંદ ઉલ્લાસ, ફૂલી ત્રિલોકે ન શામ્યો"],"ro":["Talyo kaalni jhaalno traas, puran sukh paamyo;","Paamyo Nishkulanand ullaas, fuli triloke na shaamyo"],"chhap":1,"no":4}]},{"n":60,"id":"cp-60","name":"Pad 60","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=57","stanzas":[{"id":"cp-60.1","gu":["શામ્યો અસત સુખનો ઉછાહ, સુરતિ સાચામાં લાગી;","લાગી પ્રભુપદની જો ચાહ, બીજી ભૂખ સર્વે ભાગી"],"ro":["Shaamyo asat sukhno uchhaah, surti saachaamaa laagi;","Laagi prabhupadni jo chaah, biji bhukh sarve bhaagi"],"no":1,"tek":1},{"id":"cp-60.2","gu":["ભાગી આ લોકસુખની આશ, નિરાશે નિરાંત થઈ;","થઈ પરી એ સર્વે કાશ, અન્ય અભિલાષા ગઈ"],"ro":["Bhaagi aa loksukhni aash, niraashe niraant thai;","Thai pari e sarve kaash, anya abhilaashaa gai"],"no":2},{"id":"cp-60.3","gu":["ગઈ સુરતિ સહુની પાર, અક્ષરધામે ધાઈ;","ધાઈ ઇચ્છતાં સુખ સંસાર, તેમાં ન દીઠું કાંઈ"],"ro":["Gai surti sahuni paar, Akshardhaamે dhaai;","Dhaai ichchhataa sukh sansaar, temaa na dithu kaani"],"no":3},{"id":"cp-60.4","gu":["કાંઈ માને બીજે તેનું મન? મહાસુખ મોટું જોઈ;","જોઈ નિષ્કુળાનંદ મગન, મનમાં રહ્યો મોઈ"],"ro":["Kaani maane bije tenu man? mahaasukh motu joi;","Joi Nishkulanand magan, manmaa rahyo moi"],"chhap":1,"no":4}]},{"n":61,"id":"cp-61","name":"Pad 61","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=57","stanzas":[{"id":"cp-61.1","gu":["મોહી રહ્યા જેને મુનિરાજ, ત્યાજ તનસુખ કરી;","કરી લીધું છે પોતાનું કાજ, ફેરો નથી રાખ્યો ફરી"],"ro":["Mohi rahyaa jene muniraaj, tyaaj tansukh kari;","Kari lidhu chhe potaanu kaaj, fero nathi raakhyo fari"],"no":1,"tek":1},{"id":"cp-61.2","gu":["ફરી ફસવું જે ફંદમાંય, એવું ન રાખ્યું એણે;","એણે કરવું રાખ્યું નહિ કાંય, તલ એકભાર તેણે"],"ro":["Fari fasvu je fandmaany, evu na raakhyu ene;","Ene karvu raakhyu nahi kaany, tal ekbhaar tene"],"no":2},{"id":"cp-61.3","gu":["તેણે નજર પોં’ચાડી છે નેક, શાબાશ સમજણ એની;","એની મતિ પોં’ચી ગઈ છેક, હું બલિહારી તેની"],"ro":["Tene najar po'chaadi chhe nek, shaabaash samjan eni;","Eni mati po'chi gai chhek, hu balihaari teni"],"no":3},{"id":"cp-61.4","gu":["તેની જોડ્યે આવે કહો કોણ, વાત વિચારી જોઈ;","જોઈ નિષ્કુળાનંદ એવું જોણ, કહે ધન્ય સંત સોઈ"],"ro":["Teni jodye aave kaho kon, vaat vichaari joi;","Joi Nishkulanand evu jon, kahe dhanya sant soi"],"chhap":1,"no":4}]},{"n":62,"id":"cp-62","name":"Pad 62","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=57","stanzas":[{"id":"cp-62.1","gu":["સોઈ સુખ પામવાને કાજ, મોટા મનમાંય ઇચ્છે;","ઇચ્છે ભવ બ્રહ્મા સુરરાજ, મળવા મનમાં રહે છે"],"ro":["Soi sukh paamvaane kaaj, motaa manmaany ichchhe;","Ichchhe bhav brahmaa surraaj, malvaa manmaa rahe chhe"],"no":1,"tek":1},{"id":"cp-62.2","gu":["રહે છે આશા એવી ઉરમાંય, મને મહાસુખ લેવા;","લેવા આનંદ ઇચ્છા સદાય, દલમાંઈ ઇચ્છે દેવા"],"ro":["Rahe chhe aashaa evi urmaany, mane mahaasukh levaa;","Levaa aanand ichchhaa sadaay, dalmaani ichchhe devaa"],"no":2},{"id":"cp-62.3","gu":["દેવા ઉપમા એહને એક, જોતાં બીજી જડતી નથી;","નથી છાની એ વારતા છેક, કહેવાય છે કથી કથી"],"ro":["Devaa upmaa ehne ek, jotaa biji jadti nathi;","Nathi chhaani e vaartaa chhek, kahevaay chhe kathi kathi"],"no":3},{"id":"cp-62.4","gu":["કથી કહ્યું એ ધામનું સુખ, વરણવી વળી વળી;","વળી નિષ્કુળાનંદ કે’ શું મુખ, દુઃખ જાય એને મળી"],"ro":["Kathi kahyu e dhaamnu sukh, varanvi vali vali;","Vali Nishkulanand ke' shu mukh, dukh jaay ene mali"],"chhap":1,"no":4}]},{"n":63,"id":"cp-63","name":"Pad 63","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=57","stanzas":[{"id":"cp-63.1","gu":["મળી મહારાજને મુનિરાય, સહુ સુખ પામે સોય;","સોય કહું દૃષ્ટાંતની માંય, જાણો કાચભૂમિ હોય"],"ro":["Mali mahaaraajne muniraay, sahu sukh paame soy;","Soy kahu drushtaantni maany, jaano kaachbhumi hoy"],"no":1,"tek":1},{"id":"cp-63.2","gu":["હોય કાચના સર્વે આકાર, રવિ શશી તારા વળી;","વળી તેજ તેજ ત્યાં અંબાર, રહે બહુ ઝળમળી"],"ro":["Hoy kaachnaa sarve aakaar, ravi shashi taaraa vali;","Vali tej tej tyaa ambaar, rahe bahu jhalamli"],"no":2},{"id":"cp-63.3","gu":["મળી પૂરણ દીશે પ્રકાશ, એકરસ તેજ એવું;","એવું ધામમાંઈ છે ઉજાશ, એ વિના કહીએ કેવું"],"ro":["Mali puran dishe prakaash, ekras tej evu;","Evu dhaammaani chhe ujaash, e vinaa kahiye kevu"],"no":3},{"id":"cp-63.4","gu":["કે’વું કેડે નથી હવે કાંય, સમજો તો સમજો સાને;","સાને નિષ્કુળાનંદ ન ગાય? જેને આવ્યું એવું પાને"],"ro":["Ke'vu kede nathi have kaany, samjo to samjo saane;","Saane Nishkulanand na gaay? jene aavyu evu paane"],"chhap":1,"no":4}]},{"n":64,"id":"cp-64","name":"Pad 64","section":{"gu":"મહિમાનાં પદ","en":"Pads of mahima"},"listen":"https://www.anirdesh.com/kavya/chosath-padi/index.php?pad=57","stanzas":[{"id":"cp-64.1","gu":["પાને લખ્યાં આ પદ ચોસઠ્ય, સુંદર સારાં શોધી;","શોધી જોજો સહુ સારી પઠ્ય, જેવી હોય જેની બુદ્ધિ"],"ro":["Paane lakhyaa aa pad chosathya, sundar saaraa shodhi;","Shodhi jojo sahu saari pathya, jevi hoy jeni buddhi"],"no":1,"tek":1},{"id":"cp-64.2","gu":["બુદ્ધિમાંહી તે કરી વિચાર, સવળું સાર ગ્રહેજો;","ગ્રહેજો કરવાનું તે નિરધાર, ન કરવાનું મૂકી દેજો"],"ro":["Buddhimaanhi te kari vichaar, savlu saar grahejo;","Grahejo karvaanu te nirdhaar, na karvaanu muki dejo"],"no":2},{"id":"cp-64.3","gu":["દેજો માં વળી કોયને દોષ, રોષ અંતરમાં આણી;","આણી હૈયામાંઈ ઘણી હોંશ, મંડો સહુ સુખ જાણી"],"ro":["Dejo maa vali koyne dosh, rosh antarmaa aani;","Aani haiyaamaani ghani honsh, mando sahu sukh jaani"],"no":3},{"id":"cp-64.4","gu":["જાણી જોઈને આળસ અંગ, રતિ એક રખે રહે;","રહે નિષ્કુળાનંદ તો રંગ, અલભ્ય લાભ લહે"],"ro":["Jaani joine aalas ang, rati ek rakhe rahe;","Rahe Nishkulanand to rang, alabhya laabh lahe"],"chhap":1,"no":4}]}]},{"id":"ch","title":"Cheshta","gu":"ચેષ્ટા","poet":"Premanand, Nishkulanand and Muktanand Swami","source":"https://www.anirdesh.com/kirtan/cheshta.php","songs":[{"n":170,"id":"ch-170","name":"Pratham Shriharine re, charne shish namaavu","pad":1,"ref":"Kirtan Muktavali 1-170","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-170.1","gu":["પ્રથમ શ્રીહરિને રે, ચરણે શીશ નમાવું;","નૌતમ લીલા રે, નારાયણની ગાવું"],"ro":["Pratham Shriharine re, charne shish namaavu;","Nautam lilaa re, Naaraayanni gaavu"],"en":"First I bow my head at Shri Hari's feet, and sing the ever-new lilas of Narayan.","gl":[["nautam","ever-new"],["lilaa","divine actions, his play"]],"no":1},{"id":"ch-170.2","gu":["મોટા મુનિવર રે, એકાગ્ર કરી મનને;","જેને કાજે રે, સેવે જાઈ વનને"],"ro":["Motaa munivar re, ekaagra kari manne;","Jene kaaje re, seve jaai vanne"],"en":"Great munis make their minds one-pointed and go off to the forest for his sake.","gl":[["ekaagra","one-pointed"],["jene kaaje","for whose sake"]],"no":2},{"id":"ch-170.3","gu":["આસન સાધી રે, ધ્યાન ધરીને ધારે;","જેની ચેષ્ટા રે, સ્નેહ કરી સંભારે"],"ro":["Aasan saadhi re, dhyaan dharine dhaare;","Jeni cheshtaa re, sneh kari sambhaare"],"en":"Mastering their posture, they hold him in dhyan, and lovingly recall his cheshta, his everyday ways.","gl":[["aasan saadhi","settling firmly in a sitting posture"],["cheshtaa","his ways, gestures and habits"],["sambhaare","recall"]],"no":3},{"id":"ch-170.4","gu":["સહજ સ્વાભાવિક રે, પ્રકૃતિ પુરુષોત્તમની;","સુણતાં સજની રે, બીક મટાડે જમની"],"ro":["Sahaj svaabhaavik re, prakruti Purushottamni;","Suntaa sajni re, bik mataade jamni"],"en":"Easy and unforced is Purushottam's nature; hearing of it, friend, takes away the fear of Yama.","gl":[["prakruti","nature, temperament"],["sajni","friend, the listener the poet speaks to"],["jam","Yama, death"]],"no":4},{"id":"ch-170.5","gu":["ગાવું હેતે રે, હરિનાં ચરિત્ર સંભારી;","પાવન કરજ્યો રે, પ્રભુજી બુદ્ધિ મારી"],"ro":["Gaavu hete re, harinaa charitra sambhaari;","Paavan karajyo re, prabhuji buddhi maari"],"en":"I sing with love, remembering Hari's deeds. Prabhu, make my understanding pure.","gl":[["charitra","deeds"],["buddhi","understanding"]],"no":5},{"id":"ch-170.6","gu":["સહજ સ્વભાવે રે, બેઠા હોય હરિ જ્યારે;","તુલસીની માળા રે, કર લઈ ફેરવે ત્યારે"],"ro":["Sahaj svabhaave re, bethaa hoy hari jyaare;","Tulsini maalaa re, kar lai ferve tyaare"],"en":"When Hari sits at ease in his natural way, he takes a tulsi mala in his hand and turns it.","gl":[["sahaj svabhaave","naturally, at ease"],["ferve","turns (the beads)"]],"no":6},{"id":"ch-170.7","gu":["રમૂજ કરતા રે, રાજીવનેણ રૂપાળા;","કોઈ હરિજનની રે, માગી લઈને માળા"],"ro":["Ramuj kartaa re, raajivnen rupaalaa;","Koi harijanni re, maagi laine maalaa"],"en":"Joking, the handsome, lotus-eyed one asks some devotee for his mala and takes it.","gl":[["ramuj","joking, playfulness"],["raajivnen","lotus-eyed"],["rupaalaa","handsome"]],"no":7},{"id":"ch-170.8","gu":["બેવડી રાખી રે, બબ્બે મણકા જોડે;","ફેરવે તાણી રે, કંઈક માળા તોડે"],"ro":["Bevdi raakhi re, babbe mankaa jode;","Ferve taani re, kanik maalaa tode"],"en":"He doubles it over and joins the beads two by two; turning it with a tug, he breaks quite a few malas.","gl":[["bevdi","doubled"],["mankaa","beads"],["kanik","some, quite a few"]],"no":8},{"id":"ch-170.9","gu":["વાતું કરે રે, રમૂજ કરીને હસતાં;","ભેળી કરી રે, માળા કરમાં ઘસતાં"],"ro":["Vaatu kare re, ramuj karine hastaa;","Bheli kari re, maalaa karmaa ghastaa"],"en":"He talks and jokes and laughs, bunching the mala together and rubbing it between his hands.","gl":[["bheli kari","gathering it together"],["ghastaa","rubbing"]],"no":9},{"id":"ch-170.10","gu":["ક્યારેક મીંચી રે, નેત્રકમળને સ્વામી;","પ્રેમાનંદ કહે રે, ધ્યાન ધરે બહુનામી"],"ro":["Kyaarek minchi re, netrakmalne svaami;","Premanand kahe re, dhyaan dhare bahunaami"],"chhap":1,"en":"Sometimes the Swami closes his lotus eyes; says Premanand, the Lord of many names sits in dhyan.","gl":[["netrakamal","lotus eyes"],["bahunaami","the one of many names, God"]],"no":10}]},{"n":171,"id":"ch-171","name":"Saambhal saiyar re, lilaa natnaagarni","pad":2,"ref":"Kirtan Muktavali 1-171","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-171.1","gu":["સાંભળ સૈયર રે, લીલા નટનાગરની;","સુણતાં સુખડું રે, આપે સુખસાગરની"],"ro":["Saambhal saiyar re, lilaa natnaagarni;","Suntaa sukhdu re, aape sukhsaagarni"],"en":"Listen, friend, to the lila of the master actor; hearing of the ocean of joy gives joy.","gl":[["saiyar","friend"],["natnaagar","the master actor, God at play"],["sukhsaagar","ocean of joy"]],"no":1},{"id":"ch-171.2","gu":["નેત્રકમળને રે, રાખી ઉઘાડાં ક્યારે;","ધ્યાન ધરીને રે, બેસે જીવન બા’રે"],"ro":["Netrakmalne re, raakhi ughaadaa kyaare;","Dhyaan dharine re, bese jivan baa're"],"en":"Sometimes Jivan keeps his lotus eyes open and sits outside in dhyan.","gl":[["Jivan","'my life', the Beloved, Maharaj"],["baa're","outside"]],"check":"'bese jivan baa're' read as 'sits outside'; could be 'sits apart'","no":2},{"id":"ch-171.3","gu":["ક્યારેક ચમકી રે, ધ્યાન કરંતા જાગે;","જોતાં જીવન રે, જન્મમરણ દુઃખ ભાગે"],"ro":["Kyaarek chamki re, dhyaan karantaa jaage;","Jotaa jivan re, janmamran dukh bhaage"],"en":"Sometimes, in the middle of dhyan, he comes to with a start; seeing Jivan, the misery of birth and death runs away.","gl":[["chamki","with a start"],["janmamaran","birth and death"]],"no":3},{"id":"ch-171.4","gu":["પોતા આગળ રે, સભા ભરાઈ બેસે;","સંત હરિજન રે, સામું જોઈ રહે છે"],"ro":["Potaa aagal re, sabhaa bharaai bese;","Sant harijan re, saamu joi rahe chhe"],"en":"The assembly gathers and sits before him; Sants and devotees keep gazing at him.","gl":[["sabhaa","assembly"],["saamu joi rahe","keep looking toward him"]],"no":4},{"id":"ch-171.5","gu":["ધ્યાન ધરીને રે, બેઠા હોય હરિ પોતે;","સંત હરિજન રે, તૃપ્ત ન થાય જોતે"],"ro":["Dhyaan dharine re, bethaa hoy hari pote;","Sant harijan re, trupt na thaay jote"],"en":"When Hari himself sits in dhyan, Sants and devotees can never look their fill.","gl":[["trupt","satisfied"]],"no":5},{"id":"ch-171.6","gu":["સાધુ કીર્તન રે, ગાયે વજાડી વાજાં;","તેમને જોઈ રે, મગન થાયે મહારાજા"],"ro":["Saadhu kirtan re, gaaye vajaadi vaajaa;","Temne joi re, magan thaaye mahaaraajaa"],"en":"The sadhus sing kirtan, playing instruments; watching them, Maharaj is lost in delight.","gl":[["vaajaa","instruments"],["magan","absorbed, lost in joy"]],"no":6},{"id":"ch-171.7","gu":["તેમની ભેળા રે, ચપટી વજાડી ગાયે;","સંત હરિજન રે, નીરખી રાજી થાયે"],"ro":["Temni bhelaa re, chapti vajaadi gaaye;","Sant harijan re, nirkhi raaji thaaye"],"en":"He sings along with them, snapping his fingers; Sants and devotees watch and are delighted.","gl":[["chapti","a snap of the fingers"],["nirkhi","watching"]],"no":7},{"id":"ch-171.8","gu":["ક્યારેક સાધુ રે, ગાય વજાડી તાળી;","ભેળા ગાય રે, તાળી દઈ વનમાળી"],"ro":["Kyaarek saadhu re, gaay vajaadi taali;","Bhelaa gaay re, taali dai vanmaali"],"en":"Sometimes the sadhus sing clapping their hands; Vanmali claps and sings along.","gl":[["taali","clapping"],["vanmaali","wearer of the forest garland, a name of God"]],"no":8},{"id":"ch-171.9","gu":["આગળ સાધુ રે, કીર્તન ગાય જ્યારે;","પોતા આગળ રે, કથા વંચાય ત્યારે"],"ro":["Aagal saadhu re, kirtan gaay jyaare;","Potaa aagal re, kathaa vanchaay tyaare"],"en":"At times the sadhus sing kirtan before him; at times katha is read before him.","gl":[["kathaa vanchaay","scripture is read aloud and explained"]],"check":"'jyaare … tyaare' read as 'at one time … at another'","no":9},{"id":"ch-171.10","gu":["પોતે વારતા રે, કરતા હોય બહુનામી;","ખસતા આવે રે, પ્રેમાનંદના સ્વામી"],"ro":["Pote vaartaa re, kartaa hoy bahunaami;","Khastaa aave re, Premanandnaa svaami"],"chhap":1,"en":"When the Lord of many names is giving a talk himself, Premanand's Swami keeps edging forward.","gl":[["vaartaa","a spiritual talk"],["khastaa aave","edges forward"]],"note":"Caught up in what he was saying, he would shift forward on his seat.","no":10}]},{"n":172,"id":"ch-172","name":"Manushyalilaa re, kartaa mangalkaari","pad":3,"ref":"Kirtan Muktavali 1-172","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-172.1","gu":["મનુષ્યલીલા રે, કરતા મંગળકારી;","ભક્તસભામાં રે, બેઠા ભવભયહારી"],"ro":["Manushyalilaa re, kartaa mangalkaari;","Bhaktasbhaamaa re, bethaa bhavbhayhaari"],"en":"Performing his auspicious human lila, the remover of the fear of worldly life sits among his devotees.","gl":[["manushyalilaa","acting as a human"],["mangalkaari","auspicious"],["bhavbhayhaari","remover of the fear of rebirth"]],"no":1},{"id":"ch-172.2","gu":["જેને જોતાં રે, જાયે જગ આસક્તિ;","જ્ઞાન વૈરાગ્ય રે, ધર્મ સહિત જે ભક્તિ"],"ro":["Jene jotaa re, jaaye jag aasakti;","Gnaan vairaagya re, dharm sahit je bhakti"],"en":"Seeing him, attachment to the world falls away. Gnan, vairagya, and bhakti together with dharma:","gl":[["aasakti","attachment"],["gnaan","spiritual knowledge"],["vairaagya","detachment"]],"no":2},{"id":"ch-172.3","gu":["તે સંબંધી રે, વાર્તા કરતા ભારી;","હરિ સમજાવે રે, નિજ જનને સુખકારી"],"ro":["Te sambandhi re, vaartaa kartaa bhaari;","Hari samjaave re, nij janne sukhkaari"],"en":"on these he gives weighty talks; Hari explains them to his own people and makes them happy.","gl":[["bhaari","weighty, deep"],["nij jan","his own devotees"]],"no":3},{"id":"ch-172.4","gu":["યોગ ને સાંખ્ય રે, પંચરાત્ર વેદાંત;","એ શાસ્ત્રનો રે, રહસ્ય કહે કરી ખાંત"],"ro":["Yog ne saankhya re, panchraatra vedaant;","E shaastrano re, rahasya kahe kari khaant"],"en":"Yoga and Sankhya, Pancharatra and Vedant: the inner meaning of these shastras he tells with care.","gl":[["rahasya","inner meaning"],["khaant","eagerness, care"]],"no":4},{"id":"ch-172.5","gu":["જ્યારે હરિજન રે, દેશ દેશના આવે;","ઉત્સવ ઉપર રે, પૂજા બહુવિધ લાવે"],"ro":["Jyaare harijan re, desh deshnaa aave;","Utsav upar re, pujaa bahuvidh laave"],"en":"When devotees come from land after land for a festival, they bring puja of many kinds.","gl":[["utsav","festival"],["bahuvidh","of many kinds"]],"no":5},{"id":"ch-172.6","gu":["જાણી પોતાના રે, સેવકજન અવિનાશી;","તેમની પૂજા રે, ગ્રહણ કરે સુખરાશી"],"ro":["Jaani potaanaa re, sevakjan avinaashi;","Temni pujaa re, grahan kare sukhraashi"],"en":"Knowing them as his own servants, the Imperishable, the treasury of joy, accepts their puja.","gl":[["avinaashi","the Imperishable"],["sukhraashi","a heap of joy"]],"no":6},{"id":"ch-172.7","gu":["ભક્ત પોતાના રે, તેને શ્યામ સુજાણ;","ધ્યાન કરાવી રે, ખેંચે નાડી પ્રાણ"],"ro":["Bhakt potaanaa re, tene shyaam sujaan;","Dhyaan karaavi re, khenche naadi praan"],"en":"For his own devotees, wise Shyam guides them into dhyan and draws in their nadis and prana.","gl":[["sujaan","wise, all-knowing"],["naadi","the body's subtle channels"],["praan","life-breath"]],"note":"That is, he took them into samadhi.","no":7},{"id":"ch-172.8","gu":["ધ્યાનમાંથી રે, ઉઠાડે નિજ જનને;","દેહમાં લાવે રે, પ્રાણ ઇન્દ્રિય મનને"],"ro":["Dhyaanmaanthi re, uthaade nij janne;","Dehmaa laave re, praan indriy manne"],"en":"And he raises his own people out of dhyan, bringing their prana, senses and mind back into the body.","gl":[["indriy","the senses"]],"no":8},{"id":"ch-172.9","gu":["સંત સભામાં રે, બેઠા હોય અવિનાશ;","કોઈ હરિજનને રે, તેડવો હોય પાસ"],"ro":["Sant sabhaamaa re, bethaa hoy avinaash;","Koi harijanne re, tedvo hoy paas"],"en":"When the Imperishable is sitting in the assembly of Sants and wants to call some devotee near,","gl":[["tedvo","to call over"]],"no":9},{"id":"ch-172.10","gu":["પહેલી આંગળી રે, નેત્રતણી કરી સાન;","પ્રેમાનંદ કહે રે, સાદ કરે ભગવાન"],"ro":["Paheli aangli re, netra-tani kari saan;","Premanand kahe re, saad kare bhagvaan"],"chhap":1,"en":"he beckons with his first finger and his eyes; says Premanand, that is how Bhagwan calls.","gl":[["paheli aangli","the first finger"],["saan","a sign, a signal"],["saad","a call"]],"no":10}]},{"n":173,"id":"ch-173","name":"Mohanjini re, lilaa ati sukhkaari","pad":4,"ref":"Kirtan Muktavali 1-173","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-173.1","gu":["મોહનજીની રે, લીલા અતિ સુખકારી;","આનંદ આપે રે, સુણતાં ન્યારી ન્યારી"],"ro":["Mohanjini re, lilaa ati sukhkaari;","Aanand aape re, suntaa nyaari nyaari"],"en":"Mohan's lilas give great joy; heard one by one, each delights in its own way.","gl":[["Mohan","the Enchanter, a name of God"],["nyaari nyaari","each in its own way"]],"no":1},{"id":"ch-173.2","gu":["ક્યારેક વાતો રે, કરે મુનિવર સાથે;","ગુચ્છ ગુલાબના રે, ચોળે છે બે હાથે"],"ro":["Kyaarek vaato re, kare munivar saathe;","Guchchh gulaabnaa re, chole chhe be haathe"],"en":"Sometimes, as he talks with the munis, he crushes bunches of roses in both hands.","gl":[["guchchh","bunch"],["chole","rubs, crushes"]],"no":2},{"id":"ch-173.3","gu":["શીતળ જાણી રે, લીંબુ હાર ગુલાબી;","તેને રાખે રે, આંખ્યો ઉપર દાબી"],"ro":["Shital jaani re, limbu haar gulaabi;","Tene raakhe re, aankhyo upar daabi"],"en":"Knowing them to be cooling, he keeps a lime and a rose garland pressed over his eyes.","gl":[["shital","cooling"],["daabi","pressed down"]],"no":3},{"id":"ch-173.4","gu":["ક્યારેક પોતે રે, રાજીપામાં હોયે;","વાતો કરે રે, કથા વંચાવે તોયે"],"ro":["Kyaarek pote re, raajipaamaa hoye;","Vaato kare re, kathaa vanchaave toye"],"en":"Sometimes, when he is in a happy mood, he talks, and also has katha read.","gl":[["raajipo","pleasure, a happy mood"]],"no":4},{"id":"ch-173.5","gu":["સાંભળે કીર્તન રે, પોતે કાંઈક વિચારે;","પૂછવા આવે રે, જમવાનું કોઈ ત્યારે"],"ro":["Saambhle kirtan re, pote kaanik vichaare;","Puchhvaa aave re, jamvaanu koi tyaare"],"en":"He listens to kirtan and turns something over in his mind; just then someone comes to ask him to eat,","gl":[["vichaare","ponders"],["jamvaanu","the meal"]],"no":5},{"id":"ch-173.6","gu":["હાર ચઢાવે રે, પૂજા કરવા આવે;","તેના ઉપર રે, બહુ ખીજી રીસાવે"],"ro":["Haar chadhaave re, pujaa karvaa aave;","Tenaa upar re, bahu khiji risaave"],"en":"or comes to put a garland on him and do puja, and he gets quite cross with them.","gl":[["haar chadhaave","puts a garland on"],["khiji","annoyed"],["risaave","shows displeasure"]],"note":"When he was absorbed in thought, he did not like to be pulled out of it.","no":6},{"id":"ch-173.7","gu":["કથા સાંભળતાં રે, હરે હરે કહી બોલે;","મર્મ કથાનો રે, સુણી મગન થઈ ડોલે"],"ro":["Kathaa saambhaltaa re, hare hare kahi bole;","Marm kathaano re, suni magan thai dole"],"en":"Listening to katha he says, \"Hare, Hare\"; hearing the heart of the katha, he sways, absorbed.","gl":[["marm","the heart, the inner point"],["dole","sways"]],"no":7},{"id":"ch-173.8","gu":["ભાન કથામાં રે, બીજી ક્રિયા માંયે;","ક્યારેક અચાનક રે, જમતાં હરે બોલાયે"],"ro":["Bhaan kathaamaa re, biji kriyaa maanye;","Kyaarek achaanak re, jamtaa hare bolaaye"],"en":"His attention stays on the katha even amid other things; sometimes, all of a sudden, he says \"Hare\" while eating.","gl":[["bhaan","awareness, attention"],["achaanak","suddenly"]],"check":"'biji kriyaa maanye' read as 'in the middle of other activity'","no":8},{"id":"ch-173.9","gu":["થાય સ્મૃતિ રે, પોતાને જ્યારે તેની;","થોડુંક હસે રે, ભક્ત સામું જોઈ બેની"],"ro":["Thaay smruti re, potaane jyaare teni;","Thodunk hase re, bhakt saamu joi beni"],"en":"When he catches himself doing it, he laughs a little, looking at the devotees, sister.","gl":[["smruti","becoming aware"],["beni","sister, the listener the poet speaks to"]],"no":9},{"id":"ch-173.10","gu":["એમ હરિ નિત નિત રે, આનંદ રસ વરસાવે;","એ લીલા રસ રે, જોઈ પ્રેમાનંદ ગાવે"],"ro":["Em hari nit nit re, aanand ras varsaave;","E lilaa ras re, joi Premanand gaave"],"chhap":1,"en":"So Hari rains down the nectar of joy every day; seeing that lila-nectar, Premanand sings.","gl":[["aanand ras","the nectar of joy"],["varsaave","rains down"]],"no":10}]},{"n":174,"id":"ch-174","name":"Saambhal sajni re, divya svarup muraari","pad":5,"ref":"Kirtan Muktavali 1-174","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-174.1","gu":["સાંભળ સજની રે, દિવ્ય સ્વરૂપ મુરારી;","કરે ચરિત્ર રે, મનુષ્ય વિગ્રહ ધારી"],"ro":["Saambhal sajni re, divya svarup muraari;","Kare charitra re, manushya vigrah dhaari"],"en":"Listen, friend: Murari, whose form is divine, performs his deeds having taken on a human body.","gl":[["Muraari","a name of God"],["divya","divine"],["vigrah","body, form"]],"no":1},{"id":"ch-174.2","gu":["થયા મનોહર રે, મોહન મનુષ્ય જેવા;","રૂપ અનુપમ રે, નિજ જનને સુખ દેવા"],"ro":["Thayaa manohar re, mohan manushya jevaa;","Rup anupam re, nij janne sukh devaa"],"en":"Mohan has become enchanting, looking just like a man; his form is matchless, to give joy to his own.","gl":[["manohar","enchanting"],["anupam","matchless"]],"no":2},{"id":"ch-174.3","gu":["ક્યારેક ઢોલિયે રે, બેસે શ્રી ઘનશ્યામ;","ક્યારેક બેસે રે, ચાકળે પૂરણકામ"],"ro":["Kyaarek dholiye re, bese shri Ghanshyaam;","Kyaarek bese re, chaakle purankaam"],"en":"Sometimes Shri Ghanshyam sits on a dholiyo; sometimes he whose every wish is fulfilled sits on a chaaklo.","gl":[["dholiyo","a wooden cot"],["chaaklo","a square cloth seat"],["purankaam","one with no unfulfilled wish"]],"no":3},{"id":"ch-174.4","gu":["ક્યારેક ગોદડું રે, ઓછાડે સહિત;","પાથર્યું હોય રે, તે પર બેસે પ્રીતે"],"ro":["Kyaarek goddu re, ochhaade sahit;","Paatharyu hoy re, te par bese prite"],"en":"Sometimes a quilt is spread out with its cover, and he lovingly sits on that.","gl":[["goddu","quilt, padded mattress"],["ochhaad","its cover sheet"]],"no":4},{"id":"ch-174.5","gu":["ક્યારેક ઢોલિયા રે, ઉપર તકિયો ભાળી;","તે પર બેસે રે, શ્યામ પલાંઠી વાળી"],"ro":["Kyaarek dholiyaa re, upar takiyo bhaali;","Te par bese re, shyaam palaanthi vaali"],"en":"Sometimes, seeing a pillow on the dholiyo, Shyam sits on it cross-legged.","gl":[["takiyo","pillow, bolster"],["palaanthi vaali","cross-legged"]],"no":5},{"id":"ch-174.6","gu":["ઘણુંક બેસે રે, તકિયે ઓઠીંગણ દઈને;","ક્યારેક ગોઠણ રે, બાંધે ખેસ લઈને"],"ro":["Ghanunk bese re, takiye othingan daine;","Kyaarek gothan re, baandhe khes laine"],"en":"Often he sits leaning against a pillow; sometimes he ties his knees with his khes.","gl":[["othingan","leaning back"],["gothan","knees"],["khes","a long shoulder cloth"]],"note":"Tying a cloth round the knees was a way of sitting comfortably for a long time.","no":6},{"id":"ch-174.7","gu":["ક્યારેક રાજી રે, થાય અતિશે આલી;","સંત હરિજનને રે, ભેટે બાથમાં ઘાલી"],"ro":["Kyaarek raaji re, thaay atishe aali;","Sant harijanne re, bhete baathmaa ghaali"],"en":"Sometimes, friend, he is so pleased that he takes Sants and devotees in his arms and embraces them.","gl":[["aali","friend"],["baath","an embrace"]],"no":7},{"id":"ch-174.8","gu":["ક્યારેક માથે રે, લઈ મેલે બે હાથ;","છાતી માંહે રે, ચરણકમળ દે નાથ"],"ro":["Kyaarek maathe re, lai mele be haath;","Chhaati maanhe re, charnakmal de naath"],"en":"Sometimes the Lord places both hands on their heads, and places his lotus feet upon their chests.","gl":[["chhaati","chest"],["charnakamal","lotus feet"]],"no":8},{"id":"ch-174.9","gu":["ક્યારેક આપે રે, હાર તોરા ગિરધારી;","ક્યારેક આપે રે, અંગનાં વસ્ત્ર ઉતારી"],"ro":["Kyaarek aape re, haar toraa girdhaari;","Kyaarek aape re, angnaa vastra utaari"],"en":"Sometimes Girdhari gives garlands and toras; sometimes he takes the clothes off his own body and gives them.","gl":[["toraa","flower sprays for the turban"],["Girdhaari","lifter of the mountain, a name of God"]],"no":9},{"id":"ch-174.10","gu":["ક્યારેક આપે રે, પ્રસાદીના થાળ;","પ્રેમાનંદ કહે રે, ભક્તતણા પ્રતિપાળ"],"ro":["Kyaarek aape re, prasaadinaa thaal;","Premanand kahe re, bhakta-tanaa pratipaal"],"chhap":1,"en":"Sometimes he gives platters of prasad. Says Premanand, he is the protector of his devotees.","gl":[["prasaadi","sanctified food"],["pratipaal","protector"]],"no":10}]},{"n":175,"id":"ch-175","name":"Evaa kare re, charitra paavankaari","pad":6,"ref":"Kirtan Muktavali 1-175","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-175.1","gu":["એવાં કરે રે, ચરિત્ર પાવનકારી;","શુકજી સરખા રે, ગાવે નિત સંભારી"],"ro":["Evaa kare re, charitra paavankaari;","Shukji sarkhaa re, gaave nit sambhaari"],"en":"Such purifying deeds he does that ones like Shukji sing of them, remembering them every day.","gl":[["paavankaari","purifying"],["Shukji","Shukdev, the sage who narrates the Bhagavat"]],"no":1},{"id":"ch-175.2","gu":["ક્યારેક જીભને રે, દાંત તળે દબાવે;","ડાબે જમણે રે, પડખે સહજ સ્વભાવે"],"ro":["Kyaarek jibhne re, daant tale dabaave;","Daabe jamne re, padkhe sahaj svabhaave"],"en":"Sometimes he presses his tongue under his teeth, quite naturally, to the left or the right side.","gl":[["dabaave","presses"],["padkhe","on the side"]],"no":2},{"id":"ch-175.3","gu":["છીંક જ્યારે આવે રે, ત્યારે રૂમાલ લઈને;","છીંક ખાયે રે, મુખ પર આડો દઈને"],"ro":["Chhink jyaare aave re, tyaare rumaal laine;","Chhink khaaye re, mukh par aado daine"],"en":"When a sneeze comes, he takes a handkerchief and sneezes holding it across his face.","gl":[["chhink","sneeze"],["aado","across, as a screen"]],"no":3},{"id":"ch-175.4","gu":["રમૂજ આણી રે, હસે અતિ ઘનશ્યામ;","મુખ પર આડો રે, રૂમાલ દઈ સુખધામ"],"ro":["Ramuj aani re, hase ati Ghanshyaam;","Mukh par aado re, rumaal dai sukhdhaam"],"en":"When something amuses him, Ghanshyam laughs a lot; the abode of joy holds a handkerchief across his mouth.","gl":[["ramuj aani","being amused"],["sukhdhaam","abode of joy"]],"no":4},{"id":"ch-175.5","gu":["ક્યારેક વાતું રે, કરતા થકા દેવ;","છેડે રૂમાલને રે, વળ દીધાની ટેવ"],"ro":["Kyaarek vaatu re, kartaa thakaa dev;","Chhede rumaalne re, val didhaani tev"],"en":"Sometimes, while talking, the Lord has a habit of twisting the end of his handkerchief.","gl":[["val","a twist"],["tev","habit"]],"no":5,"alt":[["didhaani","devaani"]]},{"id":"ch-175.6","gu":["અતિ દયાળુ રે, સ્વભાવ છે સ્વામીનો;","પરદુઃખહારી રે, વારી બહુનામીનો"],"ro":["Ati dayaalu re, svabhaav chhe svaamino;","Pardukhhaari re, vaari bahunaamino"],"en":"The Swami's nature is deeply compassionate; he takes away others' pain. I offer myself to the Lord of many names.","gl":[["dayaalu","compassionate"],["pardukhhaari","remover of others' pain"],["vaari","I offer myself to"]],"no":6},{"id":"ch-175.7","gu":["કોઈને દુઃખિયો રે, દેખી ન ખમાયે;","દયા આણી રે, અતિ આકળા થાયે"],"ro":["Koine dukhiyo re, dekhi na khamaaye;","Dayaa aani re, ati aaklaa thaaye"],"en":"He cannot bear to see anyone in pain; moved with compassion, he becomes very restless.","gl":[["khamaaye","be borne"],["aaklaa","restless, troubled"]],"no":7},{"id":"ch-175.8","gu":["અન્ન ધન વસ્ત્ર રે, આપીને દુઃખ ટાળે;","કરુણા દૃષ્ટિ રે, દેખી વાન જ વાળે"],"ro":["Ann dhan vastra re, aapine dukh taale;","Karunaa drushti re, dekhi vaan ja vaale"],"en":"He takes away their pain by giving food, money and clothes; with a look of compassion he brings the colour back to their faces.","gl":[["karunaa drushti","a look of compassion"],["vaan","colour, complexion"]],"check":"'dekhi vaan ja vaale' read as 'restores their colour'","no":8},{"id":"ch-175.9","gu":["ડાબે ખભે રે, ખેસ આડસોડે નાખી;","ચાલે જમણા રે, કરમાં રૂમાલ રાખી"],"ro":["Daabe khabhe re, khes aadsode naakhi;","Chaale jamnaa re, karmaa rumaal raakhi"],"en":"Throwing his khes across his left shoulder, he walks with a handkerchief in his right hand.","gl":[["aadsode","diagonally across"]],"no":9},{"id":"ch-175.10","gu":["ક્યારેક ડાબો રે, કર કેડ ઉપર મેલી;","ચાલે વહાલો રે, પ્રેમાનંદનો હેલી"],"ro":["Kyaarek daabo re, kar ked upar meli;","Chaale vahaalo re, Premanandno heli"],"chhap":1,"en":"Sometimes he walks with his left hand on his waist: Premanand's beloved, his dear friend.","gl":[["ked","waist"],["heli","dear friend, companion"]],"no":10}]},{"n":176,"id":"ch-176","name":"Nit nit nautam re, lilaa kare hariraay","pad":7,"ref":"Kirtan Muktavali 1-176","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-176.1","gu":["નિત નિત નૌતમ રે, લીલા કરે હરિરાય;","ગાતાં સુણતાં રે, હરિજન રાજી થાય"],"ro":["Nit nit nautam re, lilaa kare hariraay;","Gaataa suntaa re, harijan raaji thaay"],"en":"Every day Hari the king does ever-new lilas; singing and hearing them, the devotees are delighted.","gl":[["Hariraay","Hari the king"]],"no":1},{"id":"ch-176.2","gu":["સહજ સ્વભાવે રે, ઉતાવળા બહુ ચાલે;","હેત કરીને રે, બોલાવે બહુ વહાલે"],"ro":["Sahaj svabhaave re, utaavlaa bahu chaale;","Het karine re, bolaave bahu vahaale"],"en":"By nature he walks very fast; he speaks to people with great warmth and love.","gl":[["utaavlaa","quickly"],["bolaave","speaks to, calls"]],"no":2},{"id":"ch-176.3","gu":["ક્યારેક ઘોડલે રે, ચડવું હોય ત્યારે;","ક્યારેક સંતને રે, પીરસવા પધારે"],"ro":["Kyaarek ghodle re, chadvu hoy tyaare;","Kyaarek santne re, pirasvaa padhaare"],"en":"Sometimes when he is to ride a horse, or sometimes when he comes to serve food to the Sants,","gl":[["ghodlo","horse"],["pirasvaa","to serve food"]],"no":3,"alt":[["ghodle","ghode"]]},{"id":"ch-176.4","gu":["ત્યારે ડાબે રે, ખભે ખેસને આણી;","ખેસને બાંધે રે, કેડ સંગાથે તાણી"],"ro":["Tyaare daabe re, khabhe khesne aani;","Khesne baandhe re, ked sangaathe taani"],"en":"he brings his khes over his left shoulder and ties it tight around his waist.","gl":[["taani","pulling tight"]],"no":4},{"id":"ch-176.5","gu":["પીરસે લાડુ રે, જલેબી ઘનશ્યામ;","જણસ જમ્યાની રે, લઈ લઈ તેનાં નામ"],"ro":["Pirse laadu re, jalebi Ghanshyaam;","Janas jamyaani re, lai lai tenaa naam"],"en":"Ghanshyam serves laddus and jalebi, taking up each dish and calling out its name.","gl":[["janas","an item, a dish"]],"no":5},{"id":"ch-176.6","gu":["ફરે પંગતમાં રે, વારંવાર મહારાજ;","સંત હરિજનને રે, પીરસવાને કાજ"],"ro":["Fare pangatmaa re, vaaranvaar mahaaraaj;","Sant harijanne re, pirasvaane kaaj"],"en":"Maharaj goes round the rows again and again to serve the Sants and devotees.","gl":[["pangat","a row of people seated to eat"]],"no":6},{"id":"ch-176.7","gu":["શ્રદ્ધા ભક્તિ રે, અતિ ઘણી પીરસતાં;","કોઈના મુખમાં રે, આપે લાડુ હસતાં"],"ro":["Shraddhaa bhakti re, ati ghani pirastaa;","Koinaa mukhmaa re, aape laadu hastaa"],"en":"He serves with great shraddha and bhakti; laughing, he puts a laddu into someone's mouth.","gl":[["shraddhaa","faith, earnest care"]],"no":7},{"id":"ch-176.8","gu":["પાછલી રાત્રી રે, ચાર ઘડી રહે ત્યારે;","દાતણ કરવા રે, ઊઠે હરિ તે વારે"],"ro":["Paachhli raatri re, chaar ghadi rahe tyaare;","Daatan karvaa re, uthe hari te vaare"],"en":"When four ghadis of the night remain, Hari gets up then to clean his teeth.","gl":[["ghadi","24 minutes"],["daatan","a twig used as a toothbrush"]],"note":"Four ghadis is about an hour and a half before dawn.","no":8},{"id":"ch-176.9","gu":["ન્હાવા બેસે રે, નાથ પલાંઠી વાળી;","કર લઈ કળશ્યો રે, જળ ઢોળે વનમાળી"],"ro":["Nhaavaa bese re, naath palaanthi vaali;","Kar lai kalashyo re, jal dhole vanmaali"],"en":"The Lord sits cross-legged to bathe; Vanmali takes a water pot in his hand and pours the water over himself.","gl":[["kalashyo","a small water pot"],["dhole","pours"]],"no":9},{"id":"ch-176.10","gu":["કોરે વસ્ત્રે રે, કરી શરીરને લુવે;","પ્રેમાનંદ કહે રે, હરિજન સર્વે જુવે"],"ro":["Kore vastre re, kari sharirne luve;","Premanand kahe re, harijan sarve juve"],"chhap":1,"en":"He dries his body with a dry cloth. Says Premanand, all the devotees watch.","gl":[["kore vastre","with a dry cloth"],["luve","wipes dry"]],"no":10}]},{"n":177,"id":"ch-177","name":"Rudaa shobhe re, naahine ubhaa hoye","pad":8,"ref":"Kirtan Muktavali 1-177","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-177.1","gu":["રૂડા શોભે રે, નાહીને ઊભા હોયે;","વસ્ત્ર પહેરેલું રે, સાથળ વચ્ચે નીચોવે"],"ro":["Rudaa shobhe re, naahine ubhaa hoye;","Vastra paherelu re, saathal vachche nichove"],"en":"He looks beautiful standing after his bath; he wrings out the cloth he wore, between his thighs.","gl":[["nichove","wrings out"],["saathal","thigh"]],"no":1},{"id":"ch-177.2","gu":["પગ સાથળને રે, લુહીને સારંગપાણી;","કોરા ખેસને રે, પહેરે સારી પેઠે તાણી"],"ro":["Pag saathalne re, luhine saarangpaani;","Koraa khesne re, pahere saari pethe taani"],"en":"Sarangpani dries his legs and thighs, and puts on a dry khes, drawing it neatly round.","gl":[["Saarangpaani","holder of the Sharanga bow, a name of God"],["saari pethe","neatly, properly"]],"no":2},{"id":"ch-177.3","gu":["ઓઢી ઉપરણી રે, રેશમી કોરની વહાલે;","આવે જમવા રે, ચાખડિયે ચઢી ચાલે"],"ro":["Odhi uparni re, reshmi korni vahaale;","Aave jamvaa re, chaakhdiye chadhi chaale"],"en":"Lovingly he wraps on an upper cloth with a silk border, and comes to eat, walking in wooden sandals.","gl":[["uparni","upper cloth"],["reshmi kor","silk border"],["chaakhdi","wooden sandals"]],"no":3},{"id":"ch-177.4","gu":["માથે ઉપરણી રે, ઓઢી બેસે જમવા;","કાન ઉઘાડા રે, રાખે મુજને ગમવા"],"ro":["Maathe uparni re, odhi bese jamvaa;","Kaan ughaadaa re, raakhe mujne gamvaa"],"en":"With the upper cloth over his head he sits to eat, keeping his ears uncovered, which I love to see.","gl":[["mujne gamvaa","to my delight"]],"no":4},{"id":"ch-177.5","gu":["જમતાં ડાબા રે, પગની પલાંઠી વાળી;","તે પર ડાબો રે, કર મેલે વનમાળી"],"ro":["Jamtaa daabaa re, pagni palaanthi vaali;","Te par daabo re, kar mele vanmaali"],"en":"While eating he folds his left leg in, and Vanmali rests his left hand on it.","gl":[["daabo","left"],["mele","places"]],"no":5},{"id":"ch-177.6","gu":["જમણા પગને રે, રાખી ઊભો શ્યામ;","તે પર જમણો રે, કર મેલે સુખધામ"],"ro":["Jamnaa pagne re, raakhi ubho shyaam;","Te par jamno re, kar mele sukhdhaam"],"en":"Shyam keeps his right knee raised, and the abode of joy rests his right hand on it.","gl":[["jamno","right"],["ubho","upright, raised"]],"no":6},{"id":"ch-177.7","gu":["રૂડી રીતે રે, જમે દેવના દેવ;","વારે વારે રે, પાણી પીધાની ટેવ"],"ro":["Rudi rite re, jame devnaa dev;","Vaare vaare re, paani pidhaani tev"],"en":"The god of gods eats in a lovely way; his habit is to sip water again and again.","gl":[["rudi rite","beautifully, properly"],["vaare vaare","again and again"]],"no":7},{"id":"ch-177.8","gu":["જણસ સ્વાદુ રે, જણાયે જમતાં જમતાં;","પાસે હરિજન રે, બેઠા હોય મનગમતાં"],"ro":["Janas svaadu re, janaaye jamtaa jamtaa;","Paase harijan re, bethaa hoy mangamtaa"],"en":"When a dish tastes good as he eats, and devotees dear to him are sitting near,","gl":[["svaadu","tasty"],["mangamtaa","dear to him"]],"no":8},{"id":"ch-177.9","gu":["તેમને આપી રે, પછી પોતે જમે;","જમતાં જીવન રે, હરિજનને મન ગમે"],"ro":["Temne aapi re, pachhi pote jame;","Jamtaa jivan re, harijanne man game"],"en":"he gives some to them first, and then eats himself; watching Jivan eat delights the devotees' hearts.","gl":[["man game","is pleasing to the heart"]],"no":9},{"id":"ch-177.10","gu":["ફેરવે જમતાં રે, પેટ ઉપર હરિ હાથ;","ઓડકાર ખાય રે, પ્રેમાનંદના નાથ"],"ro":["Ferve jamtaa re, pet upar hari haath;","Odkaar khaay re, Premanandnaa naath"],"chhap":1,"en":"As he eats, Hari runs his hand over his stomach; Premanand's Lord gives a contented burp.","gl":[["odkaar","a burp, the sign of a satisfying meal"]],"no":10}]},{"n":178,"id":"ch-178","name":"Chalu kare re, mohan trupt thaine","pad":9,"ref":"Kirtan Muktavali 1-178","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-178.1","gu":["ચળું કરે રે, મોહન તૃપ્ત થઈને;","દાંતને ખોતરે રે, સળી રૂપાની લઈને"],"ro":["Chalu kare re, mohan trupt thaine;","Daantne khotre re, sali rupaani laine"],"en":"Satisfied, Mohan rinses his mouth and picks his teeth with a silver pick.","gl":[["chalu","rinsing the mouth after eating"],["sali","a small stick, a toothpick"],["rupaa","silver"]],"no":1},{"id":"ch-178.2","gu":["મુખવાસ લઈને રે, ઢોલિયે બિરાજે;","પૂજા કરે રે, હરિજન હેતે ઝાઝે"],"ro":["Mukhvaas laine re, dholiye biraaje;","Pujaa kare re, harijan hete jhaajhe"],"en":"Taking mukhvas, he sits on the dholiyo; the devotees do his puja with great love.","gl":[["mukhvaas","an after-meal mouth freshener"],["jhaajhe","abundant"]],"no":2},{"id":"ch-178.3","gu":["પાંપણ ઉપર રે, આંટો લઈ અલબેલો;","ફેંટો બાંધે રે, છોગું મેલી છેલો"],"ro":["Paampan upar re, aanto lai albelo;","Fento baandhe re, chhogu meli chhelo"],"en":"Winding a turn just above his eyes, the charming one ties his fento and tucks in a plume, so stylish.","gl":[["paampan","eyelid"],["aanto","a turn, a wind of cloth"],["fento","a turban"],["chhogu","plume, tassel"],["chhelo","dashing"]],"no":3},{"id":"ch-178.4","gu":["વર્ષા ઋતુને રે, શરદ ઋતુને જાણી;","ઘેલા નદીનાં રે, નિર્મળ નીર વખાણી"],"ro":["Varshaa rutune re, sharad rutune jaani;","Ghelaa nadinaa re, nirmal nir vakhaani"],"en":"Knowing it to be the rains or autumn, he praises the clear water of the Ghela river.","gl":[["varshaa","the rainy season"],["sharad","autumn, after the rains"],["Ghelaa","the river at Gadhada"]],"no":4},{"id":"ch-178.5","gu":["સંત હરિજનને રે, સાથે લઈ ઘનશ્યામ;","ન્હાવા પધારે રે, ઘેલે પૂરણકામ"],"ro":["Sant harijanne re, saathe lai Ghanshyaam;","Nhaavaa padhaare re, Ghele purankaam"],"en":"Taking Sants and devotees along, Ghanshyam, who wants for nothing, goes to bathe in the Ghela.","gl":[["padhaare","goes (said respectfully)"]],"no":5},{"id":"ch-178.6","gu":["બહુ જળક્રીડા રે, કરતાં જળમાં ન્હાય;","જળમાં તાળી રે, દઈને કીર્તન ગાય"],"ro":["Bahu jalakridaa re, kartaa jalmaa nhaay;","Jalmaa taali re, daine kirtan gaay"],"en":"He bathes, playing all kinds of water games; clapping in the water, he sings kirtan.","gl":[["jalkridaa","water play"]],"no":6},{"id":"ch-178.7","gu":["નાહીને બા’રે રે, નીસરી વસ્ત્ર પહેરી;","ઘોડે બેસી રે, ઘેર આવે રંગલહેરી"],"ro":["Naahine baa're re, nisri vastra paheri;","Ghode besi re, gher aave rangalheri"],"en":"After bathing he comes out, dresses, mounts his horse, and comes home, brimming with joy.","gl":[["nisri","coming out"],["rangalheri","one full of joyful spirit"]],"no":7},{"id":"ch-178.8","gu":["પાવન જશને રે, હરિજન ગાતા આવે;","જીવન જોઈને રે, આનંદ ઉર ન સમાવે"],"ro":["Paavan jashne re, harijan gaataa aave;","Jivan joine re, aanand ur na samaave"],"en":"The devotees come along singing his purifying glory; seeing Jivan, their joy cannot be held in the heart.","gl":[["jash","glory, fame"],["ur","heart"],["na samaave","cannot be contained"]],"no":8},{"id":"ch-178.9","gu":["ગઢપુરવાસી રે, જોઈને જગ આધાર;","સુફળ કરે છે રે, નેણાં વારમવાર"],"ro":["Gadhpurvaasi re, joine jag aadhaar;","Sufal kare chhe re, nenaa vaaramvaar"],"en":"The people of Gadhpur, seeing the support of the world, make their eyes fruitful again and again.","gl":[["Gadhpur","Gadhada"],["sufal","fruitful"],["nenaa","eyes"]],"no":9},{"id":"ch-178.10","gu":["આવી બિરાજે રે, ઓસરીયે બહુનામી;","ઢોલિયા ઉપર રે, પ્રેમાનંદના સ્વામી"],"ro":["Aavi biraaje re, osriye bahunaami;","Dholiyaa upar re, Premanandnaa svaami"],"chhap":1,"en":"The Lord of many names comes and sits on the dholiyo in the verandah: Premanand's Swami.","gl":[["osri","verandah"]],"no":10}]},{"n":179,"id":"ch-179","name":"Nij sevakne re, sukh devaane kaaj","pad":10,"ref":"Kirtan Muktavali 1-179","poet":"Premanand Swami","section":{"gu":"લીલા ચિંતામણિ","en":"Lila Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-179.1","gu":["નિજ સેવકને રે, સુખ દેવાને કાજ;","પોતે પ્રગટ્યા રે, પુરુષોત્તમ મહારાજ"],"ro":["Nij sevakne re, sukh devaane kaaj;","Pote pragatyaa re, Purushottam mahaaraaj"],"en":"To give joy to his own servants, Purushottam Maharaj himself has become manifest.","gl":[["pragatyaa","became manifest"]],"no":1},{"id":"ch-179.2","gu":["ફળિયામાંહી રે, સભા કરી વિરાજે;","પૂરણ શશી રે, ઉડુગણમાં જેમ છાજે"],"ro":["Faliyaamaanhi re, sabhaa kari viraaje;","Puran shashi re, uduganmaa jem chhaaje"],"en":"He holds assembly in the courtyard and sits there, shining like the full moon among the stars.","gl":[["faliyu","courtyard"],["shashi","moon"],["udugan","the host of stars"]],"no":2},{"id":"ch-179.3","gu":["બ્રહ્મરસ વરસી રે, તૃપ્ત કરે હરિજનને;","પોઢે રાત્રે રે, જમી શ્યામ શુદ્ધ અન્નને"],"ro":["Brahmaras varsi re, trupt kare harijanne;","Podhe raatre re, jami shyaam shuddh annane"],"en":"Raining the nectar of Brahman, he satisfies the devotees; at night Shyam eats pure food and lies down to rest.","gl":[["brahmaras","the bliss of Brahman"],["podhe","lies down to rest"]],"no":3},{"id":"ch-179.4","gu":["બે આંગળિયું રે, તિલક કર્યાની પેરે;","ભાલ વચ્ચે રે, ઊભી રાખી ફેરે"],"ro":["Be aangliyu re, tilak karyaani pere;","Bhaal vachche re, ubhi raakhi fere"],"en":"He holds two fingers upright at the middle of his forehead and moves them, as if drawing a tilak.","gl":[["bhaal","forehead"],["pere","in the manner of"]],"check":"'ubhi raakhi fere' read as 'holds them upright and moves them'","no":4},{"id":"ch-179.5","gu":["સૂતાં સૂતાં રે, માળા માગી લઈને;","જમણે હાથે રે, નિત ફેરવે ચિત્ત દઈને"],"ro":["Sutaa sutaa re, maalaa maagi laine;","Jamne haathe re, nit ferve chitt daine"],"en":"Lying down, he asks for a mala and every night turns it with his right hand, giving it his full attention.","gl":[["chitt dai","with full attention"]],"no":5},{"id":"ch-179.6","gu":["ભૂલ ન પડે રે, કેદી એવું નેમ;","ધર્મકુંવરની રે, સહજ પ્રકૃતિ એમ"],"ro":["Bhul na pade re, kedi evu nem;","Dharmakunvarni re, sahaj prakruti em"],"en":"He never once misses: such is his niyam. Such is the natural way of Dharmakunvar.","gl":[["nem","niyam, a daily observance"],["Dharmakunvar","son of Dharmadev, Maharaj"]],"no":6,"alt":[["nem","niyam"]]},{"id":"ch-179.7","gu":["ભર નિદ્રામાં રે, પોઢ્યા હોય મુનિરાયે;","કોઈ અજાણે રે, લગાર અડી જાયે"],"ro":["Bhar nidraamaa re, podhyaa hoy muniraaye;","Koi ajaane re, lagaar adi jaaye"],"en":"When the king of munis is deep in sleep, and someone unknowingly touches him even slightly,","gl":[["muniraay","king of munis"],["lagaar","even slightly"]],"no":7,"alt":[["adi","adki"]]},{"id":"ch-179.8","gu":["ત્યારે ફડકી રે, જાગે સુંદર શ્યામ;","‘કોણ છે?’ પૂછે રે, સેવકને સુખધામ"],"ro":["Tyaare fadki re, jaage sundar shyaam;","'Kon chhe?' puchhe re, sevakne sukhdhaam"],"en":"then beautiful Shyam wakes with a start, and the abode of joy asks his attendant, \"Who is it?\"","gl":[["fadki","with a start"],["sevak","attendant"]],"no":8},{"id":"ch-179.9","gu":["એવી લીલા રે, હરિની અનંત અપાર;","મેં તો ગાઈ રે, કાંઈક મતિ અનુસાર"],"ro":["Evi lilaa re, harini anant apaar;","Me to gaai re, kaanik mati anusaar"],"en":"Hari's lilas like these are endless, beyond measure; I have sung a little of them, as far as my understanding goes.","gl":[["anant apaar","endless, boundless"],["mati anusaar","as far as my understanding goes"]],"no":9},{"id":"ch-179.10","gu":["જે કોઈ પ્રીતે રે, શીખશે સુણશે ગાશે;","પ્રેમાનંદનો રે, સ્વામી રાજી થાશે"],"ro":["Je koi prite re, shikhshe sunshe gaashe;","Premanandno re, svaami raaji thaashe"],"chhap":1,"en":"Whoever lovingly learns, hears or sings this, Premanand's Swami will be pleased with them.","gl":[["raaji thaashe","will be pleased"]],"no":10}]},{"n":180,"id":"ch-180","name":"Oraa aavo shyaam sanehi","pad":null,"ref":"Kirtan Muktavali 1-180","poet":"Premanand Swami","section":{"gu":"ઓરા આવો શ્યામ સનેહી","en":"Oraa aavo shyaam sanehi"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-180.1","gu":["ઓરા આવો શ્યામ સનેહી, સુંદર વર જોઉં વ્હાલા;","જતન કરીને જીવન મારા, જીવમાંહી પ્રોઉં વ્હાલા"],"ro":["Oraa aavo shyaam sanehi, sundar var jou vhaalaa;","Jatan karine jivan maaraa, jivmaanhi prou vhaalaa"],"en":"Come close, loving Shyam, let me see you, my beautiful Beloved; carefully, my Life, let me thread you into my very soul.","gl":[["oraa","near"],["sanehi","loving"],["vhaalaa","Beloved"],["prou","thread (as beads on a string)"]],"no":1},{"id":"ch-180.2","gu":["ચિહ્ન અનુપમ અંગોઅંગનાં, સૂરતે સંભારું વ્હાલા;","નખશિખ નીરખી નૌતમ મારા, ઉરમાં ઉતારું વ્હાલા"],"ro":["Chihn anupam angoangnaa, surte sambhaaru vhaalaa;","Nakhshikh nirkhi nautam maaraa, urmaa utaaru vhaalaa"],"en":"With full attention I recall the matchless marks on every limb; gazing at you from toenail to crown, my ever-new one, I take you into my heart.","gl":[["chihn","marks"],["surte","with focused attention"],["nakhshikh","from toenail to crown"]],"no":2},{"id":"ch-180.3","gu":["અરુણ કમળસમ જુગલ ચરણની, શોભા અતિ સારી વ્હાલા;","ચિંતવન કરવા આતુર અતિ, મન વૃત્તિ મારી વ્હાલા"],"ro":["Arun kamalsam jugal charanni, shobhaa ati saari vhaalaa;","Chintvan karvaa aatur ati, man vrutti maari vhaalaa"],"en":"The beauty of your two feet, like dawn-red lotuses, is exquisite; my mind and its every thought long to contemplate them.","gl":[["arun","dawn-red"],["jugal","the pair"],["chintvan","contemplation"],["aatur","eager"]],"no":3},{"id":"ch-180.4","gu":["પ્રથમ તે ચિંતવન કરું, સુંદર સોળે ચિહ્ન વ્હાલા;","ઊર્ધ્વરેખા ઓપી રહી, અતિશે નવીન વ્હાલા"],"ro":["Pratham te chintvan karu, sundar sole chihn vhaalaa;","Urdhvarekhaa opi rahi, atishe navin vhaalaa"],"en":"First let me contemplate the sixteen beautiful marks. The urdhvarekha shines there, ever new.","gl":[["urdhvarekhaa","the upward line on the sole"],["opi rahi","shines"]],"no":4},{"id":"ch-180.5","gu":["અંગૂઠા આંગળી વચ્ચેથી, નીસરીને આવી વ્હાલા;","પાનીની બે કોરે જોતાં, ભક્તને મન ભાવી વ્હાલા"],"ro":["Anguthaa aangli vachchethi, nisrine aavi vhaalaa;","Paanini be kore jotaa, bhaktane man bhaavi vhaalaa"],"en":"It starts between the big toe and the next and comes down to the heel, seen on both sides; the devotee's heart delights in it.","gl":[["nisrine","emerging"],["paani","heel"]],"check":"the line's route read from 'paanini be kore'","no":5},{"id":"ch-180.6","gu":["જુગલ ચરણમાં કહું મનોહર, ચિહ્ન તેનાં નામ વ્હાલા;","શુદ્ધ મને કરી સંભારતાં, નાશ પામે કામ વ્હાલા"],"ro":["Jugal charanmaa kahu manohar, chihn tenaa naam vhaalaa;","Shuddh mane kari sambhaartaa, naash paame kaam vhaalaa"],"en":"Let me tell the names of the enchanting marks on both feet; remembering them with a pure mind, lust is destroyed.","gl":[["kaam","lust, desire"]],"no":6},{"id":"ch-180.7","gu":["અષ્ટકોણ ને ઊર્ધ્વરેખા, સ્વસ્તિક જાંબુ જવ વ્હાલા;","વજ્ર અંકુશ કેતુ ને પદ્મ, જમણે પગે નવ વ્હાલા"],"ro":["Ashtakon ne urdhvarekhaa, svastik jaambu jav vhaalaa;","Vajra ankush ketu ne padm, jamne page nav vhaalaa"],"en":"The eight-cornered sign, the urdhvarekha, the swastika, the jambu fruit and the barleycorn; the thunderbolt, the goad, the flag and the lotus: nine on the right foot.","gl":[["ashtakon","eight-cornered figure"],["jaambu","the jambu fruit"],["jav","barleycorn"],["vajra","thunderbolt"],["ankush","elephant goad"],["ketu","flag"],["padm","lotus"]],"note":"With the seven in the next stanza, these are the sixteen marks on Maharaj's feet.","no":7},{"id":"ch-180.8","gu":["ત્રિકોણ કળશ ને ગોપદ સુંદર, ધનુષ ને મીન વ્હાલા;","અર્ધચંદ્ર ને વ્યોમ સાત છે, ડાબે પગે ચિહ્ન વ્હાલા"],"ro":["Trikon kalash ne gopad sundar, dhanush ne min vhaalaa;","Ardhachandra ne vyom saat chhe, daabe page chihn vhaalaa"],"en":"The triangle, the water pot, the lovely cow's hoofprint, the bow and the fish; the half-moon and the sky: seven marks on the left foot.","gl":[["trikon","triangle"],["kalash","water pot"],["gopad","a cow's hoofprint"],["dhanush","bow"],["min","fish"],["ardhachandra","half-moon"],["vyom","sky"]],"no":8},{"id":"ch-180.9","gu":["જમણા પગના અંગૂઠાના, નખમાંહી ચિહ્ન વ્હાલા;","તે તો નીરખે જે કોઈ ભક્ત, પ્રીતિએ પ્રવીણ વ્હાલા"],"ro":["Jamnaa pagnaa anguthaanaa, nakhmaanhi chihn vhaalaa;","Te to nirkhe je koi bhakt, pritiye pravin vhaalaa"],"en":"In the nail of the right big toe there is a mark; the devotee who sees it is one skilled in love.","gl":[["pravin","skilled"]],"no":9},{"id":"ch-180.10","gu":["એ જ અંગૂઠાની પાસે, તિલ એક નૌતમ ધારું વ્હાલા;","પ્રેમાનંદ કહે નીરખું પ્રીતે, પ્રાણ લઈ વારું વ્હાલા"],"ro":["E ja anguthaani paase, til ek nautam dhaaru vhaalaa;","Premanand kahe nirkhu prite, praan lai vaaru vhaalaa"],"chhap":1,"en":"Right beside that same toe I hold in mind one lovely mole. Says Premanand, I gaze at it with love and offer my life over it.","gl":[["til","a mole, a beauty spot"],["vaaru","I offer up"]],"no":10,"alt":[["anguthaani paase","anguthaane baa're"]]}]},{"n":181,"id":"ch-181","name":"Have maaraa vahaalaane nahi re visaaru re","pad":1,"ref":"Kirtan Muktavali 1-181","poet":"Nishkulanand Swami","section":{"gu":"હવે મારા વહાલાને નહિ રે વિસારું રે","en":"Have maaraa vahaalaane nahi re visaaru re"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-181.1","gu":["હવે મારા વહાલાને નહિ રે વિસારું રે,","શ્વાસ ઉચ્છ્‍વાસે તે નિત્ય સંભારું રે"],"ro":["Have maaraa vahaalaane nahi re visaaru re,","Shvaas uchchhvaase te nitya sambhaaru re"],"en":"Now I will never forget my Beloved; with every breath in and out, I will always remember him.","gl":[["visaaru","forget"],["shvaas uchchhvaas","breathing in and out"]],"no":1,"alt":[["shvaas uchchhvaase","shvaasochchhvaase"]]},{"id":"ch-181.2","gu":["પડ્યું મારે સહજાનંદજી શું પાનું રે,","હવે હું તો કેમ કરી રાખીશ છાનું રે"],"ro":["Padyu maare Sahajanandji shu paanu re,","Have hu to kem kari raakhish chhaanu re"],"en":"My lot is cast with Sahajanandji now; how could I ever keep it secret?","gl":[["paanu padyu","I have come to deal with, my lot is cast with"],["chhaanu","hidden"]],"check":"'padyu maare … shu paanu' read as an idiom: 'my dealings are now with'","no":2},{"id":"ch-181.3","gu":["આવ્યું મારે હરિવર વરવાનું ટાણું રે,","એ વર ન મળે ખરચે નાણું રે"],"ro":["Aavyu maare harivar varvaanu taanu re,","E var na male kharche naanu re"],"en":"The hour has come for me to wed Hari, best of grooms; this groom cannot be had for money.","gl":[["taanu","the appointed hour"],["varvaanu","to wed"],["naanu","money"]],"note":"Nishkulanand speaks as a bride here; the feminine voice runs through the pad.","no":3},{"id":"ch-181.4","gu":["એ વર ભાગ્ય વિના નવ ભાવે રે,","એ સ્નેહ લગ્ન વિના નવ આવે રે"],"ro":["E var bhaagya vinaa nav bhaave re,","E sneh lagn vinaa nav aave re"],"en":"Without good fortune this groom does not appeal; without deep longing, this love does not come.","gl":[["bhaagya","good fortune"],["nav bhaave","does not appeal"]],"check":"'lagn' read as 'lagan', deep attachment; it could be 'lagna', marriage","no":4},{"id":"ch-181.5","gu":["દુરિજન મન રે માને તેમ કહેજ્યો રે,","સ્વામી મારા હૃદયાની ભીતર રહેજ્યો રે"],"ro":["Durijan man re maane tem kahejyo re,","Svaami maaraa hrudyaani bhitar rahejyo re"],"en":"Let the ill-wishers say whatever they like; my Swami, stay within my heart.","gl":[["durijan","the ill-intentioned"],["bhitar","within"]],"no":5},{"id":"ch-181.6","gu":["હવે હું તો પૂરણ પદવીને પામી રે,","મળ્યા મુને નિષ્કુળાનંદના સ્વામી રે"],"ro":["Have hu to puran padvine paami re,","Malyaa mune Nishkulanandnaa svaami re"],"chhap":1,"en":"Now I have reached the complete, highest state: Nishkulanand's Swami has met me.","gl":[["puran padvi","the complete, highest state"]],"no":6}]},{"n":182,"id":"ch-182","name":"Have maaraa vahaalaanaa darshan saaru","pad":2,"ref":"Kirtan Muktavali 1-182","poet":"Nishkulanand Swami","section":{"gu":"હવે મારા વહાલાને નહિ રે વિસારું રે","en":"Have maaraa vahaalaane nahi re visaaru re"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-182.1","gu":["હવે મારા વહાલાનાં દર્શન સારુ,","હરિજન આવે હજારે હજારું"],"ro":["Have maaraa vahaalaanaa darshan saaru,","Harijan aave hajaare hajaaru"],"en":"Now, for the darshan of my Beloved, devotees come in their thousands upon thousands.","gl":[["hajaare hajaaru","thousands upon thousands"]],"no":1},{"id":"ch-182.2","gu":["ઢોલિયે બિરાજે સહજાનંદ સ્વામી,","પૂરણ પુરુષોત્તમ અંતરજામી"],"ro":["Dholiye biraaje Sahajanand svaami,","Puran Purushottam antarjaami"],"en":"Sahajanand Swami sits on the dholiyo: the complete Purushottam, the knower of every heart.","gl":[["antarjaami","the one within, who knows every heart"]],"no":2},{"id":"ch-182.3","gu":["સભા મધ્યે બેઠાં મુનિનાં વૃંદ;","તેમાં શોભે તારે વીંટ્યો જેમ ચંદ્ર"],"ro":["Sabhaa madhye bethaa muninaa vrund;","Temaa shobhe taare vintyo jem chandra"],"en":"Groups of munis sit in the assembly; among them he shines like the moon ringed by stars.","gl":[["vrund","group"],["vintyo","surrounded"]],"no":3},{"id":"ch-182.4","gu":["દુર્ગપુર ખેલ રચ્યો અતિ ભારી,","ભેળા રમે સાધુ અને બ્રહ્મચારી"],"ro":["Durgapur khel rachyo ati bhaari,","Bhelaa rame saadhu ane brahmachaari"],"en":"At Durgapur he set up a grand game; sadhus and brahmacharis play along with him.","gl":[["Durgapur","Gadhada"],["khel","play, a game"]],"check":"the clapping and dhun in the next stanza suggest a raas; the text says only 'khel'","no":4},{"id":"ch-182.5","gu":["તાળી પડે ઊપડતી અતિ સારી,","ધૂન્ય થાય ચૌદ લોક થકી ન્યારી"],"ro":["Taali pade upadti ati saari,","Dhunya thaay chaud lok thaki nyaari"],"en":"The clapping rises beautifully; the dhun that sounds is unlike anything in the fourteen worlds.","gl":[["dhunya","dhun, a chant"],["chaud lok","the fourteen worlds"],["nyaari","beyond, unlike"]],"no":5},{"id":"ch-182.6","gu":["પાઘલડીમાં છોગલિયું અતિ શોભે,","જોઈ જોઈ હરિજનનાં મન લોભે"],"ro":["Paaghaldimaa chhogliyu ati shobhe,","Joi joi harijannaa man lobhe"],"en":"The little plume in his pagh looks so fine; gazing at it again and again, the devotees' hearts are drawn.","gl":[["paaghaldi","turban"],["chhogliyu","plume"],["lobhe","are drawn, enchanted"]],"no":6},{"id":"ch-182.7","gu":["પધાર્યા વહાલો સર્વે તે સુખના રાશી,","સહજાનંદ અક્ષરધામના વાસી"],"ro":["Padhaaryaa vahaalo sarve te sukhnaa raashi,","Sahajanand Akshardhaamnaa vaasi"],"en":"The Beloved has come, the treasury of all joy: Sahajanand, who dwells in Akshardham.","gl":[["sukhnaa raashi","a heap of joy"],["vaasi","dweller"]],"no":7},{"id":"ch-182.8","gu":["ભાંગી મારી જન્મોજનમની ખામી,","મળ્યા મુને નિષ્કુળાનંદના સ્વામી"],"ro":["Bhaangi maari janmojnamni khaami,","Malyaa mune Nishkulanandnaa svaami"],"chhap":1,"en":"The lack of birth after birth is broken: Nishkulanand's Swami has met me.","gl":[["janmojanam","birth after birth"],["khaami","lack, shortfall"]],"no":8}]},{"n":183,"id":"ch-183","name":"Podhe prabhu sakal munike shyaam","pad":null,"ref":"Kirtan Muktavali 1-183","poet":"Muktanand Swami","section":{"gu":"પોઢે પ્રભુ સકલ મુનિકે શ્યામ","en":"Podhe prabhu sakal munike shyaam"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-183.0","gu":["પોઢે પ્રભુ સકલ મુનિકે શ્યામ;","સ્વામિનારાયણ દિવ્ય મૂર્તિ, સંતનકે વિશ્રામ"],"ro":["Podhe prabhu sakal munike shyaam;","Swaminarayan divya murti, santanke vishraam"],"en":"The Lord, the Shyam of all the munis, lies down to rest: Swaminarayan, the divine murti, the rest of the Sants.","gl":[["podhe","lies down to rest"],["santanke vishraam","the resting place of the Sants"]],"note":"This one is in Braj, close to Hindi.","no":0,"tek":1},{"id":"ch-183.1","gu":["અક્ષર પર આનંદઘન પ્રભુ, કિયો હે ભૂપર ઠામ;","જેહી મિલત જન તરત માયા, લહત અક્ષરધામ"],"ro":["Akshar par aanandghan prabhu, kiyo he bhupar thaam;","Jehi milat jan tarat maayaa, lahat Akshardhaam"],"en":"The Lord, solid bliss beyond Akshar, has made his home on earth; meeting him, people cross maya and attain Akshardham.","gl":[["aanandghan","bliss in solid form"],["bhupar","on earth"],["thaam","home, place"],["tarat","cross over"],["lahat","attain"]],"no":1,"back":"Podhe"},{"id":"ch-183.2","gu":["શારદ શેષ મહેશ મહામુનિ, જપત જેહી ગુણનામ;","જાસ પદરજ શીશ ધરી ધરી, હોત જન નિષ્કામ"],"ro":["Shaarad Shesh Mahesh mahaamuni, japat jehi gunnaam;","Jaas padraj shish dhari dhari, hot jan nishkaam"],"en":"Sharad, Shesh, Mahesh and the great munis chant his virtues and names; placing the dust of his feet on their heads again and again, people become free of desire.","gl":[["Shaarad","Saraswati, goddess of speech"],["Shesh","the thousand-headed serpent"],["Mahesh","Shiva"],["padraj","dust of the feet"],["nishkaam","free of desire"]],"no":2,"back":"Podhe"},{"id":"ch-183.3","gu":["પ્રેમકે પર્યંક પર પ્રભુ, કરત સુખ આરામ;","મુક્તાનંદ નિજ ચરણ ઢિગ ગુન, ગાવત આઠું જામ"],"ro":["Premke paryank par prabhu, karat sukh aaraam;","Muktanand nij charan dhig gun, gaavat aathu jaam"],"chhap":1,"en":"On a couch of love the Lord rests at ease; Muktanand, close to his feet, sings his virtues all eight watches of the day.","gl":[["paryank","couch, bed"],["dhig","near"],["aathu jaam","all eight watches, day and night"]],"no":3,"back":"Podhe"}],"note":"Sung while doing dhyan (meditation)."},{"n":184,"id":"ch-184","name":"Re shyaam tame saachu naanu","pad":null,"ref":"Kirtan Muktavali 1-184","poet":"Muktanand Swami","section":{"gu":"રે શ્યામ તમે સાચું નાણું","en":"Re shyaam tame saachu naanu"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-184.0","gu":["રે શ્યામ તમે સાચું નાણું, બીજું સર્વે દુઃખદાયક જાણું"],"ro":["Re shyaam tame saachu naanu, biju sarve dukhdaayak jaanu"],"en":"O Shyam, you are the true coin; everything else, I know, brings only pain.","gl":[["saachu naanu","true coin, the real thing"],["dukhdaayak","pain-giving"]],"no":0,"tek":1},{"id":"ch-184.1","gu":["રે તમ વિના સુખ સંપત કહાવે, તે તો સર્વે મહાદુઃખ ઉપજાવે;","અંતે એમાં કામ કોઈ નાવે"],"ro":["Re tam vinaa sukh sampat kahaave, te to sarve mahaadukh upjaave;","Ante emaa kaam koi naave"],"en":"Whatever passes for happiness and wealth without you, all of it only breeds great pain; in the end none of it is any use.","gl":[["sampat","wealth"],["kaam naave","is no use"]],"no":1,"back":"Re shyaam"},{"id":"ch-184.2","gu":["રે મૂરખ લોક મરે ભટકી, જૂઠા સંગે હારે શિર પટકી;","તેથી મારી મનવૃત્તિ અટકી"],"ro":["Re murakh lok mare bhatki, juthaa sange haare shir patki;","Tethi maari manvrutti atki"],"en":"Foolish people wander till they die; in the company of what is false they lose, beating their heads. So my mind has stopped going that way.","gl":[["bhatki","wandering"],["shir patki","beating the head"],["manvrutti","the mind's leaning"]],"check":"'atki' read as 'stopped (turning to the world)'; it could be 'is caught (on you)'","no":2,"back":"Re shyaam"},{"id":"ch-184.3","gu":["રે અખંડ અલૌકિક સુખ સારુ, રે જોઈ જોઈ મન મોહ્યું મારું;","ધરા ધન તમ ઉપર વારું"],"ro":["Re akhand alaukik sukh saaru, re joi joi man mohyu maaru;","Dharaa dhan tam upar vaaru"],"en":"You are unbroken, otherworldly joy; gazing at you again and again, my mind is captivated. I would offer up the earth and all its wealth over you.","gl":[["akhand","unbroken"],["alaukik","not of this world"],["dharaa","the earth"]],"check":"'sukh saaru' read as 'the true joy'; it could be 'for the sake of joy'","no":3,"back":"Re shyaam"},{"id":"ch-184.4","gu":["રે બ્રહ્માથી કીટ લગી જોયું, જૂઠું સુખ જાણીને વગોવ્યું;","મુક્તાનંદ મન તમ સંગ મોહ્યું"],"ro":["Re brahmaathi kit lagi joyu, juthu sukh jaanine vagovyu;","Muktanand man tam sang mohyu"],"chhap":1,"en":"From Brahma down to the insect I have looked; knowing their happiness to be false, I have spurned it. Muktanand's mind is captivated by you.","gl":[["kit","insect"],["vagovyu","spurned, disowned"]],"no":4,"back":"Re shyaam"}]},{"n":185,"id":"ch-185","name":"Vandu Sahajanand rasrup","pad":1,"ref":"Kirtan Muktavali 1-185","poet":"Premanand Swami (as Premsakhi)","section":{"gu":"ધ્યાન ચિંતામણિ","en":"Dhyan Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-185.1","gu":["વંદું સહજાનંદ રસરૂપ, અનુપમ સારને રે લોલ;","જેને ભજતાં છૂટે ફંદ, કરે ભવ પારને રે લોલ"],"ro":["Vandu Sahajanand rasrup, anupam saarne re lol;","Jene bhajtaa chhute fand, kare bhav paarne re lol"],"en":"I bow to Sahajanand, whose form is bliss, the matchless essence; worshipping him, the snare falls away and he carries one across the ocean of births.","gl":[["rasrup","whose form is bliss"],["fand","snare, noose"],["bhav","the round of births"]],"note":"'Re lol' is a sung refrain with no meaning of its own. From here on the poet goes over Maharaj's form limb by limb, as an aid to dhyan.","no":1},{"id":"ch-185.2","gu":["સમરું પ્રગટ રૂપ સુખધામ, અનુપમ નામને રે લોલ;","જેને ભવ બ્રહ્માદિક દેવ, ભજે તજી કામને રે લોલ"],"ro":["Samru pragat rup sukhdhaam, anupam naamne re lol;","Jene bhav brahmaadik dev, bhaje taji kaamne re lol"],"en":"I remember the manifest form, the abode of joy, the matchless name, whom Bhav, Brahma and the gods worship, leaving desire behind.","gl":[["samru","I remember"],["pragat","manifest, present"],["Bhav","Shiva"]],"no":2},{"id":"ch-185.3","gu":["જે હરિ અક્ષરબ્રહ્મ આધાર, પાર કોઈ નવ લહે રે લોલ;","જેને શેષ સહસ્રમુખ ગાય, નિગમ નેતિ કહે રે લોલ"],"ro":["Je hari Aksharbrahma aadhaar, paar koi nav lahe re lol;","Jene Shesh sahasramukh gaay, nigam neti kahe re lol"],"en":"That Hari is the support of Akshar Brahma; no one finds his end. Shesh sings of him with a thousand mouths, and the Vedas say, 'Not this, not this.'","gl":[["aadhaar","support"],["nigam","the Vedas"],["neti","'not this': beyond all description"]],"no":3},{"id":"ch-185.4","gu":["વર્ણવું સુંદર રૂપ અનુપ, જુગલ ચરણે નમી રે લોલ;","નખશિખ પ્રેમસખીના નાથ, રહો ઉરમાં રમી રે લોલ"],"ro":["Varnavu sundar rup anup, jugal charne nami re lol;","Nakhshikh Premsakhinaa naath, raho urmaa rami re lol"],"chhap":1,"en":"Bowing at your two feet, I describe your matchless, beautiful form. Lord of Premsakhi, from toenail to crown, stay delighting in my heart.","gl":[["varnavu","I describe"],["rami","delighting, at play"],["Premsakhi","'friend in love', Premanand Swami's pen name"]],"no":4}],"note":"Premanand Swami sang Vandu Sahajanand before Shriji Maharaj, who praised these songs for dhyan: see Vachanamrut Gadhada II-48."},{"n":186,"id":"ch-186","name":"Aavo maaraa mohan mithdaa laal","pad":2,"ref":"Kirtan Muktavali 1-186","poet":"Premanand Swami (as Premsakhi)","section":{"gu":"ધ્યાન ચિંતામણિ","en":"Dhyan Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-186.1","gu":["આવો મારા મોહન મીઠડા લાલ, કે જોઉં તારી મૂરતિ રે લોલ;","જતન કરી રાખું રસિયા રાજ, વિસારું નહિ ઉરથી રે લોલ"],"ro":["Aavo maaraa mohan mithdaa laal, ke jou taari murti re lol;","Jatan kari raakhu rasiyaa raaj, visaaru nahi urthi re lol"],"en":"Come, my sweet, dear Mohan, that I may see your murti; I'll keep you with care, my beloved king, and never let you slip from my heart.","gl":[["mithdaa","sweet"],["rasiyaa","the beloved, one full of delight"],["murti","form"]],"no":1},{"id":"ch-186.2","gu":["મન મારું મોહ્યું મોહનલાલ, પાઘલડીની ભાતમાં રે લોલ;","આવો ઓરા છોગલાં ખોસું છેલ, ખાંતિલા જોઉં ખાંતમાં રે લોલ"],"ro":["Man maaru mohyu mohanlaal, paaghaldini bhaatmaa re lol;","Aavo oraa chhoglaa khosu chhel, khaantilaa jou khaantmaa re lol"],"en":"My mind is captivated, Mohanlal, by the pattern of your pagh. Come close, my dashing one, let me tuck in the plumes and gaze at you to my heart's content.","gl":[["bhaat","pattern, design"],["chhoglaa","plumes"],["khosu","I tuck in"],["khaant","eagerness"]],"check":"'khaantilaa jou khaantmaa' read loosely; 'khaantilaa' may mean 'finely made'","no":2},{"id":"ch-186.3","gu":["વહાલા તારું ઝળકે સુંદર ભાલ, તિલક રૂડાં કર્યાં રે લોલ;","વહાલા તારા વામ કરણમાં તિલ, તેણે મનડાં હર્યાં રે લોલ"],"ro":["Vahaalaa taaru jhalke sundar bhaal, tilak rudaa karyaa re lol;","Vahaalaa taaraa vaam karanmaa til, tene mandaa haryaa re lol"],"en":"Beloved, your beautiful forehead gleams with a lovely tilak; Beloved, there is a mole on your left ear, and it has stolen hearts.","gl":[["bhaal","forehead"],["vaam karan","left ear"],["haryaa","stole"]],"no":3},{"id":"ch-186.4","gu":["વહાલા તારી ભૃકુટિને બાણે શ્યામ, કાળજ મારાં કોરિયાં રે લોલ;","નેણે તારે પ્રેમસખીના નાથ, કે ચિત્ત મારાં ચોરિયાં રે લોલ"],"ro":["Vahaalaa taari bhrukutine baane shyaam, kaalaj maaraa koriyaa re lol;","Nene taare Premsakhinaa naath, ke chitt maaraa choriyaa re lol"],"chhap":1,"en":"Beloved Shyam, the arrows of your brows have pierced my heart; Lord of Premsakhi, your eyes have stolen my mind.","gl":[["bhrukuti","eyebrows"],["baan","arrow"],["kaalaj","the heart (literally the liver)"],["koriyaa","pierced"]],"no":4}],"note":"Premanand Swami sang Vandu Sahajanand before Shriji Maharaj, who praised these songs for dhyan: see Vachanamrut Gadhada II-48."},{"n":187,"id":"ch-187","name":"Vahaalaa mune vash kidhi Ghanshyaam","pad":3,"ref":"Kirtan Muktavali 1-187","poet":"Premanand Swami (as Premsakhi)","section":{"gu":"ધ્યાન ચિંતામણિ","en":"Dhyan Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-187.1","gu":["વહાલા મુને વશ કીધી ઘનશ્યામ, વા’લપ તારા વા’લમાં રે લોલ;","મન મારું તલખે જોવા કાજ, ટીબકડી છે ગાલમાં રે લોલ"],"ro":["Vahaalaa mune vash kidhi Ghanshyaam, vaa'lap taaraa vaa'lamaa re lol;","Man maaru talkhe jovaa kaaj, tibakdi chhe gaalmaa re lol"],"en":"Beloved Ghanshyam, you have won me over with the love in your love; my mind aches to see the little mark on your cheek.","gl":[["vash","under your sway"],["vaa'lap","tenderness"],["talkhe","aches, longs"],["tibakdi","a little dot or mark"]],"check":"'tibakdi': a mole or a dimple","no":1},{"id":"ch-187.2","gu":["વહાલા તારી નાસિકા નમણી નાથ, અધરબિંબ લાલ છે રે લોલ;","છેલા મારા પ્રાણ કરું કુરબાન, જોયા જેવી ચાલ છે રે લોલ"],"ro":["Vahaalaa taari naasikaa namni naath, adharbimb laal chhe re lol;","Chhelaa maaraa praan karu kurbaan, joyaa jevi chaal chhe re lol"],"en":"Beloved, your nose is finely shaped, Lord, and your lips red as the bimba fruit; my dashing one, I would give my life for you; your walk is a sight to see.","gl":[["namni","graceful"],["adharbimb","lips like the red bimba fruit"],["kurbaan","given up, sacrificed"],["chaal","walk, gait"]],"no":2},{"id":"ch-187.3","gu":["વહાલા તારા દંત દાડમના બીજ, ચતુરાઈ ચાવતા રે લોલ;","વહાલા મારા પ્રાણ હરો છો નાથ, મીઠું મીઠું ગાવતા રે લોલ"],"ro":["Vahaalaa taaraa dant daadamnaa bij, chaturaai chaavtaa re lol;","Vahaalaa maaraa praan haro chho naath, mithu mithu gaavtaa re lol"],"en":"Beloved, your teeth are pomegranate seeds, chewing so elegantly; Beloved, you steal my life, Lord, singing so sweetly.","gl":[["daadam","pomegranate"],["chaturaai","finesse, elegance"]],"no":3},{"id":"ch-187.4","gu":["વહાલા તારે હસવે હરાણું ચિત્ત, બીજું હવે નવ ગમે રે લોલ;","મન મારું પ્રેમસખીના નાથ, કે તમ કેડે ભમે રે લોલ"],"ro":["Vahaalaa taare hasve haraanu chitt, biju have nav game re lol;","Man maaru Premsakhinaa naath, ke tam kede bhame re lol"],"chhap":1,"en":"Beloved, your laughter has stolen my mind; nothing else appeals now. Lord of Premsakhi, my mind wanders after you.","gl":[["haraanu","was stolen"],["kede bhame","follows after"]],"no":4}],"note":"Premanand Swami sang Vandu Sahajanand before Shriji Maharaj, who praised these songs for dhyan: see Vachanamrut Gadhada II-48."},{"n":188,"id":"ch-188","name":"Rasiyaa joi rupaali kot","pad":4,"ref":"Kirtan Muktavali 1-188","poet":"Premanand Swami (as Premsakhi)","section":{"gu":"ધ્યાન ચિંતામણિ","en":"Dhyan Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-188.1","gu":["રસિયા જોઈ રૂપાળી કોટ, રૂડી રેખાવળી રે લોલ;","વહાલા મારું મનડું મળવા ચ્હાય, કે જાય ચિત્તડું ચળી રે લોલ"],"ro":["Rasiyaa joi rupaali kot, rudi rekhaavli re lol;","Vahaalaa maaru mandu malvaa chhaay, ke jaay chittadu chali re lol"],"en":"O beloved, seeing your lovely neck with its fine lines, my mind longs to meet you, and my heart is carried away.","gl":[["kot","neck"],["rekhaavli","a row of lines"],["chaay","longs"]],"check":"'jaay chittadu chali' read as 'my heart is carried away'","no":1},{"id":"ch-188.2","gu":["વહાલા તારી જમણી ભુજાને પાસ, રૂડાં તિલ ચાર છે રે લોલ;","વહાલા તારા કંઠ વચ્ચે તિલ એક, અનુપમ સાર છે રે લોલ"],"ro":["Vahaalaa taari jamni bhujaane paas, rudaa til chaar chhe re lol;","Vahaalaa taaraa kanth vachche til ek, anupam saar chhe re lol"],"en":"Beloved, near your right arm are four lovely moles; Beloved, in the middle of your throat is one mole, the matchless essence.","gl":[["bhujaa","arm"],["kanth","throat"]],"no":2},{"id":"ch-188.3","gu":["વહાલા તારા ઉરમાં વિણગુણ હાર, જોઈ નેણાં ઠરે રે લોલ;","વહાલા તે તો જાણે પ્રેમીજન, જોઈ નિત્ય ધ્યાન ધરે રે લોલ"],"ro":["Vahaalaa taaraa urmaa vingun haar, joi nenaa thare re lol;","Vahaalaa te to jaane premijan, joi nitya dhyaan dhare re lol"],"en":"Beloved, seeing the stringless garland on your chest, my eyes are soothed. Beloved, the loving ones know it: they see it and stay always in dhyan.","gl":[["ur","chest"],["vingun haar","a garland woven without thread"],["thare","are soothed, cooled"]],"check":"'vingun haar' read as a garland made without thread","no":3},{"id":"ch-188.4","gu":["રસિયા જોઈ તમારું રૂપ, રસિક જન ઘેલડા રે લોલ;","આવો વહાલા પ્રેમસખીના નાથ, સુંદરવર છેલડા રે લોલ"],"ro":["Rasiyaa joi tamaaru rup, rasik jan gheldaa re lol;","Aavo vahaalaa Premsakhinaa naath, sundarvar chheldaa re lol"],"chhap":1,"en":"O beloved, seeing your form, those who know its sweetness go mad with love. Come, Beloved, Lord of Premsakhi, my beautiful, dashing groom.","gl":[["rasik jan","those who relish God's beauty"],["gheldaa","mad with love"],["sundarvar","beautiful groom"]],"no":4}],"note":"Premanand Swami sang Vandu Sahajanand before Shriji Maharaj, who praised these songs for dhyan: see Vachanamrut Gadhada II-48."},{"n":189,"id":"ch-189","name":"Vahaalaa taari bhujaa jugal jagdish","pad":5,"ref":"Kirtan Muktavali 1-189","poet":"Premanand Swami (as Premsakhi)","section":{"gu":"ધ્યાન ચિંતામણિ","en":"Dhyan Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-189.1","gu":["વહાલા તારી ભુજા જુગલ જગદીશ, જોઈને જાઉં વારણે રે લોલ;","કરનાં લટકાં કરતા લાલ, આવોને મારે બારણે રે લોલ"],"ro":["Vahaalaa taari bhujaa jugal jagdish, joine jaau vaarne re lol;","Karnaa latkaa kartaa laal, aavone maare baarne re lol"],"en":"Beloved, Lord of the world, seeing your two arms I offer myself to them; dear one, swinging your hands gracefully, come to my door.","gl":[["jaau vaarne","I offer myself"],["latkaa","graceful movements"],["baarne","to the door"]],"no":1},{"id":"ch-189.2","gu":["વહાલા તારી આંગળિયુંની રેખા, નખમણિ જોઈને રે લોલ;","વહાલા મારા ચિત્તમાં રાખું ચોરી, કહું નહિ કોઈને રે લોલ"],"ro":["Vahaalaa taari aangliyunni rekhaa, nakhamni joine re lol;","Vahaalaa maaraa chittamaa raakhu chori, kahu nahi koine re lol"],"en":"Beloved, seeing the lines of your fingers and your jewel-like nails, Beloved, I keep them hidden in my heart and tell no one.","gl":[["rekhaa","lines"],["nakhmani","jewel-like nails"]],"no":2},{"id":"ch-189.3","gu":["વહાલા તારા ઉરમાં અનુપમ છાપ, જોવાને જીવ આકળો રે લોલ;","વહાલા મારા હૈડે હરખ ન માય, જાણું જે હમણાં મળો રે લોલ"],"ro":["Vahaalaa taaraa urmaa anupam chhaap, jovaane jiv aaklo re lol;","Vahaalaa maaraa haide harakh na maay, jaanu je hamnaa malo re lol"],"en":"Beloved, there is a matchless mark on your chest, and my soul is restless to see it. Beloved, my heart can't hold its joy; I feel you will meet me right now.","gl":[["chhaap","mark, imprint"],["aaklo","restless"],["harakh","joy"],["hamnaa","right now"]],"no":3},{"id":"ch-189.4","gu":["વહાલા તારું ઉદર અતિ રસરૂપ, શીતળ સદા નાથજી રે લોલ;","આવો ઓરા પ્રેમસખીના પ્રાણ, મળું ભરી બાથજી રે લોલ"],"ro":["Vahaalaa taaru udar ati rasrup, shital sadaa naathji re lol;","Aavo oraa Premsakhinaa praan, malu bhari baathji re lol"],"chhap":1,"en":"Beloved, your belly is the very form of bliss, ever cool, Lord. Come close, life of Premsakhi, let me hold you in a full embrace.","gl":[["udar","belly"],["bhari baath","a full embrace"]],"no":4}],"note":"Premanand Swami sang Vandu Sahajanand before Shriji Maharaj, who praised these songs for dhyan: see Vachanamrut Gadhada II-48."},{"n":190,"id":"ch-190","name":"Vahaalaa taari murti ati rasrup","pad":6,"ref":"Kirtan Muktavali 1-190","poet":"Premanand Swami (as Premsakhi)","section":{"gu":"ધ્યાન ચિંતામણિ","en":"Dhyan Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-190.1","gu":["વહાલા તારી મૂરતિ અતિ રસરૂપ, રસિક જોઈને જીવે રે લોલ;","વહાલા એ રસના ચાખણહાર, કે છાશ તે નવ પીવે રે લોલ"],"ro":["Vahaalaa taari murti ati rasrup, rasik joine jive re lol;","Vahaalaa e rasnaa chaakhanhaar, ke chhaash te nav pive re lol"],"en":"Beloved, your murti is the very form of bliss; those who relish it live by seeing it. Beloved, those who have tasted that nectar do not drink buttermilk.","gl":[["chaakhanhaar","one who has tasted"],["chhaash","buttermilk"]],"note":"Buttermilk after nectar: the world's pleasures after tasting God's form.","no":1},{"id":"ch-190.2","gu":["વહાલા મારે સુખસંપત તમે શ્યામ, મોહન મન ભાવતા રે લોલ;","આવો મારે મંદિર જીવનપ્રાણ, હસીને બોલાવતા રે લોલ"],"ro":["Vahaalaa maare sukhsampat tame shyaam, mohan man bhaavtaa re lol;","Aavo maare mandir jivnapraan, hasine bolaavtaa re lol"],"en":"Beloved Shyam, you are my happiness and my wealth, Mohan dear to my heart; come into my mandir, life of my life, calling to me with a smile.","gl":[["sukhsampat","happiness and wealth"],["mandir","home, and the heart"]],"no":2},{"id":"ch-190.3","gu":["વહાલા તારું રૂપ અનુપમ ગૌર, મૂરતિ મનમાં ગમે રે લોલ;","વહાલા તારું જોબન જોવા કાજ, કે ચિત્ત ચરણે નમે રે લોલ"],"ro":["Vahaalaa taaru rup anupam gaur, murti manmaa game re lol;","Vahaalaa taaru joban jovaa kaaj, ke chitt charne name re lol"],"en":"Beloved, your form is matchless and fair, and your murti delights my mind; Beloved, to see your youthful radiance, my mind bows at your feet.","gl":[["gaur","fair"],["joban","youthful radiance"]],"no":3},{"id":"ch-190.4","gu":["આવો મારા રસિયા રાજીવનેણ, મરમ કરી બોલતા રે લોલ;","આવો વહાલા પ્રેમસખીના સેણ, મંદિર મારે ડોલતા રે લોલ"],"ro":["Aavo maaraa rasiyaa raajivnen, maram kari boltaa re lol;","Aavo vahaalaa Premsakhinaa sen, mandir maare doltaa re lol"],"chhap":1,"en":"Come, my beloved, lotus-eyed one, speaking with hidden meaning; come, Beloved, Premsakhi's dear one, swaying into my mandir.","gl":[["maram","hidden meaning, a playful hint"],["sen","beloved"],["doltaa","swaying"]],"no":4}],"note":"Premanand Swami sang Vandu Sahajanand before Shriji Maharaj, who praised these songs for dhyan: see Vachanamrut Gadhada II-48."},{"n":191,"id":"ch-191","name":"Vahaalaa taaru rup anupam naath","pad":7,"ref":"Kirtan Muktavali 1-191","poet":"Premanand Swami (as Premsakhi)","section":{"gu":"ધ્યાન ચિંતામણિ","en":"Dhyan Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-191.1","gu":["વહાલા તારું રૂપ અનુપમ નાથ, ઉદર શોભા ઘણી રે લોલ;","ત્રિવળી જોઉં સુંદર છેલ, આવોને ઓરા અમ ભણી રે લોલ"],"ro":["Vahaalaa taaru rup anupam naath, udar shobhaa ghani re lol;","Trivli jou sundar chhel, aavone oraa am bhani re lol"],"en":"Beloved, your form is matchless, Lord, and your belly so beautiful; let me see the three folds, my handsome one: come close, toward us.","gl":[["trivli","the three folds at the waist"],["am bhani","toward us"]],"no":1},{"id":"ch-191.2","gu":["વહાલા તારી નાભિ નૌતમ રૂપ, ઊંડી અતિ ગોળ છે રે લોલ;","કટિલંક જોઈને સહજાનંદ, કે મન રંગચોળ છે રે લોલ"],"ro":["Vahaalaa taari naabhi nautam rup, undi ati gol chhe re lol;","Katilank joine Sahajanand, ke man rangchol chhe re lol"],"en":"Beloved, your navel is lovely, deep and perfectly round; seeing your slender waist, Sahajanand, my mind is steeped in its colour.","gl":[["naabhi","navel"],["katilank","the curve of the waist"],["rangchol","deeply dyed, absorbed"]],"no":2},{"id":"ch-191.3","gu":["વહાલા તારી જંઘા જુગલની શોભા, મનમાં જોઈ રહું રે લોલ;","વહાલા નિત નીરખું પિંડી ને પાની, કોઈને નવ કહું રે લોલ"],"ro":["Vahaalaa taari janghaa jugalni shobhaa, manmaa joi rahu re lol;","Vahaalaa nit nirkhu pindi ne paani, koine nav kahu re lol"],"en":"Beloved, I keep seeing in my mind the beauty of your two thighs; Beloved, every day I gaze at your calves and heels, and tell no one.","gl":[["janghaa","thighs"],["pindi","calf"],["paani","heel"]],"no":3},{"id":"ch-191.4","gu":["વહાલા તારા ચરણકમળનું ધ્યાન, ધરું અતિ હેતમાં રે લોલ;","આવો વહાલા પ્રેમસખીના નાથ, રાખું મારા ચિત્તમાં રે લોલ"],"ro":["Vahaalaa taaraa charnakmalnu dhyaan, dharu ati hetmaa re lol;","Aavo vahaalaa Premsakhinaa naath, raakhu maaraa chittamaa re lol"],"chhap":1,"en":"Beloved, I meditate on your lotus feet with great love. Come, Beloved, Lord of Premsakhi; I will keep you in my heart.","gl":[["charnakamal","lotus feet"],["het","love"]],"no":4}],"note":"Premanand Swami sang Vandu Sahajanand before Shriji Maharaj, who praised these songs for dhyan: see Vachanamrut Gadhada II-48."},{"n":192,"id":"ch-192","name":"Vahaalaa taaraa jugal charan rasrup","pad":8,"ref":"Kirtan Muktavali 1-192","poet":"Premanand Swami (as Premsakhi)","section":{"gu":"ધ્યાન ચિંતામણિ","en":"Dhyan Chintamani"},"listen":"https://www.anirdesh.com/kirtan/cheshta.php","stanzas":[{"id":"ch-192.1","gu":["વહાલા તારા જુગલ ચરણ રસરૂપ, વખાણું વહાલમાં રે લોલ;","વહાલા અતિ કોમળ અરુણ રસાળ, ચોરે ચિત્ત ચાલમાં રે લોલ"],"ro":["Vahaalaa taaraa jugal charan rasrup, vakhaanu vahaalmaa re lol;","Vahaalaa ati komal arun rasaal, chore chitt chaalmaa re lol"],"en":"Beloved, lovingly I praise your two feet, the form of bliss; Beloved, so tender, dawn-red and full of sweetness, they steal the mind as you walk.","gl":[["komal","tender"],["rasaal","full of sweetness"],["chaal","walk"]],"no":1},{"id":"ch-192.2","gu":["વહાલા તારે જમણે અંગૂઠે તિલ, કે નખમાં ચિહ્ન છે રે લોલ;","વહાલા છેલી આંગળીએ તિલ એક, જોવાને મન દીન છે રે લોલ"],"ro":["Vahaalaa taare jamne anguthe til, ke nakhmaa chihn chhe re lol;","Vahaalaa chheli aangliye til ek, jovaane man din chhe re lol"],"en":"Beloved, there is a mole on your right big toe, and a mark in its nail; Beloved, there is one mole on your little toe, and my mind humbly longs to see it.","gl":[["chheli aangli","the last, little toe"],["din","humble, longing"]],"no":2},{"id":"ch-192.3","gu":["વહાલા તારા નખની અરુણતા જોઈ, શશીકળા ક્ષીણ છે રે લોલ;","વહાલા રસચોર ચકોર જે ભક્ત, જોવાને પ્રવીણ છે રે લોલ"],"ro":["Vahaalaa taaraa nakhni aruntaa joi, shashiklaa kshin chhe re lol;","Vahaalaa raschor chakor je bhakt, jovaane pravin chhe re lol"],"en":"Beloved, seeing the dawn-red glow of your nails, the crescent moon grows pale; Beloved, devotees who are like the chakor, stealing that nectar, are skilled at seeing it.","gl":[["shashiklaa","the crescent moon"],["kshin","faded, waning"],["chakor","the bird said to live on moonlight"],["raschor","a stealer of nectar"]],"no":3},{"id":"ch-192.4","gu":["વહાલા તારી ઊર્ધ્વરેખામાં ચિત્ત, રહો કરી વાસને રે લોલ;","માગે પ્રેમસખી કર જોડી, દેજો દાન દાસને રે લોલ"],"ro":["Vahaalaa taari urdhvarekhaamaa chitt, raho kari vaasne re lol;","Maage Premsakhi kar jodi, dejo daan daasne re lol"],"chhap":1,"en":"Beloved, may my mind make its home in your urdhvarekha. With folded hands, Premsakhi asks: grant this gift to your servant.","gl":[["vaas","a dwelling"],["kar jodi","with folded hands"],["daan","a gift"]],"no":4}],"note":"Premanand Swami sang Vandu Sahajanand before Shriji Maharaj, who praised these songs for dhyan: see Vachanamrut Gadhada II-48."}]}]};
